    reg [3:0] wptr;
    reg [3:0] rptr;
    reg [3:0] count;
    reg [7:0] mem [0:7];
    reg [7:0] dout;

    integer i;
    initial begin
        wptr  = 4'd0;
        rptr  = 4'd0;
        count = 4'd0;
        dout  = 8'd0;
        for (i = 0; i < 8; i = i + 1)
            mem[i] = 8'd0;
    end

