module rr_chain_arb (
    input  wire       clk,
    input  wire       i_ce,
    input  wire [3:0] req,
    output reg  [3:0] gnt,
    output reg  [1:0] stage
);
    // round-robin arbiter state
    reg [1:0] last_gnt;
    // chain-precedence bookkeeping: arm (line0) -> start (line1) -> finish (line2)
    reg       seen_arm;
    reg       seen_start;
    // sticky scope register: set the first time any grant is issued
    reg       armed;

    initial begin
        last_gnt   = 2'd3;
        gnt        = 4'b0000;
        stage      = 2'd0;
        seen_arm   = 1'b0;
        seen_start = 1'b0;
        armed      = 1'b0;
    end

    // combinational round-robin grant: one-hot, never on a non-requesting line
    reg [3:0] gnt_c;
    always @(*) begin
        case (last_gnt)
            2'd0: gnt_c = req[1] ? 4'b0010 :
                          req[2] ? 4'b0100 :
                          req[3] ? 4'b1000 :
                          req[0] ? 4'b0001 : 4'b0000;
            2'd1: gnt_c = req[2] ? 4'b0100 :
                          req[3] ? 4'b1000 :
                          req[0] ? 4'b0001 :
                          req[1] ? 4'b0010 : 4'b0000;
            2'd2: gnt_c = req[3] ? 4'b1000 :
                          req[0] ? 4'b0001 :
                          req[1] ? 4'b0010 :
                          req[2] ? 4'b0100 : 4'b0000;
            default: gnt_c = req[0] ? 4'b0001 :
                             req[1] ? 4'b0010 :
                             req[2] ? 4'b0100 :
                             req[3] ? 4'b1000 : 4'b0000;
        endcase
    end

    wire [1:0] gnt_idx = gnt_c[0] ? 2'd0 :
                         gnt_c[1] ? 2'd1 :
                         gnt_c[2] ? 2'd2 : 2'd3;

    wire fire = i_ce && (gnt_c != 4'b0000);

    always @(posedge clk) begin
        gnt <= fire ? gnt_c : 4'b0000;
        if (fire) begin
            last_gnt <= gnt_idx;
            armed    <= 1'b1;
            case (stage)
                2'd0: begin
                    if (gnt_c[0]) begin
                        stage    <= 2'd1;   // ARM step
                        seen_arm <= 1'b1;
                    end
                end
                2'd1: begin
                    if (gnt_c[1]) begin
                        stage      <= 2'd2; // START step
                        seen_start <= 1'b1;
                    end else if (gnt_c[3]) begin
                        stage      <= 2'd0; // abort line
                        seen_arm   <= 1'b0;
                        seen_start <= 1'b0;
                    end
                end
                2'd2: begin
                    if (gnt_c[2]) begin
                        stage <= 2'd3;      // FINISH step
                    end else if (gnt_c[3]) begin
                        stage      <= 2'd0; // abort line
                        seen_arm   <= 1'b0;
                        seen_start <= 1'b0;
                    end
                end
                default: begin
                    stage      <= 2'd0;     // retire transaction
                    seen_arm   <= 1'b0;
                    seen_start <= 1'b0;
                end
            endcase
        end
    end

    // P: once the arbiter has ever granted (sticky armed), a finished
    // transaction can only be observed if arm and start really happened.
    always @(posedge clk)
        if (armed && stage == 2'd3)
            assert (seen_arm && seen_start);
endmodule

