module tmr_token_bucket (
    input  wire       i_clk,
    input  wire       i_reset,
    input  wire       i_ce,
    input  wire       i_req,
    input  wire       i_fill,
    output wire       o_grant,
    output wire [3:0] o_tokens
);
    // triple-modular-redundant token counters
    reg [3:0] tokA, tokB, tokC;
    initial tokA = 4'd0;
    initial tokB = 4'd0;
    initial tokC = 4'd0;

    // bitwise majority voter
    wire [3:0] votes = (tokA & tokB) | (tokA & tokC) | (tokB & tokC);

    // spend decision is taken off copy A
    wire take  = i_req && (tokA != 4'd0);
    wire grant = i_ce && take;

    // shadow register recording that a grant was issued earlier
    reg grant_q;
    initial grant_q = 1'b0;

    reg pv;
    initial pv = 1'b0;

    always @(posedge i_clk) begin
        if (i_reset) begin
            tokA <= 4'd0;
            tokB <= 4'd0;
            tokC <= 4'd0;
        end else if (i_ce) begin
            tokA <= (take && (tokA != 4'd0))  ? (tokA - 4'd1)
                  : ((i_fill && !take && (tokA != 4'd15)) ? (tokA + 4'd1) : tokA);
            tokB <= (take && (tokB != 4'd0))  ? (tokB - 4'd1)
                  : ((i_fill && !take && (tokB != 4'd15)) ? (tokB + 4'd1) : tokB);
            tokC <= (take && (tokC != 4'd0))  ? (tokC - 4'd1)
                  : ((i_fill && !take && (tokC != 4'd15)) ? (tokC + 4'd1) : tokC);
        end
    end

    always @(posedge i_clk) begin
        if (i_reset)
            grant_q <= 1'b0;
        else
            grant_q <= grant;
    end

    always @(posedge i_clk)
        pv <= 1'b1;

    assign o_grant  = grant;
    assign o_tokens = votes;

    // Precedence: a grant recorded in the shadow register implies the voted
    // bucket was non-empty in the cycle the grant was issued.
    always @(posedge i_clk)
        if (pv && grant_q)
            assert ($past(votes) != 4'd0);
