// Fixed-latency execution unit with an in-flight occupancy tracker.
// Issued operations march through a 4-deep valid shift register and retire
// from the last stage; the occupancy counter tracks how many are in flight.
module exu_inflight_tracker (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // pipeline advance / idle when low
    input  wire       i_issue,   // issue a new operation this cycle
    input  wire [7:0] i_opnd,
    output wire       o_valid,
    output wire [7:0] o_res,
    output wire [2:0] o_inflight
);

    // latency shift register: one valid bit per pipeline stage
    reg [3:0] pipe;
    // payload pipeline riding alongside
    reg [7:0] d0, d1, d2, d3;
    // occupancy counter (3 bits wide: can hold up to 7)
    reg [2:0] inflight;

    initial begin
        pipe     = 4'b0000;
        d0       = 8'h00;
        d1       = 8'h00;
        d2       = 8'h00;
        d3       = 8'h00;
        inflight = 3'd0;
    end

    wire acc    = i_ce && i_issue;   // accepted issue this cycle
    wire retire = i_ce && pipe[3];   // operation leaving the last stage

    always @(posedge clk) begin
        if (rst) begin
            pipe     <= 4'b0000;
            d0       <= 8'h00;
            d1       <= 8'h00;
            d2       <= 8'h00;
            d3       <= 8'h00;
            inflight <= 3'd0;
        end else if (i_ce) begin
            pipe <= {pipe[2:0], i_issue};
            d0   <= i_opnd;
            d1   <= d0 + 8'd1;
            d2   <= d1 ^ 8'h5a;
            d3   <= d2;

            case ({acc, retire})
                2'b10:   inflight <= inflight + 3'd1;
                2'b01:   inflight <= inflight - 3'd1;
                default: inflight <= inflight;
            endcase
        end
    end

    assign o_valid    = pipe[3];
    assign o_res      = d3;
    assign o_inflight = inflight;

    // P: occupancy of a 4-stage fixed-latency unit never exceeds 4,
    //    even though the counter is 3 bits wide.
    always @(*)
        assert (inflight <= 3'd4);

endmodule


