module skid_stage (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire       flush,
    input  wire       in_valid,
    input  wire [7:0] in_data,
    input  wire       out_ready,
    output wire       in_ready,
    output wire       o_valid,
    output wire [7:0] o_data
);
    // pipeline stage output register
    reg        out_valid;
    reg [7:0]  out_data;
    // skid buffer: the word here is only meaningful while the stall flag is up
    reg        skid_valid;
    reg [7:0]  skid_data;
    // registered backpressure flag
    reg        stall;
    // scope arming register: high until the first flush ever happens
    reg        pre_flush;

    initial out_valid  = 1'b0;
    initial out_data   = 8'h00;
    initial skid_valid = 1'b0;
    initial skid_data  = 8'h00;
    initial stall      = 1'b0;
    initial pre_flush  = 1'b1;

    assign in_ready = !skid_valid;
    assign o_valid  = out_valid;
    assign o_data   = out_data;

    always @(posedge clk) begin
        if (rst) begin
            out_valid  <= 1'b0;
            out_data   <= 8'h00;
            skid_valid <= 1'b0;
            skid_data  <= 8'h00;
            stall      <= 1'b0;
            pre_flush  <= 1'b1;
        end else if (ce) begin
            if (flush) begin
                // flush drops the presented word but leaves the skid buffer alone;
                // this is the event that disarms the scope
                out_valid <= 1'b0;
                pre_flush <= 1'b0;
            end else begin
                stall <= out_valid && !out_ready;
                if (stall) begin
                    if (out_ready) begin
                        if (skid_valid) begin
                            out_data   <= skid_data;
                            out_valid  <= 1'b1;
                            skid_valid <= 1'b0;
                        end else begin
                            out_valid <= in_valid;
                            if (in_valid)
                                out_data <= in_data;
                        end
                    end else if (in_valid && !skid_valid) begin
                        skid_valid <= 1'b1;
                        skid_data  <= in_data;
                    end
                end else begin
                    if (out_ready || !out_valid) begin
                        out_valid <= in_valid;
                        if (in_valid)
                            out_data <= in_data;
                    end
                end
            end
        end
    end

    wire buf_occupied = skid_valid;
    wire stage_empty  = !out_valid;

    // Absence, in the scope before the first flush: the skid buffer is never
    // occupied at the same time as the output stage is empty.
    assert property (!pre_flush || !(buf_occupied && stage_empty));
endmodule

