module rr_coin_arbiter (
    input  wire       clk,
    input  wire       step,
    input  wire [3:0] req,
    output reg  [3:0] gnt,
    output reg  [3:0] last,
    output reg        armed,
    output reg  [5:0] credit,
    output reg        dispense
);
    // Four coin slots compete for the single credit accumulator port.
    // Slots 0,1 drop 5c pieces; slots 2,3 drop 10c pieces.

    initial gnt      = 4'b0000;
    initial last     = 4'b0001;
    initial armed    = 1'b0;
    initial credit   = 6'd0;
    initial dispense = 1'b0;

    // Cyclic priority picks, one per possible position of the last-grant token.
    wire [3:0] sel0 = req[1] ? 4'b0010 : req[2] ? 4'b0100 : req[3] ? 4'b1000 : req[0] ? 4'b0001 : 4'b0000;
    wire [3:0] sel1 = req[2] ? 4'b0100 : req[3] ? 4'b1000 : req[0] ? 4'b0001 : req[1] ? 4'b0010 : 4'b0000;
    wire [3:0] sel2 = req[3] ? 4'b1000 : req[0] ? 4'b0001 : req[1] ? 4'b0010 : req[2] ? 4'b0100 : 4'b0000;
    wire [3:0] sel3 = req[0] ? 4'b0001 : req[1] ? 4'b0010 : req[2] ? 4'b0100 : req[3] ? 4'b1000 : 4'b0000;

    // Round-robin next grant: token in `last` selects which pick is used.
    wire [3:0] nxt = (last[0] ? sel0 : 4'b0000) |
                     (last[1] ? sel1 : 4'b0000) |
                     (last[2] ? sel2 : 4'b0000) |
                     (last[3] ? sel3 : 4'b0000);

    // Coin value of the winning slot (priority-coded so it is at most 10c).
    wire [5:0] coin = (nxt[0] | nxt[1]) ? 6'd5 : ((nxt[2] | nxt[3]) ? 6'd10 : 6'd0);
    wire [6:0] sum  = {1'b0, credit} + {1'b0, coin};

    always @(posedge clk) begin
        if (step) begin
            gnt <= nxt;
            if (|nxt) begin
                last  <= nxt;
                armed <= 1'b1;   // sticky: set the first time a grant is issued
            end
            if (sum >= 7'd25) begin
                credit   <= sum[5:0] - 6'd25;
                dispense <= 1'b1;
            end else begin
                credit   <= sum[5:0];
                dispense <= 1'b0;
            end
        end
    end

    // Once the arbiter has ever granted, two coin slots must never be
    // granted the accumulator port at the same time.
    always @(*)
        assert (!armed || !(gnt[0] && gnt[2]));
endmodule

