module boot_key_debounce (
    input  wire clk,
    input  wire ce,
    input  wire raw_key,
    output wire clean_key,
    output wire menu_armed
);
    // K identical consecutive samples are required before the clean
    // boot-menu key output is allowed to follow the raw input.
    parameter [2:0] K = 3'd6;

    reg       samp;    // last registered raw sample
    reg [2:0] cnt;     // stability counter, saturates at K
    reg       at_k;    // registered decode of (cnt == K-1)
    reg       shadow;  // value captured one step before the commit
    reg       clean;   // debounced output
    reg       armed;   // sticky: set at the first commit, never cleared

    initial begin
        samp   = 1'b0;
        cnt    = 3'd0;
        at_k   = 1'b0;
        shadow = 1'b0;
        clean  = 1'b0;
        armed  = 1'b0;
    end

    wire       match    = (raw_key == samp);
    wire [2:0] next_cnt = (!match) ? 3'd0 : ((cnt < K) ? (cnt + 3'd1) : K);
    wire       commit   = at_k && match;

    always @(posedge clk) if (ce) begin
        samp <= raw_key;
        cnt  <= next_cnt;
        at_k <= (next_cnt == (K - 3'd1));

        // one step before the run completes, record the value that is
        // about to be committed to the clean output
        if (match && (cnt == (K - 3'd2)))
            shadow <= samp;

        // the run of K identical samples completes here
        if (commit) begin
            clean <= shadow;
            armed <= 1'b1;
        end
    end

    assign clean_key  = clean;
    assign menu_armed = armed;

    // Precedence, in the "after first commit" scope: whenever the counter
    // is saturated, the clean output must already carry the value that was
    // shadowed when the stable run was recognised.
    always @(posedge clk)
        if (armed && (cnt == K))
            assert (clean == shadow);
endmodule

