module lfsr_precedence (
    input  wire       clk,
    input  wire       step,      // enable: when low, all state is frozen
    output wire       out_bit,
    output wire [3:0] state_o
);
    // 4-bit maximal-length LFSR, polynomial x^4 + x^3 + 1.
    // Seeded nonzero, so the all-zeros lockup state is never entered.
    reg [3:0] lfsr    = 4'h1;
    reg [3:0] prev    = 4'h8;   // shadow register: the value that preceded lfsr
    reg       stepped = 1'b0;   // records that a shift happened on the last edge

    wire [3:0] nxt = {lfsr[2:0], lfsr[3] ^ lfsr[2]};

    assign out_bit = lfsr[0];
    assign state_o = lfsr;

    always @(posedge clk) begin
        stepped <= step;
        if (step) begin
            prev <= lfsr;   // shadow captures the earlier value
            lfsr <= nxt;
        end
    end

    // Precedence: whenever a shift has just been observed, the value now on the
    // register must differ from the shadowed value that preceded it -- the
    // generator always makes progress.
    always @(posedge clk)
        if (stepped)
            assert (lfsr != prev);

endmodule

