module prienc_owner_guard (
    input  wire       clk,
    input  wire       ce,
    input  wire       abort,
    input  wire [3:0] req,
    output wire       o_lo_owner,
    output wire       o_hi_owner,
    output wire       o_valid
);
    // ---- before-abort scope register: starts high, cleared on first abort ----
    reg armed = 1'b1;

    // ---- stage 1: priority encoder with registered valid flag ----
    reg        vld = 1'b0;
    reg [1:0]  idx = 2'd0;
    reg [3:0]  gnt = 4'b0000;   // registered one-hot shadow of idx

    // ---- stage 2: decoded ownership flags ----
    reg q_lo = 1'b0;
    reg q_hi = 1'b0;
    reg q_v  = 1'b0;
    reg q_z  = 1'b1;

    // combinational priority encoder (lowest index wins)
    wire [1:0] pidx = req[0] ? 2'd0 : req[1] ? 2'd1 : req[2] ? 2'd2 : 2'd3;
    wire [3:0] pgnt = req[0] ? 4'b0001 :
                      req[1] ? 4'b0010 :
                      req[2] ? 4'b0100 :
                      req[3] ? 4'b1000 : 4'b0000;
    wire       pv   = |req;

    always @(posedge clk)
        if (ce && abort)
            armed <= 1'b0;

    always @(posedge clk)
        if (ce) begin
            if (abort && armed) begin
                // broadcast/scan mode entered together with leaving the scope
                vld <= 1'b1;
                idx <= 2'd0;
                gnt <= 4'b1111;
            end else begin
                vld <= pv;
                idx <= pidx;
                gnt <= pgnt;
            end
        end

    always @(posedge clk)
        if (ce) begin
            q_lo <= vld && (idx < 2'd2);
            q_hi <= vld && (|gnt[3:2]);
            q_v  <= vld;
            q_z  <= (gnt == 4'b0000);
        end

    assign o_lo_owner = q_lo;
    assign o_hi_owner = q_hi;
    assign o_valid    = q_v;

    // P1: before any abort, a low-half owner and a high-half owner never coexist
    always @(posedge clk)
        if (armed)
            assert (!(q_lo && q_hi));

    // P2: before any abort, "result valid" and "no grant at all" never coexist
    always @(posedge clk)
        if (armed)
            assert (!(q_v && q_z));
endmodule

