module thermo_div_guard (
    input  wire       clk,
    input  wire       ce,
    input  wire [7:0] temp,
    input  wire       q_arm,
    input  wire       r_done,
    output wire       heat_o,
    output wire       tick_o
);
    localparam [7:0] T_LOW  = 8'd60;
    localparam [7:0] T_HIGH = 8'd80;
    localparam [2:0] DIVM1  = 3'd4;   // divide by 5

    // clock divider: phase counter, divided enable fires on the wrap
    reg [2:0] phase;
    // thermostat state
    reg [7:0] temp_lat;   // temperature sample taken on the divided enable
    reg       heater;     // hysteresis output
    // chatter / inconsistency detectors
    reg       bad_hi;     // heater was on while last sample was above T_HIGH
    reg       bad_lo;     // heater was off while last sample was below T_LOW
    // monitoring window
    reg       win;

    initial phase    = 3'd0;
    initial temp_lat = 8'd70;
    initial heater   = 1'b0;
    initial bad_hi   = 1'b0;
    initial bad_lo   = 1'b0;
    initial win      = 1'b0;

    wire tickw = ce && (phase == DIVM1);

    assign tick_o = tickw;
    assign heat_o = heater;

    always @(posedge clk) if (ce) begin
        phase <= (phase == DIVM1) ? 3'd0 : phase + 3'd1;

        if (tickw) begin
            // sample and apply hysteresis from the same sample
            temp_lat <= temp;
            if (temp < T_LOW)
                heater <= 1'b1;
            else if (temp > T_HIGH)
                heater <= 1'b0;

            // check the previously latched sample against the current output
            if (heater && (temp_lat > T_HIGH))
                bad_hi <= 1'b1;
            if (!heater && (temp_lat < T_LOW))
                bad_lo <= 1'b1;
        end

        // window: opened by q_arm (which also restarts the detectors),
        // closed by r_done; may be opened and closed repeatedly
        if (q_arm) begin
            win    <= 1'b1;
            bad_hi <= 1'b0;
            bad_lo <= 1'b0;
        end else if (r_done)
            win <= 1'b0;
    end

    always @(posedge clk)
        if (win) assert (!bad_hi);

    always @(posedge clk)
        if (win) assert (!bad_lo);
endmodule

