module rr_chain_arb (
    input  wire       clk,
    input  wire       i_ce,
    input  wire [3:0] i_req,
    input  wire       i_start,
    input  wire       i_finish,
    output reg  [3:0] o_grant,
    output reg        o_fin
);
    // phase encoding: 0 = IDLE, 1 = ARMED (grant issued), 2 = RUNNING, 3 = FINISHED
    localparam [1:0] PH_IDLE = 2'd0,
                     PH_ARM  = 2'd1,
                     PH_RUN  = 2'd2,
                     PH_FIN  = 2'd3;

    reg [1:0] last_grant;   // round-robin pointer
    reg [1:0] phase;
    reg [3:0] req_hold;     // request vector latched at grant time
    reg       r_arm_seen;   // this transaction was armed (granted)
    reg       r_start_seen; // this transaction was started
    reg       armed_q;      // sticky: an arbitration has happened at least once

    initial begin
        last_grant   = 2'd0;
        phase        = PH_IDLE;
        o_grant      = 4'b0000;
        o_fin        = 1'b0;
        req_hold     = 4'b0000;
        r_arm_seen   = 1'b0;
        r_start_seen = 1'b0;
        armed_q      = 1'b0;
    end

    // ---- round robin winner select, starting just after last_grant ----
    wire [1:0] c1 = last_grant + 2'd1;
    wire [1:0] c2 = last_grant + 2'd2;
    wire [1:0] c3 = last_grant + 2'd3;

    reg [1:0] win;
    reg       any;

    always @(*) begin
        any = 1'b1;
        if      (i_req[c1])         win = c1;
        else if (i_req[c2])         win = c2;
        else if (i_req[c3])         win = c3;
        else if (i_req[last_grant]) win = last_grant;
        else begin
            win = last_grant;
            any = 1'b0;
        end
    end

    // ---- arm / start / finish chain ----
    always @(posedge clk) begin
        if (i_ce) begin
            case (phase)
                PH_IDLE: begin
                    if (any) begin
                        o_grant      <= (4'b0001 << win);
                        last_grant   <= win;
                        req_hold     <= i_req;
                        phase        <= PH_ARM;
                        r_arm_seen   <= 1'b1;
                        armed_q      <= 1'b1;
                    end
                end
                PH_ARM: begin
                    if (i_start) begin
                        phase        <= PH_RUN;
                        r_start_seen <= 1'b1;
                    end
                end
                PH_RUN: begin
                    if (i_finish) begin
                        phase        <= PH_FIN;
                        o_fin        <= 1'b1;
                    end
                end
                PH_FIN: begin
                    phase        <= PH_IDLE;
                    o_grant      <= 4'b0000;
                    o_fin        <= 1'b0;
                    req_hold     <= 4'b0000;
                    r_arm_seen   <= 1'b0;
                    r_start_seen <= 1'b0;
                end
            endcase
        end
    end

    // Chain precedence, only required once arbitration has ever occurred:
    // a completion can never be observed unless this transaction was armed
    // and then started.
    always @(posedge clk)
        if (armed_q && o_fin)
            assert (r_start_seen && r_arm_seen);

endmodule

