module pingpong_dbuf (
    input  wire       clk,
    input  wire       rst,
    input  wire       en,
    input  wire       push,
    input  wire       pop,
    output wire       wr_full,
    output wire       rd_empty,
    output wire [3:0] occupancy,
    output wire       half_swapped
);
    // ping-pong double buffer: two halves of 4 entries each.
    // wsel selects the half the writer fills, rsel the half the reader drains;
    // they are flipped together so the two agents never touch the same half.
    reg       wsel  = 1'b0;
    reg       rsel  = 1'b1;
    reg [2:0] cnt0  = 3'd0;   // entries resident in half 0
    reg [2:0] cnt1  = 3'd0;   // entries resident in half 1
    reg [3:0] total = 4'd0;   // shadow occupancy accumulator
    reg       armed = 1'b0;   // sticky: set at the first buffer swap, never cleared
    reg       pv    = 1'b0;

    wire [2:0] wcnt = wsel ? cnt1 : cnt0;
    wire [2:0] rcnt = rsel ? cnt1 : cnt0;

    assign wr_full   = (wcnt == 3'd4);
    assign rd_empty  = (rcnt == 3'd0);
    assign occupancy = total;

    wire do_swap = wr_full && rd_empty;
    wire do_push = push && !wr_full && !do_swap;
    wire do_pop  = pop  && !rd_empty && !do_swap;

    assign half_swapped = en && do_swap;

    always @(posedge clk)
        pv <= 1'b1;

    // arm register: latched on the first swap, never cleared afterwards
    always @(posedge clk)
        if (!rst && en && do_swap)
            armed <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            wsel  <= 1'b0;
            rsel  <= 1'b1;
            cnt0  <= 3'd0;
            cnt1  <= 3'd0;
            total <= 4'd0;
        end else if (en) begin
            if (do_swap) begin
                wsel <= ~wsel;
                rsel <= ~rsel;
            end else begin
                if (do_push) begin
                    if (wsel) cnt1 <= cnt1 + 3'd1;
                    else      cnt0 <= cnt0 + 3'd1;
                end
                if (do_pop) begin
                    if (rsel) cnt1 <= cnt1 - 3'd1;
                    else      cnt0 <= cnt0 - 3'd1;
                end
                total <= total + (do_push ? 4'd1 : 4'd0) - (do_pop ? 4'd1 : 4'd0);
            end
        end
    end

    // P: once the buffer has swapped at least once, every rising edge of the
    // writer-full flag must find the accumulated occupancy at or below 8,
    // even though the accumulator is 4 bits wide.
    always @(posedge clk)
        if (pv && armed && $rose(wr_full))
            assert (total <= 4'd8);
endmodule

