module pslice_check (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire [7:0] data_in,
    output wire [7:0] data_out,
    output wire       par_out,
    output wire       val_out,
    output wire [5:0] o_chk_cnt,
    output wire [5:0] o_ok_cnt
);
    // input register slice, protected by a stored parity bit
    reg [7:0] s0_data;
    reg       s0_par;
    reg       s0_val;

    // output register slice, carries the same protection
    reg [7:0] s1_data;
    reg       s1_par;
    reg       s1_val;

    // retirement bookkeeping
    reg [5:0] chk_cnt;
    reg [5:0] ok_cnt;

    initial begin
        s0_data = 8'h00;
        s0_par  = 1'b0;
        s0_val  = 1'b0;
        s1_data = 8'h00;
        s1_par  = 1'b0;
        s1_val  = 1'b0;
        chk_cnt = 6'd0;
        ok_cnt  = 6'd0;
    end

    // parity checker sitting between the two slices
    wire s0_bad = s0_val && (s0_par ^ (^s0_data));

    always @(posedge clk) begin
        if (rst) begin
            s0_data <= 8'h00;
            s0_par  <= 1'b0;
            s0_val  <= 1'b0;
            s1_data <= 8'h00;
            s1_par  <= 1'b0;
            s1_val  <= 1'b0;
            chk_cnt <= 6'd0;
            ok_cnt  <= 6'd0;
        end else if (ce) begin
            // fill slice 0 with fresh data and its generated parity
            s0_data <= data_in;
            s0_par  <= ^data_in;
            s0_val  <= 1'b1;

            // hand slice 0 over to slice 1, parity travels with the data
            s1_data <= s0_data;
            s1_par  <= s0_par;
            s1_val  <= s0_val;

            // count every retired beat, and separately the clean ones
            if (s0_val) begin
                chk_cnt <= chk_cnt + 6'd1;
                if (!s0_bad)
                    ok_cnt <= ok_cnt + 6'd1;
            end
        end
    end

    assign data_out  = s1_data;
    assign par_out   = s1_par;
    assign val_out   = s1_val;
    assign o_chk_cnt = chk_cnt;
    assign o_ok_cnt  = ok_cnt;

    // P: every retired beat was a clean beat
    always @(*)
        assert (ok_cnt == chk_cnt);
endmodule

