// Transaction scoreboard: arm (credit allocated) -> start (issue) -> finish (retire).
// Retired never exceeds issued, issued never exceeds armed, and each gap is
// bounded by the window WIN.
module txn_scoreboard (
    input  wire       clk,
    input  wire       ce,        // idle when low: no state changes at all
    input  wire       arm_req,
    input  wire       start_req,
    input  wire       fin_req,
    output reg  [3:0] alloc_cnt,
    output reg  [3:0] iss_cnt,
    output reg  [3:0] ret_cnt
);
    localparam [2:0] WIN = 3'd4;

    // credit registers: armed-but-not-started, started-but-not-finished
    reg [2:0] pend_iss;
    reg [2:0] outstanding;

    reg pv;

    initial begin
        alloc_cnt   = 4'd0;
        iss_cnt     = 4'd0;
        ret_cnt     = 4'd0;
        pend_iss    = 3'd0;
        outstanding = 3'd0;
        pv          = 1'b0;
    end

    // the chain is enforced purely through the credit registers
    wire do_arm   = ce && arm_req   && (pend_iss    <  WIN);
    wire do_start = ce && start_req && (pend_iss    != 3'd0) && (outstanding < WIN);
    wire do_fin   = ce && fin_req   && (outstanding != 3'd0);

    always @(posedge clk) begin
        pv <= 1'b1;

        if (do_arm)   alloc_cnt <= alloc_cnt + 4'd1;
        if (do_start) iss_cnt   <= iss_cnt   + 4'd1;
        if (do_fin)   ret_cnt   <= ret_cnt   + 4'd1;

        case ({do_arm, do_start})
            2'b10:   pend_iss <= pend_iss + 3'd1;
            2'b01:   pend_iss <= pend_iss - 3'd1;
            default: pend_iss <= pend_iss;
        endcase

        case ({do_start, do_fin})
            2'b10:   outstanding <= outstanding + 3'd1;
            2'b01:   outstanding <= outstanding - 3'd1;
            default: outstanding <= outstanding;
        endcase
    end

    // P (chain precedence, no-change form): a start cannot be observed unless an
    // arm got ahead of the issue counter, and a finish cannot be observed unless
    // a start got ahead of the retire counter.
    always @(posedge clk)
        if (pv)
            assert (((($past(alloc_cnt) != $past(iss_cnt))) || $stable(iss_cnt)) &&
                    ((($past(iss_cnt)   != $past(ret_cnt))) || $stable(ret_cnt)));
endmodule

