module boot_prio_sched (
    input  wire       clk,
    input  wire       i_ce,      // scheduler tick enable; low => full idle
    input  wire       i_flush,   // end of the boot round
    input  wire [7:0] i_req,     // dynamic requests, admitted only after flush
    output wire       o_valid,
    output wire [2:0] o_index,
    output wire [2:0] o_count
);

    // ---------------- state ----------------
    reg [7:0] pending;      // outstanding boot/thread requests
    reg [2:0] o_index_r;    // encoded index, meaningful only while valid
    reg       o_valid_r;    // registered valid flag
    reg [2:0] grant_count;  // retired grants (saturating)
    reg       pre_flush;    // arming register: high until first flush tick

    initial pending     = 8'h0F;   // four statically pinned boot threads
    initial o_index_r   = 3'd0;
    initial o_valid_r   = 1'b0;
    initial grant_count = 3'd0;
    initial pre_flush   = 1'b1;

    // ------------- priority encoder (combinational) -------------
    wire       req_any = |pending;
    reg  [2:0] enc;
    always @(*) begin
        if      (pending[0]) enc = 3'd0;
        else if (pending[1]) enc = 3'd1;
        else if (pending[2]) enc = 3'd2;
        else if (pending[3]) enc = 3'd3;
        else if (pending[4]) enc = 3'd4;
        else if (pending[5]) enc = 3'd5;
        else if (pending[6]) enc = 3'd6;
        else                 enc = 3'd7;
    end

    wire [7:0] gmask = req_any ? (8'h01 << enc) : 8'h00;
    wire [7:0] admit = (!pre_flush) ? i_req : 8'h00;

    // ------------- sequential core -------------
    always @(posedge clk) begin
        if (i_ce) begin
            if (i_flush) begin
                // open the scheduler up: all slots become requestable
                pending   <= 8'hFF;
                o_valid_r <= 1'b0;
                pre_flush <= 1'b0;
            end else begin
                pending   <= (pending & ~gmask) | admit;
                o_valid_r <= req_any;
                if (req_any)
                    o_index_r <= enc;
                if (o_valid_r)
                    grant_count <= (grant_count == 3'd7) ? 3'd7
                                                         : grant_count + 3'd1;
            end
        end
    end

    assign o_valid = o_valid_r;
    assign o_index = o_index_r;
    assign o_count = grant_count;

    // ------------- property -------------
    // Before the scheduler has ever been flushed, and while a grant is
    // actually presented, at most three grants can already have retired.
    always @(posedge clk)
        if (pre_flush && o_valid_r)
            assert (grant_count <= 3'd3);

endmodule

