module cdc_alu_req (
    input  wire       clk,
    input  wire       ce,
    input  wire       start,
    input  wire [1:0] op,
    input  wire [7:0] a,
    input  wire [7:0] b,
    output reg  [7:0] result,
    output reg        carry,
    output reg        zero,
    output reg        busy
);
    // gray-coded request pointer crossing into the ALU domain
    reg [1:0] wbin  = 2'd0;
    reg [1:0] wgray = 2'b00;
    // two-flop synchronizer
    reg [1:0] s1    = 2'b00;
    reg [1:0] s2    = 2'b00;
    // last pointer value acknowledged on the far side
    reg [1:0] seen  = 2'b00;
    // bounded-response countdown
    reg [1:0] cnt   = 2'd0;
    // latched operands
    reg [7:0] opa   = 8'd0;
    reg [7:0] opb   = 8'd0;
    reg [1:0] opr   = 2'd0;

    initial begin
        busy   = 1'b0;
        result = 8'd0;
        carry  = 1'b0;
        zero   = 1'b0;
    end

    wire [1:0] wbin_nxt  = wbin + 2'd1;
    wire [1:0] wgray_nxt = (wbin_nxt >> 1) ^ wbin_nxt;

    wire issue = ce && start && !busy;
    wire done  = ce && busy && (s2 != seen);

    wire [8:0] sum = {1'b0, opa} + {1'b0, opb};
    wire [8:0] dif = {1'b0, opa} - {1'b0, opb};

    reg [8:0] alu;
    always @(*) begin
        case (opr)
            2'd0:    alu = sum;
            2'd1:    alu = dif;
            2'd2:    alu = {1'b0, opa & opb};
            default: alu = {1'b0, opa | opb};
        endcase
    end

    always @(posedge clk) begin
        if (ce) begin
            s1 <= wgray;
            s2 <= s1;
            if (issue) begin
                wbin  <= wbin_nxt;
                wgray <= wgray_nxt;
                opa   <= a;
                opb   <= b;
                opr   <= op;
                busy  <= 1'b1;
                cnt   <= 2'd3;
            end else if (done) begin
                seen   <= s2;
                busy   <= 1'b0;
                cnt    <= 2'd0;
                result <= alu[7:0];
                carry  <= alu[8];
                zero   <= (alu[7:0] == 8'd0);
            end else if (busy) begin
                cnt <= cnt - 2'd1;
            end
        end
    end

    // Bounded response: the countdown must never expire while a request is
    // still outstanding (window opened by accept, closed by completion).
    always @(posedge clk)
        if (busy)
            assert (cnt != 2'd0);
endmodule

