module gray_chain_seq (
    input  wire clk,
    input  wire rst,
    input  wire ce,
    output wire o_armed,
    output wire o_started,
    output wire o_done
);
    // three-step chain: arm, start, finish
    localparam [1:0] S_IDLE    = 2'd0,
                     S_ARMED   = 2'd1,
                     S_STARTED = 2'd2,
                     S_DONE    = 2'd3;

    // gray codes of the milestone binary counts 3, 7 and 12
    localparam [3:0] G_ARM   = 4'b0010; // gray(3)
    localparam [3:0] G_START = 4'b0100; // gray(7)
    localparam [3:0] G_FIN   = 4'b1010; // gray(12)

    reg [3:0] bin;
    reg [3:0] gray;   // gray-code counter, shadowed by bin
    reg [1:0] stage;

    initial bin   = 4'd0;
    initial gray  = 4'd0;
    initial stage = S_IDLE;

    // saturating binary shadow
    wire [3:0] nbin = (bin == 4'd15) ? 4'd15 : (bin + 4'd1);

    always @(posedge clk) begin
        if (rst) begin
            bin   <= 4'd0;
            gray  <= 4'd0;
            stage <= S_IDLE;
        end else if (ce) begin
            bin  <= nbin;
            gray <= nbin ^ (nbin >> 1);
            case (stage)
                S_IDLE:    if (gray == G_ARM)   stage <= S_ARMED;
                S_ARMED:   if (gray == G_START) stage <= S_STARTED;
                S_STARTED: if (gray == G_FIN)   stage <= S_DONE;
                default:                        stage <= S_DONE;
            endcase
        end
    end

    assign o_armed   = (stage != S_IDLE);
    assign o_started = (stage == S_STARTED) || (stage == S_DONE);
    assign o_done    = (stage == S_DONE);

    // P: the finish step can only be observed after the whole chain ran,
    // i.e. the binary shadow must already be past the finish milestone.
    always @(posedge clk)
        if (stage == S_DONE)
            assert (bin >= 4'd12);

endmodule

