    reg [3:0] bin;
    reg [3:0] gray;

    // profiling bucket flags, sampled from the two representations
    reg       flag_hi;   // sampled from the gray view
    reg       flag_lo;   // sampled from the binary view

    // sticky arming register: set the first time a profiling run starts
    reg       armed;

    initial bin     = 4'd0;
    initial gray    = 4'd0;
    initial flag_hi = 1'b0;
    initial flag_lo = 1'b0;
    initial armed   = 1'b0;

    wire [3:0] bin_next = bin + 4'd1;

    always @(posedge i_clk) begin
        if (i_reset) begin
            bin     <= 4'd0;
            gray    <= 4'd0;
            flag_hi <= 1'b0;
            flag_lo <= 1'b0;
            armed   <= 1'b0;
        end else if (i_ce) begin
            bin     <= bin_next;
            gray    <= bin_next ^ (bin_next >> 1);
            // hi bucket recognised from the gray encoding of sample 8
            flag_hi <= (gray == 4'b1100);
            // lo bucket recognised directly from the binary shadow
            flag_lo <= (bin < 4'd8);
            if (i_start)
                armed <= 1'b1;
