module fetch_skid_stage (
    input  wire       clk,
    input  wire       rst,
    input  wire       in_valid,
    input  wire [7:0] in_data,
    input  wire       out_ready,
    output wire       in_ready,
    output reg        out_valid,
    output reg [7:0]  out_data
);
    // ---- skid buffer of a valid/ready instruction-fetch pipeline stage ----
    reg       skid_valid;
    reg [7:0] skid_data;   // only meaningful while skid_valid (stall flag) is up
    reg [2:0] occ;         // shadow occupancy counter
    reg       armed;       // sticky: set the first time back-pressure stalls us

    initial begin
        out_valid  = 1'b0;
        out_data   = 8'h00;
        skid_valid = 1'b0;
        skid_data  = 8'h00;
        occ        = 3'd0;
        armed      = 1'b0;
    end

    assign in_ready = !skid_valid;

    wire in_fire   = in_valid  && in_ready;
    wire out_fire  = out_valid && out_ready;
    wire capture   = in_fire && out_valid && !out_ready; // stall: park word in skid
    wire drain     = !out_valid || out_ready;            // output slot becomes free

    always @(posedge clk) begin
        if (rst) begin
            out_valid  <= 1'b0;
            out_data   <= 8'h00;
            skid_valid <= 1'b0;
            skid_data  <= 8'h00;
            occ        <= 3'd0;
        end else begin
            if (capture) begin
                skid_valid <= 1'b1;
                skid_data  <= in_data;
            end

            if (drain) begin
                if (skid_valid) begin
                    out_valid  <= 1'b1;
                    out_data   <= skid_data;
                    skid_valid <= 1'b0;
                end else if (in_fire) begin
                    out_valid  <= 1'b1;
                    out_data   <= in_data;
                end else begin
                    out_valid  <= 1'b0;
                end
            end

            // occupancy bookkeeping
            if (in_fire && !out_fire)
                occ <= occ + 3'd1;
            else if (!in_fire && out_fire)
                occ <= occ - 3'd1;
        end
    end

    // sticky arm: first stall event, never cleared (not even by reset)
    always @(posedge clk) begin
        if (capture)
            armed <= 1'b1;
    end

    // P: once the stage has ever stalled, the tracked occupancy never exceeds
    //    the two physical slots (output register + skid buffer).
    always @(*)
        assert (!armed || (occ <= 3'd2));
endmodule

