module onehot_pipe_gauge (
    input  wire clk,
    input  wire rst,
    input  wire step,
    input  wire start,
    output wire busy,
    output wire [2:0] o_cnt
);
    // one-hot pipeline walker: S0 -> S1 -> S2 -> S3 -> S4 -> S0
    localparam [4:0] S0 = 5'b00001,
                     S1 = 5'b00010,
                     S2 = 5'b00100,
                     S3 = 5'b01000,
                     S4 = 5'b10000;

    reg [4:0] st;
    reg [2:0] cnt;   // stage gauge: how far down the pipe we are
    reg       pv;

    initial st  = S0;
    initial cnt = 3'd0;
    initial pv  = 1'b0;

    // advance / clear terms are only mutually exclusive because st is one-hot
    wire adv = st[1] | st[2] | st[3];
    wire clr = st[0] | st[4];

    reg [4:0] nxt;
    always @(*) begin
        nxt = 5'b00000;
        if (st[0]) nxt = nxt | (start ? S1 : S0);
        if (st[1]) nxt = nxt | S2;
        if (st[2]) nxt = nxt | S3;
        if (st[3]) nxt = nxt | S4;
        if (st[4]) nxt = nxt | S0;
    end

    always @(posedge clk) begin
        if (rst) begin
            st  <= S0;
            cnt <= 3'd0;
        end else if (step) begin
            st <= nxt;
            if (adv)
                cnt <= cnt + 3'd1;
            else if (clr)
                cnt <= 3'd0;
        end
    end

    always @(posedge clk)
        pv <= 1'b1;

    assign busy  = |st[4:1];
    assign o_cnt = cnt;

    // P: while the one-hot state does not change, the stage gauge must not
    //    change either, and it never exceeds 3 (its width allows 7).
    always @(posedge clk)
        if (pv && $stable(st))
            assert ($stable(cnt) && cnt <= 3'd3);
endmodule

