        if (rst) begin
            busy       <= 1'b0;
            beats      <= 4'd0;
            words_sent <= 4'd0;
            len_reg    <= 4'd0;
            addr       <= 28'd0;
        end else if (ce) begin
            if (busy) begin
                // issue one beat
                beats      <= beats - 4'd1;
                words_sent <= words_sent + 4'd1;
                addr       <= addr + 28'd4;
                if (beats == 4'd1)
                    busy <= 1'b0;
            end else if (start_ok) begin
                // accept a new burst descriptor
                busy       <= 1'b1;
                beats      <= i_len;
                words_sent <= 4'd0;
                len_reg    <= i_len;
                addr       <= i_addr;
            end
        end
        // ce low: engine stalls, every register holds its value
