// PWM generator with a period counter, a duty register and a
// deadline-tracked duty update request.
module pwm_duty_update (
    input  wire       clk,
    input  wire       i_ce,      // idle when low: all state frozen
    input  wire       i_req,     // request a new duty value
    input  wire [3:0] i_duty,
    output wire       o_pwm,
    output reg        o_applied
);
    // period counter: free running 0..15 while enabled
    reg [3:0] cnt;
    // live duty and the shadow copy waiting for the period boundary
    reg [3:0] duty;
    reg [3:0] duty_next;
    // outstanding update request and its countdown to completion
    reg       pending;
    reg [4:0] deadline;
    // sticky arm: set the first time a request is accepted, never cleared
    reg       armed;
    reg       pv;

    initial begin
        cnt       = 4'd0;
        duty      = 4'd0;
        duty_next = 4'd0;
        pending   = 1'b0;
        deadline  = 5'd0;
        armed     = 1'b0;
        pv        = 1'b0;
        o_applied = 1'b0;
    end

    wire at_end = (cnt == 4'd15);
    wire accept = i_ce && i_req && !pending;
    wire apply  = i_ce && pending && at_end;

    // output is high exactly while the counter is below the duty value
    assign o_pwm = (cnt < duty);

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (i_ce) begin
            cnt       <= cnt + 4'd1;
            o_applied <= apply;
            if (accept) begin
                pending   <= 1'b1;
                armed     <= 1'b1;
                duty_next <= i_duty;
                // cycles remaining, measured from the next state, until wrap
                deadline  <= at_end ? 5'd16 : (5'd15 - {1'b0, cnt});
            end else if (apply) begin
                pending   <= 1'b0;
                duty      <= duty_next;
                deadline  <= 5'd0;
            end else if (pending) begin
                deadline  <= deadline - 5'd1;
            end
        end
    end

    // Bounded response (safety): once the updater has ever been armed, the
    // countdown must never have been expired while a request was outstanding.
    always @(posedge clk)
