// saturating event counter with full/empty status flags
module sat_counter_flags (
    input  wire clk,
    input  wire i_rst,
    input  wire i_ce,
    output wire o_full,
    output wire o_empty
);
    parameter [3:0] MAX = 4'd10;

    reg [3:0] cnt;
    reg       at_max;   // "full"  status flag
    reg       at_min;   // "empty" status flag
    reg       pv;       // past-valid

    initial cnt    = 4'd0;
    initial at_max = 1'b0;
    initial at_min = 1'b1;
    initial pv     = 1'b0;

    // saturating next value: clamps at MAX, well below 4'd15
    wire [3:0] nxt = (cnt >= MAX) ? MAX : (cnt + 4'd1);

    always @(posedge clk)
        pv <= 1'b1;

    always @(posedge clk) begin
        if (i_rst) begin
            cnt    <= 4'd0;
            at_max <= 1'b0;
            at_min <= 1'b1;
        end else if (i_ce) begin
            cnt    <= nxt;
            at_max <= (nxt == MAX);
            at_min <= (nxt == 4'd0);
        end
    end

    assign o_full  = at_max;
    assign o_empty = at_min;

    // P: the counter holding still and a status flag moving are never
    //    true at the same time
    always @(posedge clk)
        if (pv && $stable(cnt))
            assert ($stable(at_max) && $stable(at_min));

endmodule

