module strsearch_match_queue (
    input  wire       clk,
    input  wire       ce,        // global enable / idle when low
    input  wire       start,     // opens the search window (Q)
    input  wire       finish,    // closes the search window (R)
    input  wire       load,      // report a fresh batch of character matches
    input  wire [7:0] load_mask, // positions in the string that matched
    input  wire       pop,       // consume the currently encoded position
    output reg        busy,      // window register
    output reg        idx_valid, // registered valid flag of the priority encoder
    output reg  [2:0] idx        // encoded position, meaningful only while valid
);

    // pending match positions still to be emitted
    reg [7:0] pend;
    // shadow register: every position ever loaded during the current window
    reg [7:0] loaded;

    initial busy      = 1'b0;
    initial idx_valid = 1'b0;
    initial idx       = 3'd0;
    initial pend      = 8'b0;
    initial loaded    = 8'b0;

    // combinational priority encoder (lowest string position wins)
    function [2:0] lowest_set;
        input [7:0] m;
        begin
            if      (m[0]) lowest_set = 3'd0;
            else if (m[1]) lowest_set = 3'd1;
            else if (m[2]) lowest_set = 3'd2;
            else if (m[3]) lowest_set = 3'd3;
            else if (m[4]) lowest_set = 3'd4;
            else if (m[5]) lowest_set = 3'd5;
            else if (m[6]) lowest_set = 3'd6;
            else           lowest_set = 3'd7;
        end
    endfunction

    reg [7:0] nxt_pend;
    always @(*) begin
        nxt_pend = pend;
        if (pop && idx_valid)
            nxt_pend = nxt_pend & ~(8'b1 << idx);
        if (load)
            nxt_pend = nxt_pend | load_mask;
    end

    always @(posedge clk) begin
        if (ce) begin
            if (start) begin
                busy      <= 1'b1;
                pend      <= 8'b0;
                loaded    <= 8'b0;
                idx       <= 3'd0;
                idx_valid <= 1'b0;
            end else if (finish) begin
                busy      <= 1'b0;
                pend      <= 8'b0;
                loaded    <= 8'b0;
                idx       <= 3'd0;
                idx_valid <= 1'b0;
            end else if (busy) begin
                pend      <= nxt_pend;
                if (load)
                    loaded <= loaded | load_mask;
                idx_valid <= |nxt_pend;
                idx       <= lowest_set(nxt_pend);
            end
        end
    end

    // Precedence, scoped between start and finish: a position emitted by the
    // encoder must have been reported as a match earlier in this window.
    always @(posedge clk)
        if (busy && idx_valid)
            assert (loaded[idx]);

endmodule

