module irq_priority_grant (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire [7:0] req,
    output reg  [7:0] pending,
    output reg  [7:0] ever_req,
    output reg  [2:0] grant_idx,
    output reg        grant_valid
);

    // Requests currently outstanding plus whatever arrives this cycle
    wire [7:0] sel = pending | req;

    // Combinational priority encoder: lowest index wins
    reg [2:0] enc_idx;
    reg       enc_valid;
    integer   i;
    always @(*) begin
        enc_idx   = 3'd0;
        enc_valid = 1'b0;
        for (i = 7; i >= 0; i = i - 1) begin
            if (sel[i]) begin
                enc_idx   = i;
                enc_valid = 1'b1;
            end
        end
    end

    initial pending     = 8'd0;
    initial ever_req    = 8'd0;  // shadow: every line that has ever asserted
    initial grant_idx   = 3'd0;
    initial grant_valid = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            pending     <= 8'd0;
            ever_req    <= 8'd0;
            grant_idx   <= 3'd0;
            grant_valid <= 1'b0;
        end else if (ce) begin
            ever_req    <= ever_req | req;
            grant_valid <= enc_valid;
            grant_idx   <= enc_idx;
            if (enc_valid)
                pending <= sel & ~(8'd1 << enc_idx);
            else
                pending <= 8'd0;
        end
    end

    // The encoded index is only meaningful while grant_valid is set:
    // whenever a grant is presented, that line must have requested earlier.
    always @(*)
        assert (!grant_valid || ever_req[grant_idx]);

endmodule

