module sat_watermark_flags (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,
    input  wire       i_inc,
    input  wire       i_clear,
    output wire [3:0] o_count,
    output wire       o_full,
    output wire       o_empty
