// Ping-pong (double) buffer fill engine with a completion deadline counter.
// The writer owns half `sel`, the reader owns half `rsel`; they are never the
// same half.  Each accepted fill request is guaranteed to finish within DEPTH
// enabled cycles by the countdown register `ttl`; `err_r` latches the (never
// occurring) event "countdown expired while the request is still outstanding".
module pingpong_deadline (
    input  wire       clk,
    input  wire       ce,      // global enable: low => all state frozen
    input  wire       start,   // request a new half-buffer fill
    input  wire [7:0] wdata,
    input  wire       rd,      // reader consumes a word from the other half
    output wire [7:0] rdata,
    output wire       err
);
    localparam [3:0] DEPTH = 4'd8;

    reg        sel   = 1'b0;   // half currently owned by the writer
    reg        rsel  = 1'b1;   // half currently owned by the reader
    reg        busy  = 1'b0;   // fill request outstanding
    reg  [3:0] wcnt  = 4'd0;   // words written into the writer half
    reg  [3:0] ttl   = 4'd0;   // countdown to the completion deadline
    reg  [3:0] rcnt  = 4'd0;   // reader index into its half
    reg        rvld  = 1'b0;   // reader half holds a complete frame
    reg        err_r = 1'b0;   // deadline expired while still outstanding

    reg  [7:0] mem0 [0:7];
    reg  [7:0] mem1 [0:7];

    integer i;
    initial begin
        for (i = 0; i < 8; i = i + 1) begin
            mem0[i] = 8'd0;
            mem1[i] = 8'd0;
        end
    end

    wire accept  = ce && start && !busy;
    wire wstep   = ce && busy;
    wire wlast   = wstep && (wcnt == 4'd7);
    wire expired = wstep && (ttl == 4'd0);

    assign rdata = rsel ? mem1[rcnt[2:0]] : mem0[rcnt[2:0]];
    assign err   = err_r;

    // data path: writer only ever touches half `sel`
    always @(posedge clk) begin
        if (wstep) begin
            if (sel) mem1[wcnt[2:0]] <= wdata;
            else     mem0[wcnt[2:0]] <= wdata;
        end
    end

    // control path
    always @(posedge clk) begin
        if (expired)
            err_r <= 1'b1;

        if (accept) begin
            busy <= 1'b1;
            wcnt <= 4'd0;
            ttl  <= DEPTH;
        end else if (wlast) begin
            busy <= 1'b0;
            wcnt <= 4'd0;
            ttl  <= 4'd0;
            sel  <= ~sel;      // writer swaps to the other half
            rsel <= sel;       // reader takes over the half just filled
            rcnt <= 4'd0;
            rvld <= 1'b1;
        end else if (wstep) begin
            wcnt <= wcnt + 4'd1;
            ttl  <= ttl  - 4'd1;
        end

        if (ce && rd && rvld && !wlast) begin
            if (rcnt == 4'd7) begin
                rcnt <= 4'd0;
                rvld <= 1'b0;
            end else begin
                rcnt <= rcnt + 4'd1;
            end
        end
    end

    // past-valid guard
    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    // P: bounded response, safety form -- while the request stayed outstanding
    // (busy did not change), the deadline-expiry flag must not have changed.
    always @(posedge clk)
        if (pv && $stable(busy))
            assert ($stable(err_r));
endmodule

