module wdog_bounded (
    input  wire clk,
    input  wire rst,     // synchronous reset
    input  wire ce,      // timebase enable: when low the whole watchdog idles
    input  wire kick,    // software pets the dog
    output wire o_bark,  // timeout reached, reset request to the host
    output wire o_armed
);
    // The watchdog counts timebase ticks since the last kick.  When it reaches
    // LIMIT it latches the bark flag and freezes; only a kick (or reset)
    // restarts it.  Note the freeze is decided by the latched flag, not by a
    // fresh comparison against LIMIT.
    parameter [4:0] LIMIT = 5'd20;

    reg [4:0] wdt;
    reg       expired;
    reg       armed;   // sticky: set the first time the dog is ever kicked

    initial wdt     = 5'd0;
    initial expired = 1'b0;
    initial armed   = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            wdt     <= 5'd0;
            expired <= 1'b0;
            armed   <= 1'b0;
        end else if (ce) begin
            if (kick) begin
                wdt     <= 5'd0;
                expired <= 1'b0;
                armed   <= 1'b1;
            end else if (!expired) begin
                wdt <= wdt + 5'd1;
                if ((wdt + 5'd1) == LIMIT)
                    expired <= 1'b1;
            end
        end
    end

    assign o_bark  = expired;
    assign o_armed = armed;

    // Property: once the watchdog has been armed by a first kick, the elapsed
    // tick count never exceeds the programmed timeout, even though the counter
    // is five bits wide and could hold up to 31.
    always @(*)
        if (armed)
            assert (wdt <= LIMIT);

endmodule

