module lfsr_prio_precedence (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    output wire       o_valid,
    output wire [2:0] o_index
);
    // ---------------------------------------------------------------
    // 8-bit Fibonacci LFSR (taps 8,6,5,4) driving an 8-bit request
    // vector.  A nonzero state always maps to a nonzero state, so the
    // all-zeros lockup value is never produced.
    // ---------------------------------------------------------------
    reg [7:0] lfsr;
    reg [7:0] req_q;     // registered request vector (encoder input)
    reg [1:0] req_seen;  // shadow: history of "a request was present"
    reg       val_q;     // registered valid output
    reg [2:0] idx_q;     // registered index output

    initial lfsr     = 8'h01;
    initial req_q    = 8'h01;
    initial req_seen = 2'b11;
    initial val_q    = 1'b1;
    initial idx_q    = 3'd0;

    wire       fb        = lfsr[7] ^ lfsr[5] ^ lfsr[4] ^ lfsr[3];
    wire [7:0] lfsr_next = { lfsr[6:0], fb };

    // combinational priority encoder over the registered request vector
    wire       vld = |req_q;
    wire [2:0] idx = req_q[7] ? 3'd7 :
                     req_q[6] ? 3'd6 :
                     req_q[5] ? 3'd5 :
                     req_q[4] ? 3'd4 :
                     req_q[3] ? 3'd3 :
                     req_q[2] ? 3'd2 :
                     req_q[1] ? 3'd1 : 3'd0;

    always @(posedge clk) begin
        if (rst) begin
            lfsr     <= 8'h01;
            req_q    <= 8'h01;
            req_seen <= 2'b11;
            val_q    <= 1'b1;
            idx_q    <= 3'd0;
        end else if (ce) begin
            lfsr     <= lfsr_next;
            req_q    <= lfsr;
            req_seen <= { req_seen[0], |lfsr };
            val_q    <= vld;
            idx_q    <= idx;
        end
    end

    assign o_valid = val_q;
    assign o_index = idx_q;

    // Precedence: whenever the registered output stage reports a valid
    // index, the shadow history must record that a request bit was
    // actually present earlier in the pipeline.
    assert property (!o_valid || req_seen[1]);
endmodule

