module dma_burst_engine (
    input wire clk,
    input wire rst,
    input wire i_ce,
    input wire i_start,
    input wire [4:0] i_len,
    input wire [11:0] i_base,
    output reg o_busy
);
    // beats-remaining counter and its bookkeeping companions
    reg [4:0]  beats_left;
    reg [4:0]  beats_done;
    reg [4:0]  burst_len;
    reg [11:0] addr;
    reg [11:0] base;

    initial begin
        o_busy     = 1'b0;
        beats_left = 5'd0;
        beats_done = 5'd0;
        burst_len  = 5'd0;
        addr       = 12'd0;
        base       = 12'd0;
    end

    // requested length is clamped to the engine's maximum burst of 16 beats
    wire [4:0] eff_len = (i_len > 5'd16) ? 5'd16 : i_len;
    wire       accept  = (!o_busy) && i_start && (i_len != 5'd0);

    // address one past the last beat of the current burst
    wire [11:0] end_addr = base + ({7'd0, burst_len} << 2);

    always @(posedge clk) begin
        if (rst) begin
            o_busy     <= 1'b0;
            beats_left <= 5'd0;
            beats_done <= 5'd0;
            burst_len  <= 5'd0;
            addr       <= 12'd0;
            base       <= 12'd0;
        end else if (i_ce) begin
            if (o_busy) begin
                // issue one beat
                beats_left <= beats_left - 5'd1;
                beats_done <= beats_done + 5'd1;
                addr       <= addr + 12'd4;
                o_busy     <= (beats_left != 5'd1);
            end else if (accept) begin
                o_busy     <= 1'b1;
                beats_left <= eff_len;
                beats_done <= 5'd0;
                burst_len  <= eff_len;
                addr       <= i_base;
                base       <= i_base;
            end
        end
        // i_ce low: engine idles, all state held
    end

    // P: while the engine is busy, the beat pointer has not yet reached the
    // end of the burst region.
    always @(posedge clk)
        if (o_busy)
            assert (addr != end_addr);
