// Debounced external halt request line for a small RISC-V core.
// The raw request must be seen identical for K = 4 consecutive enabled
// samples before the clean (core-visible) halt request is allowed to flip.
module halt_debounce (
    input  wire clk,
    input  wire i_ce,          // sample enable; low => whole design idles
    input  wire i_raw_halt,    // noisy external halt request
    output wire o_halt_req,    // debounced request presented to the core
    output wire o_stable
);
    // ---------------- state ----------------
    reg [1:0] cnt      = 2'd0; // consecutive-identical-sample counter (0..3)
    reg       cand     = 1'b0; // candidate (last raw sample) value
    reg       stable_f = 1'b0; // set once the candidate has been stable K-1 times
    reg       clean    = 1'b0; // debounced output

    reg       pv       = 1'b0; // past-valid

    always @(posedge clk)
        pv <= 1'b1;

    always @(posedge clk) begin
        if (i_ce) begin
            if (i_raw_halt != cand) begin
                // glitch: restart the stability measurement
                cand     <= i_raw_halt;
                cnt      <= 2'd0;
                stable_f <= 1'b0;
            end else begin
                // another identical sample; counter saturates at K-1
                if (cnt != 2'd3)
                    cnt <= cnt + 2'd1;
                if (cnt == 2'd2)
                    stable_f <= 1'b1;
                // only a candidate already marked stable may drive the output
                if (stable_f)
                    clean <= cand;
            end
        end
    end

    assign o_halt_req = clean;
    assign o_stable   = stable_f;

    // Property: the debounced output may only have changed on the previous
    // edge if the stability counter was saturated at K-1 at that time.
    always @(posedge clk)
        if (pv && (clean != $past(clean)))
            assert ($past(cnt) == 2'd3);
endmodule

