module rr_credit_arb (
    input  wire       i_clk,
    input  wire       i_reset,
    input  wire       i_ce,
    input  wire [3:0] i_req,
    input  wire       i_ack_valid,
    input  wire [1:0] i_ack_id,
    output wire [3:0] o_grant,
    output wire [2:0] o_occ,
    output wire       o_armed
);
    // ---------------------------------------------------------------
    // Round-robin arbiter over 4 requesters with a last-grant pointer.
    // A line that already owns an outstanding grant (ack_pend) is
    // masked out, so a grant never lands on a busy or non-requesting
    // line, and the grant vector is one-hot-or-zero by construction.
    // ---------------------------------------------------------------
    reg [3:0] ack_pend;   // outstanding (granted, not yet acked) lines
    reg [2:0] occ;        // occupancy: number of outstanding grants
    reg [1:0] last;       // last granted index (round-robin pointer)
    reg       armed;      // high until line 3 has ever been granted

    initial ack_pend = 4'b0000;
    initial occ      = 3'd0;
    initial last     = 2'd3;
    initial armed    = 1'b1;

    wire [3:0] mreq = i_req & ~ack_pend;

    wire [1:0] p1 = last + 2'd1;
    wire [1:0] p2 = last + 2'd2;
    wire [1:0] p3 = last + 2'd3;

    reg [3:0] gnt_c;
    always @(*) begin
        gnt_c = 4'b0000;
        if (mreq[p1])       gnt_c = (4'b0001 << p1);
        else if (mreq[p2])  gnt_c = (4'b0001 << p2);
        else if (mreq[p3])  gnt_c = (4'b0001 << p3);
        else if (mreq[last])gnt_c = (4'b0001 << last);
    end

    wire       gnt_any = |gnt_c;
    wire [1:0] gidx    = gnt_c[0] ? 2'd0 :
                         gnt_c[1] ? 2'd1 :
                         gnt_c[2] ? 2'd2 : 2'd3;

    // an ack only counts if that line really has an outstanding grant
    wire       eff_ack   = i_ack_valid && ack_pend[i_ack_id];
    wire [3:0] ack_mask  = eff_ack ? (4'b0001 << i_ack_id) : 4'b0000;

    always @(posedge i_clk) begin
        if (i_reset) begin
            ack_pend <= 4'b0000;
            occ      <= 3'd0;
            last     <= 2'd3;
            armed    <= 1'b1;
        end else if (i_ce) begin
            ack_pend <= (ack_pend | gnt_c) & ~ack_mask;
            occ      <= occ + {2'b00, gnt_any} - {2'b00, eff_ack};
            if (gnt_any)
                last <= gidx;
            if (gnt_c[3])
                armed <= 1'b0;
        end
    end

    assign o_grant = i_ce ? gnt_c : 4'b0000;
    assign o_occ   = occ;
    assign o_armed = armed;

    // Property: before line 3 has ever been granted, at most three
    // grants can be outstanding at once (occ is 3 bits wide).
    always @(posedge i_clk)
        if (armed)
            assert (occ <= 3'd3);
endmodule

