        wptr    = 3'd0;
        rptr    = 3'd0;
        count   = 4'd0;
        o_data  = 8'h00;
        o_zero  = 1'b1;
        o_carry = 1'b0;
o_push_tally = 8'h00;
        for (i = 0; i < 8; i = i + 1) mem[i] = 9'd0;
    end

