module pingpong_tile_buffer (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,
    input  wire       wr_en,
    input  wire       rd_en,
    input  wire [7:0] wr_data,
    output reg  [7:0] rd_data,
    output wire       o_sel
);
