        if (rst) begin
            sel      <= 1'b0;
            wr_half  <= 1'b0;
            rd_half  <= 1'b1;
            wcnt     <= 2'd0;
            rcnt     <= 2'd0;
            wr_full  <= 1'b0;
            rd_empty <= 1'b1;
           swp_v0   <= 1'b0;
           swp_v1   <= 1'b0;
           swp_v2   <= 1'b0;
           swp_v3   <= 1'b0;
           swp_d0   <= 1'b0;
           swp_d1   <= 1'b0;
           swp_d2   <= 1'b0;
           swp_d3   <= 1'b0;
       end else if (swp_commit) begin
           sel      <= swp_d3;
           wr_half  <= swp_d3; // writer takes the freshly drained half
           rd_half  <=  sel;   // reader takes the freshly filled half
            wcnt     <= 2'd0;
            rcnt     <= 2'd0;
            wr_full  <= 1'b0;
            rd_empty <= 1'b0;
