o_ce_beats <= o_ce_beats + {3'd0, i_start};
            case (st)
                S_IDLE: begin
                    if (i_start) begin
                        st      <= S_OPEN;
                        loading <= 1'b1;
                        ready   <= 1'b0;
                    end else begin
                        st      <= S_IDLE;
                        loading <= 1'b0;
                        ready   <= 1'b0;
                    end
                end
                S_OPEN: begin
                    st      <= S_HEADER;
                    loading <= 1'b1;
                    ready   <= 1'b0;
                    rows    <= 4'd0;
                end
                S_HEADER: begin
                    st      <= S_ROWS;
                    loading <= 1'b1;
                    ready   <= 1'b0;
