    always @(posedge clk) if (i_ce) begin
       if (do_grant && refill)
            tokens <= tokens;                 // one out, one in
        else if (do_grant)
            tokens <= tokens - 3'd1;
       else if (refill && (tokens < BURST))
            tokens <= tokens + 3'd1;
    end

    // request window and its countdown
    always @(posedge clk) if (i_ce) begin
        if (do_grant)
            pending <= 1'b0;
        else if (pending)
            deadline <= deadline - 4'd1;
        else if (req) begin
            pending  <= 1'b1;
            deadline <= TIMEOUT;
        end
    end

