// Simple token-lexer FSM: binary-encoded states 0..4, encodings 5..7 unused.
module lex_fsm (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,      // idle when low: all state frozen
    input  wire [1:0] cls,     // 0=escape/backslash, 1=alpha, 2=digit, 3=quote
    output reg  [2:0] st,
    output reg  [2:0] len
);
    localparam [2:0] S_IDLE  = 3'd0;
    localparam [2:0] S_IDENT = 3'd1;
    localparam [2:0] S_NUM   = 3'd2;
    localparam [2:0] S_STR   = 3'd3;
    localparam [2:0] S_ESC   = 3'd4;
    // An escape can now be taken from top level or from inside an identifier,
    // so S_ESC alone no longer says which token is being built: the state code
    // to resume with is held here while st == S_ESC.
    reg [2:0] esc_ret;
   // Decode and commit are now separate cycles: the next-state decode and the
   // length adder no longer share one combinational path to the outputs. A
   // character is absorbed into the staging pair in one cycle and the pair is
   // driven onto st/len in the next.
   reg [2:0] st_s;
   reg [2:0] len_s;
   reg       s_vld;

    wire [2:0] len_inc = (len == 3'd7) ? 3'd7 : (len + 3'd1);

    initial st  = S_IDLE;
    initial len = 3'd0;
    initial esc_ret = S_IDLE;
   initial st_s  = S_IDLE;
   initial len_s = 3'd0;
   initial s_vld = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            st  <= S_IDLE;
            len <= 3'd0;
            esc_ret <= S_IDLE;
           st_s  <= S_IDLE;
           len_s <= 3'd0;
           s_vld <= 1'b0;
        end else if (ce) begin
           if (s_vld) begin
               st    <= st_s;   // commit cycle: staged pair becomes visible
               len   <= len_s;
               s_vld <= 1'b0;
           end else begin
               s_vld <= 1'b1;   // decode cycle: absorb this character
            case (st)
                S_IDLE: begin
                    if (cls == 2'd1) begin
                       st_s  <= S_IDENT;
                       len_s <= 3'd1;
                    end else if (cls == 2'd2) begin
                       st_s  <= S_NUM;
                       len_s <= 3'd1;
                    end else if (cls == 2'd3) begin
                       st_s  <= S_STR;
                       len_s <= 3'd0;
                    end else begin
                       st_s    <= S_ESC;   // stray backslash: escaped char starts an identifier
                        esc_ret <= S_IDENT;
                       len_s   <= 3'd0;
                    end
                end
                S_IDENT: begin
                    if (cls == 2'd1 || cls == 2'd2) begin
                       st_s  <= S_IDENT;
                       len_s <= len_inc;
                    end else if (cls == 2'd0) begin
                       st_s    <= S_ESC;   // a\b is still a single identifier
                        esc_ret <= S_IDENT;
                       len_s   <= len;
                    end else begin
                       st_s  <= S_IDLE;
                       len_s <= 3'd0;
                    end
                end
                S_NUM: begin
                    if (cls == 2'd2) begin
                       st_s  <= S_NUM;
                       len_s <= len_inc;
                    end else begin
                       st_s  <= S_IDLE;
                       len_s <= 3'd0;
                    end
                end
                S_STR: begin
                    if (cls == 2'd3) begin
                       st_s  <= S_IDLE;   // closing quote ends the token
                       len_s <= 3'd0;
                    end else if (cls == 2'd0) begin
                       st_s  <= S_ESC;    // backslash: next char is literal
                        esc_ret <= S_STR;
                       len_s <= len;
                    end else begin
                       st_s  <= S_STR;
                       len_s <= len_inc;
                    end
                end
                S_ESC: begin
                   st_s  <= esc_ret;     // resume whatever token the escape interrupted
                   len_s <= len_inc;
                end
