        if (ce) begin
            if (load) begin
                shadow_a   <= code_in;
                shadow_b   <= code_in;
                shadow_c   <= code_in;
prev_lo   <= code_in[1:0] - 2'd1;
prev_hi_t <= code_in[2] ^ (code_in[1:0] == 2'd0);
