        if (rst) begin
            bin0  <= 4'd0;
            bin1  <= 4'd0;
            bin2  <= 4'd0;
            bin3  <= 4'd0;
            total <= 4'd0;
           pend     <= 2'd0;
           pend_sel <= 2'd0;
ce_ticks <= 4'd0;
       end else begin
           if (fold) begin
               case (pend_sel)
                   2'd0: bin0 <= bin0 + {1'b0, fold_amt};
                   2'd1: bin1 <= bin1 + {1'b0, fold_amt};
                   2'd2: bin2 <= bin2 + {1'b0, fold_amt};
