   wire [3:0] out_b_nxt = gnt_b ? (gnt_take ? out_b + 4'd1 : out_b - 4'd1) : out_b;

    always @(posedge clk) begin
        if (rst) begin
            used  <= 4'd0;
            avail <= CAP;
           out_a <= 4'd0;
           out_b <= 4'd0;
          rsv_a <= 2'd0;
           turn  <= 1'b0;
           gnt_a <= 1'b0;
           gnt_b <= 1'b0;
           gnt_take <= 1'b0;
       end else if (i_ce) begin
           // stage 1: arbitrate this cycle's request
           gnt_a    <= accept && !turn;
           gnt_b    <= accept &&  turn;
           gnt_take <= i_take;
           if (accept)
               turn <= ~turn;

           // stage 2: retire the move granted last cycle
           out_a <= out_a_nxt;
           out_b <= out_b_nxt;
          rsv_a <= rsv_a_nxt;
          used  <= out_a_nxt + rsv_a_nxt + out_b_nxt;   // running total over both lanes
           if (take_fire)
