module hwm_stack_ptr (
    input  wire       clk,
    input  wire       i_ce,
    input  wire       i_push,
    input  wire       i_pop,
    output wire       o_deep,
    output wire [3:0] o_mark,
    output wire [3:0] o_sp
);
    localparam [3:0] THRESH = 4'd4;

    // stack pointer and its high-water mark
    reg [3:0] sp;
    reg [3:0] hwm;
    reg       mark_deep;   // registered "mark has crossed THRESH" flag
    reg       pv;          // past-valid

   // push/pop event ledger for depth accounting: every accepted push and
   // every accepted pop is logged, and the difference of the two counters
   // is the occupancy the mark logic trusts
   reg [3:0] n_push;
   reg [3:0] n_pop;

    initial sp        = 4'd0;
    initial hwm       = 4'd0;
    initial mark_deep = 1'b0;
    initial pv        = 1'b0;
   initial n_push    = 4'd0;
   initial n_pop     = 4'd0;

    wire do_push = i_ce && i_push && !i_pop && (sp != 4'hF);
    wire do_pop  = i_ce && i_pop  && !i_push && (sp != 4'h0);

    wire [3:0] sp_nx  = do_push ? (sp + 4'd1)
                      : (do_pop ? (sp - 4'd1) : sp);

   wire [3:0] n_push_nx = do_push ? (n_push + 4'd1) : n_push;
   wire [3:0] n_pop_nx  = do_pop  ? (n_pop  + 4'd1) : n_pop;

   // occupancy as seen by the ledger after this cycle's events
   wire [3:0] occ_nx    = n_push_nx - n_pop_nx;

   // the mark must cover both the pointer and the logged occupancy
   wire [3:0] mark_lo   = (sp_nx > occ_nx) ? sp_nx : occ_nx;

    // the mark never falls below the pointer and only ratchets upward
   wire [3:0] hwm_nx = (mark_lo > hwm) ? mark_lo : hwm;

    always @(posedge clk) begin
        if (i_ce) begin
            sp        <= sp_nx;
            hwm       <= hwm_nx;
            mark_deep <= (hwm_nx >= THRESH);
           n_push    <= n_push_nx;
           n_pop     <= n_pop_nx;
        end
    end

    always @(posedge clk)
        pv <= 1'b1;

    assign o_deep = mark_deep;
    assign o_mark = hwm;
    assign o_sp   = sp;

    // Precedence: the deep-mark flag can only rise because the pointer itself
    // has just reached that depth, so the depth must be visible right now.
    always @(posedge clk)
        if (pv && $rose(mark_deep))
            assert (sp >= THRESH);

endmodule

