        d0 = 8'h00; d1 = 8'h00;
        p0 = 1'b0;  p1 = 1'b0;
       p0h = 1'b0; p1h = 1'b0;
        v0 = 1'b0;  v1 = 1'b0;
        occ = 3'd0;
       oq_busy = 1'b0;
       oq_par  = 1'b0;
      oq_parh = 1'b0;
       sb_d = 8'h00; sb_p = 1'b0; sb_v = 1'b0;
      sb_ph = 1'b0;
       lim     = 3'd2;
      rpy     = 3'd0;
        o_valid = 1'b0;
        o_data  = 8'h00;
        o_retry = 1'b0;
    end

    // stored parity is checked against stored data every cycle
   wire mism0 = v0 && ((p0 != (^d0[3:0])) || (p0h != (^d0[7:4])));
   wire mism1 = v1 && ((p1 != (^d1[3:0])) || (p1h != (^d1[7:4])));
