// does not have to carry an adder and an XOR network in the same
// cycle: goal_pre always holds the code the counter will show K
// counts from now, and accept just latches it.
wire [3:0] goal_bin      = bin_nxt + K;
wire [3:0] goal_gray_nxt = goal_bin ^ (goal_bin >> 1);

    wire accept = i_ce && armed && req && !busy;
    wire tick   = i_ce && busy;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (i_ce) begin
            // gray counter advances together with its binary shadow
            bin  <= bin_nxt;
gray_pre  <= gray_pre2[2:0];
if (top_load) gray_pre_top <= gray_pre2[3];
gray     <= {gray_pre_top, gray_pre};
// the prefetch chain shifts one encoding per count
gray_pre2 <= gray_pre3;
gray_pre3 <= gray_pre4;
gray_pre4 <= gray_pre5;
gray_pre5 <= gray_la;
           // deadline encoder keeps pace with the counter
           goal_pre <= goal_gray_nxt;

