   reg       p1_b;
   reg       p1_take;
   reg       p2_a;
   reg       p2_b;
   reg       p2_take;
   reg       p3_a;
   reg       p3_b;
   reg       p3_take;
   reg       p4_a;
   reg       p4_b;
   reg       p4_take;

