           gnt_b <= 1'b0;
           gnt_take <= 1'b0;
           p1_a <= 1'b0;
           p1_b <= 1'b0;
           p1_take <= 1'b0;
           p2_a <= 1'b0;
           p2_b <= 1'b0;
           p2_take <= 1'b0;
           p3_a <= 1'b0;
           p3_b <= 1'b0;
           p3_take <= 1'b0;
           p4_a <= 1'b0;
           p4_b <= 1'b0;
           p4_take <= 1'b0;
       end else if (i_ce) begin
           // stage 1: arbitrate this cycle's request
           gnt_a    <= accept && !turn;
           gnt_b    <= accept &&  turn;
           gnt_take <= i_take;
           if (accept)
               turn <= ~turn;
           // stages 2-5: the credit walks the shared shelf port
           p1_a    <= gnt_a;
           p1_b    <= gnt_b;
           p1_take <= gnt_take;
           p2_a    <= p1_a;
           p2_b    <= p1_b;
           p2_take <= p1_take;
           p3_a    <= p2_a;
           p3_b    <= p2_b;
           p3_take <= p2_take;
           p4_a    <= p3_a;
           p4_b    <= p3_b;
           p4_take <= p3_take;

           // stage 6: retire the move as it leaves the port
           out_a <= out_a_nxt;
           out_b <= out_b_nxt;
          rsv_a <= rsv_a_nxt;
          used  <= out_a_nxt + rsv_a_nxt + out_b_nxt;   // running total over both lanes
