module token_bucket_deadline (
    input  wire clk,
    input  wire i_ce,
    input  wire req,
    output wire grant,
    output wire expired
);
    // burst size of the bucket and the response deadline for one request
    localparam [2:0] BURST   = 3'd4;
    localparam [3:0] TIMEOUT = 4'd6;

    reg [2:0] tokens;    // token bucket, capped at BURST
    reg [1:0] tick_cnt;   // refill timer, counts down, tick at zero
    reg       pending;    // window register: set by accepted request, cleared by grant
    reg [3:0] deadline;   // bounded-response countdown for the pending request
    reg       refill_q;  // staged refill: a tick is captured here and applied to the bucket next cycle
    reg       pending_b;   // second request slot: holds a request that arrived while the head slot was busy
    reg [3:0] deadline_b;  // best-effort countdown for the queued slot
    reg       rr_b;        // arbitration pointer, 1 when the queued slot gets the next token
    reg [2:0] starve;      // consecutive cycles the head slot has waited on a dry bucket

    initial tokens   = BURST;
    initial tick_cnt = 2'd3;
    initial pending  = 1'b0;
    initial deadline = 4'd0;
    initial refill_q = 1'b0;
    initial pending_b  = 1'b0;
    initial deadline_b = 4'd0;
    initial rr_b       = 1'b0;
    initial starve     = 3'd0;

    wire tick     = (tick_cnt == 2'd0);
    wire b_ready    = pending_b && (tokens != 3'd0);
    // the queued slot only pre-empts on its own turn, and only while the
    // bucket still holds a spare token for the head slot
    wire do_grant_b = b_ready && (!pending || (rr_b && (tokens >= 3'd2)));
    wire do_grant = pending && (tokens != 3'd0) && !do_grant_b;
    wire do_refill = refill_q && (tokens < BURST);
    wire any_grant = do_grant || do_grant_b;
    // dry-bucket alarm: the head slot has spent a whole refill interval without a token
    wire dry_alarm = pending && (starve >= 3'd3);

    assign grant   = i_ce && any_grant;
    assign expired = (pending && (deadline == 4'd0)) || (pending_b && (deadline_b == 4'd0)) || dry_alarm;

    // refill timer
    always @(posedge clk) if (i_ce)
        tick_cnt <= tick ? 2'd3 : (tick_cnt - 2'd1);

    // refill request is registered one cycle before it reaches the bucket
    always @(posedge clk) if (i_ce)
        refill_q <= tick;

    // bucket: drains on a grant, refills on a tick, saturates at BURST
    always @(posedge clk) if (i_ce) begin
        if (any_grant && do_refill)
            tokens <= tokens;                 // one out, one in
        else if (any_grant)
            tokens <= tokens - 3'd1;
        else if (do_refill)
            tokens <= tokens + 3'd1;
    end

    // round-robin pointer: whichever slot was served hands the turn over
    always @(posedge clk) if (i_ce) begin
        if (do_grant_b)
            rr_b <= 1'b0;
        else if (do_grant)
            rr_b <= 1'b1;
    end

    // queued slot: captures the request that arrives while the head slot is busy,
    // counts down best effort and drops the request if it runs out
    always @(posedge clk) if (i_ce) begin
        if (do_grant_b)
            pending_b <= 1'b0;
        else if (pending_b) begin
            if (deadline_b == 4'd0)
                pending_b <= 1'b0;
            else
                deadline_b <= deadline_b - 4'd1;
        end else if (req && pending) begin
            pending_b  <= 1'b1;
            deadline_b <= TIMEOUT;
        end
    end

    // request window and its countdown
    always @(posedge clk) if (i_ce) begin
        if (do_grant)
            pending <= 1'b0;
        else if (pending)
            deadline <= deadline - 4'd1;
        else if (req) begin
            pending  <= 1'b1;
            deadline <= TIMEOUT;
        end
    end
    // starvation counter: how many enabled cycles the head request has spent
    // waiting on an empty bucket; cleared as soon as a token is in the bucket
    always @(posedge clk) if (i_ce) begin
        if (!pending || (tokens != 3'd0))
            starve <= 3'd0;
        else
            starve <= starve + 3'd1;
    end

    // P: inside the request window the countdown never expires
    always @(posedge clk)
        if (pending) assert (deadline != 4'd0);
    // P2: the dry-bucket counter cannot outlive the request window
    always @(posedge clk)
        if (pending) assert (starve <= 3'd5);
