       if (rst) begin
           gray_s <= 4'b0000;
           s_vld  <= 1'b0;
ce_d    <= 1'b0;
ce_hist <= 4'b0000;
       end else begin
           s_vld <= i_ce;
ce_d    <= i_ce;
ce_hist <= {ce_hist[2:0], ce_d};
           if (i_ce) gray_s <= gnext(gray_s);
       end
   end

