   // same cycle, so the two views never disagree at the outputs.

    always @(posedge clk) begin
        if (rst) begin
            bin  <= 4'b0000;
            gray <= 4'b0000;
       end else if (s_vld) begin
            bin  <= bin + 4'b0001;
           gray <= gray_s;
        end
