    // ---- gray counter with its binary shadow -------------------------
    reg [3:0] bin;
    reg [3:0] gray;

   // The binary->gray conversion is pipelined: the encoder runs one
// increment ahead of the visible counter; behind it a four-deep
// prefetch chain holds the next four encodings, so the adder and the
// XOR network run six counts ahead and every register in the chain --
// including the output register -- is fed straight out of a register.
reg [2:0] gray_pre;     // in-flight gray code for bin+1, low bits
// Bit 3 of a gray code is just bit 3 of the binary count, so the top
// bit skips the XOR network entirely and lives in its own register.
// It is only reloaded on the two counts where it can change, which
// keeps it from toggling with the rest of the pipeline.
reg       gray_pre_top;
// prefetch chain: pre-encoded gray codes waiting to be shifted into
// the stage-1 registers, oldest (nearest the output) first.
reg [3:0] gray_pre2;    // gray code queued for bin+2
reg [3:0] gray_pre3;    // gray code queued for bin+3
reg [3:0] gray_pre4;    // gray code queued for bin+4
reg [3:0] gray_pre5;    // gray code queued for bin+5

    // ---- bounded-response deadline machinery -------------------------
    reg [3:0] timer;      // countdown for the outstanding request
    reg       busy;       // request outstanding
    reg [3:0] goal_gray;  // gray code the counter should show at completion
   reg [3:0] goal_pre;   // deadline gray code, encoded K counts ahead
    reg       armed;      // sticky: set the first time a request is seen

    reg       pv;         // past valid

   // ---- distractor: rolling record of request pulses ---------------
   reg [3:0] req_hist;

    localparam [3:0] K = 4'd8;   // response bound

    initial begin
        bin       = 4'd0;
        gray      = 4'd0;
gray_pre     = 3'd1;   // encoder prefilled with gray(bin+1)[2:0]
gray_pre_top = 1'b0;   // ... and its top bit
gray_pre2    = 4'd3;   // prefetch chain prefilled with gray(bin+2..5)
gray_pre3    = 4'd2;
gray_pre4    = 4'd6;
gray_pre5    = 4'd7;
        timer     = 4'd0;
        busy      = 1'b0;
        goal_gray = 4'd0;
       goal_pre  = 4'd12;   // gray(0 + K)
        armed     = 1'b0;
        pv        = 1'b0;
       req_hist   = 4'd0;
       o_req_hist = 4'd0;
