module skid_cred_stage (
    input  wire       i_clk,
    input  wire       i_reset,
    input  wire       i_ce,
    input  wire       i_valid,
    input  wire [7:0] i_cred,
    input  wire       i_ready,
    output wire       o_valid,
    output wire [7:0] o_cred,
    output wire       o_upstream_ready,
    output wire       g_bypass,
output wire       g_holdoff,
output reg  [3:0] o_dbg_count
);
    // ---- main pipeline register (vendor/credential record) ----
    reg        m_valid;
    reg [7:0]  m_cred;

    // ---- skid buffer: s_cred is only meaningful while the stall flag is up ----
    reg        hold;      // stall flag
    reg [7:0]  s_cred;
   // ---- promotion transit register (skid -> main is now a two-cycle path) ----
   reg        pr_v;     // a promoted record is in flight toward the main slot
   reg [7:0]  pr_cred;
   reg [1:0]  t_occ;    // occupancy of the transit register

// ---- per-slot occupancy accounting, kept in parallel with the valid bits ----
    reg [1:0]  occ;
   reg [1:0]  p_occ;   // priority-class share of the main slot (i_cred[7] set)
reg [1:0]  s_occ;
// ---- configured stage depth and free-slot accounting ----
reg [1:0]  cap;    // programmed depth: 1 (main only) or 2 (main + skid)
reg [2:0]  free;   // slots still available = cap - records resident

    // ---- downstream arbitration grants ----
    reg        g_fast;    // bypass grant: record admitted into an empty stage
    reg        g_hld;     // hold-off grant: skid full, upstream must wait

    // ---- sticky arm + past-valid ----
    reg        armed;
    reg        pv;
reg  [3:0] dbg_prev;

    initial begin
        m_valid = 1'b0;
        m_cred  = 8'h00;
        hold    = 1'b0;
        s_cred  = 8'h00;
       pr_v    = 1'b0;
       pr_cred = 8'h00;
       t_occ   = 2'd0;
        occ     = 2'd0;
       p_occ   = 2'd0;
s_occ   = 2'd0;
cap     = 2'd2;
free    = 3'd2;
        g_fast  = 1'b0;
        g_hld   = 1'b0;
        armed   = 1'b0;
        pv      = 1'b0;
o_dbg_count = 4'd0;
dbg_prev    = 4'd0;
    end

wire       skid_free  = (free != 3'd0);
// the parked record leaves the skid slot for the transit register
wire       promote    = i_ce && m_valid && i_ready && hold;
wire       load_skid  = i_ce && i_valid && skid_free && ((m_valid && !i_ready && !hold) || (!m_valid && pr_v));
wire       fill_main  = i_ce && i_valid && !m_valid && !pr_v;
wire       drain_main = i_ce && m_valid && i_ready && !(!hold && i_valid && skid_free);
wire       drain_skid = i_ce && hold && i_ready;
// a fresh input record takes the main slot next cycle
wire       main_wr_new  = fill_main || (i_ce && i_valid && m_valid && i_ready && !hold && skid_free);
// the promoted record leaves the transit register for the main slot
wire       main_wr_pr   = i_ce && !m_valid && pr_v;
// total records resident in the stage (main slot + skid slot + transit)
wire [1:0] occ_total  = occ + p_occ + s_occ + t_occ;
// quiescent: nothing resident in the stage and nothing arriving this cycle
wire       stage_idle = (occ_total == 2'd0) && !i_valid;
// depth request is sampled off the credential bus while quiescent
wire [1:0] cap_req    = i_cred[0] ? 2'd1 : 2'd2;
// a record is taken from upstream / handed downstream this cycle
wire       in_accept  = i_valid && !hold && skid_free;
wire       out_accept = m_valid && i_ready;

    // ---- skid-buffered valid/ready stage ----
    always @(posedge i_clk) begin
        if (i_reset) begin
            m_valid <= 1'b0;
            m_cred  <= 8'h00;
            hold    <= 1'b0;
            s_cred  <= 8'h00;
        end else if (i_ce) begin
            if (m_valid && i_ready) begin
                if (hold) begin
                   // the main record goes downstream this cycle; the parked
                   // record steps into the transit register on its way in
                   m_valid <= 1'b0;
                   hold    <= 1'b0;
end else if (i_valid && skid_free) begin
                    m_cred  <= i_cred;
                    m_valid <= 1'b1;
                end else begin
                    m_valid <= 1'b0;
                end
            end else if (!m_valid) begin
               if (pr_v) begin
                   // main slot is reserved for the record already in transit,
                   // so a fresh arrival is parked in the freed skid slot
                   m_valid <= 1'b1;
                   m_cred  <= pr_cred;
                   if (i_valid && skid_free) begin
                       hold   <= 1'b1;
                       s_cred <= i_cred;
                   end
               end else if (i_valid) begin
                   m_valid <= 1'b1;
                   m_cred  <= i_cred;
               end
            end else begin
if (i_valid && !hold && skid_free) begin
                    hold   <= 1'b1;
                    s_cred <= i_cred;
                end
            end
        end
    end

// ---- main-slot occupancy counter ----
   // normal-class records only; the priority-class share lives in p_occ
    always @(posedge i_clk) begin
        if (i_reset)
            occ <= 2'd0;
        else if (i_ce) begin
           if (main_wr_new)
               occ <= {1'b0, ~i_cred[7]};
          else if (main_wr_pr)
              occ <= {1'b0, ~pr_cred[7]};
           else if (drain_main)
               occ <= 2'd0;
        end
    end

   // ---- main-slot occupancy counter, priority-class share ----
   always @(posedge i_clk) begin
       if (i_reset)
           p_occ <= 2'd0;
       else if (i_ce) begin
           if (main_wr_new)
               p_occ <= {1'b0, i_cred[7]};
          else if (main_wr_pr)
              p_occ <= {1'b0, pr_cred[7]};
           else if (drain_main)
               p_occ <= 2'd0;
       end
   end

// ---- skid-slot occupancy counter ----
always @(posedge i_clk) begin
    if (i_reset)
        s_occ <= 2'd0;
    else if (i_ce) begin
        if (load_skid)
            s_occ <= s_occ + 2'd1;
        else if (drain_skid)
            s_occ <= s_occ - 2'd1;
    end
end
// ---- promotion transit register ----
// the parked record now spends a cycle here on its way to the main slot,
// which keeps the skid-to-main mux out of the downstream ready path
always @(posedge i_clk) begin
    if (i_reset) begin
        pr_v    <= 1'b0;
        pr_cred <= 8'h00;
    end else if (i_ce) begin
        if (promote) begin
            pr_v    <= 1'b1;
            pr_cred <= s_cred;
        end else if (main_wr_pr)
            pr_v <= 1'b0;
    end
end
// ---- transit-register occupancy ----
always @(posedge i_clk) begin
    if (i_reset)
        t_occ <= 2'd0;
    else if (i_ce) begin
        if (promote)
            t_occ <= t_occ + 2'd1;
        else if (main_wr_pr)
            t_occ <= t_occ - 2'd1;
    end
end
// ---- programmed stage depth ----
// depth is re-sampled only while the stage is quiescent, so a change can
// never strand a record in a slot that has just been configured away
always @(posedge i_clk) begin
    if (i_reset)
        cap <= 2'd2;
    else if (i_ce && stage_idle)
        cap <= cap_req;
end
// ---- free-slot counter: depth minus the records resident in the stage ----
always @(posedge i_clk) begin
    if (i_reset)
        free <= 3'd2;
    else if (i_ce) begin
        if (stage_idle)
            free <= {1'b0, cap_req};
        else
            free <= free - {2'b00, in_accept} + {2'b00, out_accept};
    end
end

    // ---- grant registers ----
    always @(posedge i_clk) begin
        if (i_reset) begin
            g_fast <= 1'b0;
            g_hld  <= 1'b0;
dbg_prev    <= 4'd0;
o_dbg_count <= 4'd0;
        end else if (i_ce) begin
g_fast <= i_valid && (free == {1'b0, cap});
            g_hld  <= i_valid && m_valid && hold;
dbg_prev    <= dbg_prev + {3'b000, (i_valid && i_ready)};
o_dbg_count <= dbg_prev ^ {3'b000, hold};
        end
    end

    // ---- sticky arm: first time a record is parked in the skid buffer ----
    always @(posedge i_clk)
        armed <= armed | load_skid;

    always @(posedge i_clk)
        pv <= 1'b1;

    assign o_valid          = m_valid;
    assign o_cred           = m_cred;
assign o_upstream_ready = !hold && skid_free;
    assign g_bypass         = g_fast;
    assign g_holdoff        = g_hld;

    // ---- P: once armed, the two grants are never asserted together ----
    always @(posedge i_clk)
        if (pv && armed && $rose(g_hld))
            assert (!g_fast);

endmodule

