module pdk_reqtrack (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // global enable / idle when low
    input  wire       i_arm,     // Q event: arms the tracker (sticky)
    input  wire       i_launch,  // start step: issue a request into the array
    output wire       o_retire,  // finish step: request leaves last stage
    output wire [2:0] o_inflight
);
    parameter STAGES = 4;

    // shift register tracking in-flight requests through the stage array
    reg [STAGES-1:0] pipe;
   // peer short path: a second, two-stage request array. Accepted launches
   // alternate between the long array and this one to balance occupancy.
   reg [1:0]        pipe_b;
    // separate count of set bits in that shift register
    reg [2:0]        cnt;
    // sticky arm register (scope): set the first time i_arm is seen, never cleared
    reg              armed;
    // sticky record that a start actually happened after arming
    reg              started;
   // issue stage: an accepted launch is held here for one cycle (address
   // decode) before it is written into the stage array
   reg              ln_stage;
  // target lane of the request held in the issue stage (0 = long, 1 = short)
  reg              ln_tag;
  // round-robin lane pointer applied to the next accepted launch
  reg              rr;
// express lane: a request issued while the stage array is completely idle
// bypasses the array and completes one cycle later
reg              xpr;

    initial pipe    = {STAGES{1'b0}};
   initial pipe_b  = 2'b00;
    initial cnt     = 3'd0;
    initial armed   = 1'b0;
    initial started = 1'b0;
   initial ln_stage = 1'b0;
  initial ln_tag   = 1'b0;
  initial rr       = 1'b0;
initial xpr      = 1'b0;

    // a launch is only accepted once the tracker has been armed
    wire accept = i_ce && i_launch && armed;
  // the issue stage takes the express lane only when both arrays are empty
  wire xpr_take = ln_stage && (pipe == {STAGES{1'b0}}) && (pipe_b == 2'b00);
  wire retire = i_ce && (pipe[STAGES-1] || pipe_b[1] || xpr);

    assign o_retire   = retire;
    assign o_inflight = cnt;

    always @(posedge clk) begin
        if (rst) begin
            pipe    <= {STAGES{1'b0}};
           pipe_b  <= 2'b00;
            cnt     <= 3'd0;
            armed   <= 1'b0;
            started <= 1'b0;
           ln_stage <= 1'b0;
          ln_tag   <= 1'b0;
          rr       <= 1'b0;
           xpr      <= 1'b0;
        end else if (i_ce) begin
         pipe    <= { pipe[STAGES-2:0], ln_stage && !ln_tag && !xpr_take };
         pipe_b  <= { pipe_b[0],        ln_stage &&  ln_tag && !xpr_take };
         cnt     <= cnt + (ln_stage ? 3'd1 : 3'd0)
                         - (pipe[STAGES-1] ? 3'd1 : 3'd0)
                         - (pipe_b[1] ? 3'd1 : 3'd0)
                         - (xpr ? 3'd1 : 3'd0);
