        if (rst) begin
pipe  <= 3'b000;
            occ   <= 3'd0;
            armed <= 1'b0;
wb    <= 1'b0;
beat  <= 1'b0;
credit <= 3'd4;
n_iss <= 3'd0;
n_ret <= 3'd0;
rtn   <= 3'd0;
