// slot that falls off the far end. Free running, they wrap at three bits.
reg [2:0]   n_in;
reg [2:0]   n_out;

    initial win   = 0;
    initial ones  = 0;
   initial adm_q = 0;
   initial s1    = 0;
   initial s2    = 0;
   initial s3    = 0;
   initial s4    = 0;
    initial armed = 0;
   initial gap   = 0;
    initial pv    = 0;
