            win   <= 0;
            ones  <= 0;
           adm_q <= 0;
           s1    <= 0;
           s2    <= 0;
           s3    <= 0;
           s4    <= 0;
            armed <= 0;
           gap   <= 0;
n_in  <= 0;
n_out <= 0;
