win   <= { win[W-2:0], s4 };
           ones  <= ones - retiring + (adm_q ? 3'd1 : 3'd0);
adm_q <= s4;
s1    <= allow;
s2    <= s1;
s3    <= s2;
s4    <= s3;
if (allow)
    n_in  <= n_in  + 3'd1;
if (win[W-1])
    n_out <= n_out + 3'd1;
            if (allow)
