reg [2:0] cn1, cn2, cn3, cn4;
reg       cv1, cv2, cv3, cv4;

    initial prog         = 3'd0;
    initial seen_half    = 1'b0;
    initial before_alarm = 1'b1;
    initial alarm        = 1'b0;
   initial stg          = 3'd0;
   initial stg_v        = 1'b0;
  initial hcnt         = 3'd0;
 initial prog2        = 3'd0;
 initial stg2         = 3'd0;
 initial hpend        = 1'b0;
 initial harb         = 1'b0;
initial cm1          = 3'd0;
initial cm2          = 3'd0;
initial cm3          = 3'd0;
initial cm4          = 3'd0;
initial cn1          = 3'd0;
initial cn2          = 3'd0;
initial cn3          = 3'd0;
initial cn4          = 3'd0;
initial cv1          = 1'b0;
initial cv2          = 1'b0;
initial cv3          = 1'b0;
initial cv4          = 1'b0;

