// Multi-zone thermostat front end with hysteresis and a power budget.
// The active-zone mask is a parity protected register slice; a maintained
// occupancy counter and a remaining-budget counter track it.
module zone_heat_budget (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,      // idle when low: all state frozen
    input  wire [2:0] i_zone,    // zone under consideration this cycle
    input  wire [7:0] i_temp,    // measured temperature of that zone
    output wire       o_fault,   // parity mismatch on the zone slice
    output wire [3:0] o_nact,
output wire [3:0] o_budget,
output reg  [3:0] o_hot_cnt
);
    parameter [7:0] T_LOW  = 8'd40;   // below this, zone asks for heat
    parameter [7:0] T_HIGH = 8'd60;   // above this, zone releases heat
    localparam [3:0] BUDGET = 4'd4;   // at most 4 heaters may run at once
   localparam [3:0] BASE   = BUDGET - 4'd1; // slots in the shared base pool
   localparam [7:0] T_CRIT = 8'd20;  // below this a zone may claim the boost slot

    // ---- parity protected register slice -------------------------------
    reg [7:0] zone;    // one bit per zone heater
    reg       zpar;    // parity bit covering zone
    initial   zone = 8'h00;
    initial   zpar = 1'b0;

    // ---- bookkeeping registers -----------------------------------------
    reg [3:0] nact;    // number of heaters currently on
    reg [3:0] budget;  // remaining power slots
    initial   nact   = 4'd0;
   initial   budget = BASE;

   // The fourth slot is a boost slot: it is handed out only to a deeply
   // cold zone when the base pool is dry, and is tracked back to the zone
   // holding it so it can be returned when that heater goes off again.
   reg       b_used;  // boost slot is committed to a zone
   reg [2:0] b_zone;  // zone holding the boost slot
   initial   b_used = 1'b0;
   initial   b_zone = 3'd0;

   // ---- issue / commit pipeline ---------------------------------------
   // A grant decided this cycle reaches the heater mask on the next cycle;
   // the in-flight grant is held here.  One grant may be in flight.
   reg       p_val;   // a grant is in flight
   reg       p_on;    // 1 = turn the zone on, 0 = turn it off
   reg [2:0] p_zone;  // zone the in-flight grant targets
   initial   p_val  = 1'b0;
   initial   p_on   = 1'b0;
   initial   p_zone = 3'd0;

  // duct partner channel: zones are ducted in pairs, so a zone that is
  // deeply cold also opens its partner's damper.  The partner grant has
  // its own in-flight register but draws from the same base pool.
  reg       q_val;   // a partner grant is in flight (always a turn-on)
  reg [2:0] q_zone;  // partner zone the in-flight grant targets
  initial   q_val  = 1'b0;
  initial   q_zone = 3'd0;
initial   o_hot_cnt = 4'd0;

    wire fault = (zpar != (^zone));
    assign o_fault  = fault;
    assign o_nact   = nact;
   assign o_budget = budget + {3'b000, ~b_used};

    // hysteresis: nothing happens inside the dead band, so no chattering
    wire req_on  = i_ce && !fault && (i_temp <  T_LOW);
    wire req_off = i_ce && !fault && (i_temp >  T_HIGH);

   // forward the in-flight grant, so a zone is never granted twice while
   // its mask bit has not been updated yet
  wire zbit = (p_val && (p_zone == i_zone)) ? p_on :
              (q_val && (q_zone == i_zone)) ? 1'b1 : zone[i_zone];

  // a zone deep in the cold may use the boost slot once the base pool is dry
  wire deep_cold = (i_temp < T_CRIT);
  wire slot_free = (budget != 4'd0) || (!b_used && deep_cold);

  wire do_on  = req_on  && !zbit && slot_free;
   wire do_off = req_off &&  zbit;

   // a power slot is reserved when the grant is issued and released only
   // when the heater has actually been switched off, one cycle later
  wire take_base  = do_on && (budget != 4'd0);
  wire take_boost = do_on && (budget == 4'd0);
  wire rel_boost  = p_val && !p_on && b_used && (p_zone == b_zone);
  wire rel_base   = p_val && !p_on && !rel_boost;

 // the ducted partner of the zone under consideration
 wire [2:0] pz = i_zone ^ 3'd1;
 wire qbit = (p_val && (p_zone == pz)) ? p_on :
             (q_val && (q_zone == pz)) ? 1'b1 : zone[pz];
 // the partner never uses the boost slot: it may only have what is left
 // of the base pool after the primary grant has taken its slot
 wire [3:0] base_left = budget - {3'b000, take_base};
 wire do_hon = do_on && deep_cold && !qbit && (base_left != 4'd0);

    always @(posedge i_clk) begin
        if (i_rst) begin
            zone   <= 8'h00;
            zpar   <= 1'b0;
            nact   <= 4'd0;
           budget <= BASE;
           b_used <= 1'b0;
           b_zone <= 3'd0;
           p_val  <= 1'b0;
           p_on   <= 1'b0;
           p_zone <= 3'd0;
          q_val  <= 1'b0;
          q_zone <= 3'd0;
o_hot_cnt <= 4'd0;
       end else if (i_ce) begin
           // commit stage: apply the grant issued last cycle
          if (p_val) zone[p_zone] <= p_on;
          if (q_val) zone[q_zone] <= 1'b1;
          // each committed grant flips exactly one data bit
          zpar <= zpar ^ p_val ^ q_val;
          nact <= nact + {3'b000, (p_val && p_on)} + {3'b000, q_val}
                       - {3'b000, (p_val && !p_on)};
           // issue stage: latch this cycle's decision
           p_val  <= do_on || do_off;
           p_on   <= do_on;
           p_zone <= i_zone;
         q_val  <= do_hon;
         q_zone <= pz;
         budget <= budget - {3'b000, take_base} - {3'b000, do_hon}
                          + {3'b000, rel_base};
          b_used <= (b_used && !rel_boost) || take_boost;
          if (take_boost)
              b_zone <= i_zone;
o_hot_cnt <= ((i_temp > T_HIGH) && (o_hot_cnt != 4'd15)) ? o_hot_cnt + 4'd1 : o_hot_cnt;
       end
    end

    wire heating = (zone != 8'h00);

    // P: whenever any heater is running, occupancy never exceeds the
    //    power budget of 4 (the counter is 4 bits wide).
    always @(posedge i_clk)
        if (heating)
            assert (nact <= 4'd4);
endmodule

