module skid_parity_window (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,        // stage enable: low => full idle
    input  wire       i_valid,
    input  wire [7:0] i_data,
    input  wire       i_dready,    // downstream ready
    input  wire       i_close,     // closes the observation window
    output wire       o_ready,
    output reg        o_valid,
output reg  [7:0] o_data,
output reg  [3:0] o_beat_count
);

    // ---- skid buffer stage state ----
    reg        stall;      // skid slot occupied
    reg  [3:0] skid;       // low nibble of the buffered word
    reg  [3:0] skid_hi;    // upper nibble; flops enabled only for wide words
    reg        skid_wide;  // buffered word has a nonzero upper nibble
    reg        skid_par;   // shadow parity of the buffered word

    reg        o_par;      // shadow parity of the presented word

    // ---- observation window (opened by a skid release, closed by i_close) ----
    reg        win;
    reg  [7:0] acc_data;    // xor of words released inside the window
    reg        acc_par;     // xor of their shadow parities

   // ---- pending tracker: window accumulator xor the word still in the skid slot ----
reg  [3:0] pend_lo;      // low nibble of the pending residue
reg  [3:0] pend_hi;      // upper nibble, only clocked while the residue is wide
reg        pend_wide;    // residue currently carries a nonzero upper nibble
reg        pend_par;     // shadow parity of the whole residue
reg        pend_par_hi;  // shadow parity of the tracked upper nibble

    initial begin
        stall    = 1'b0;
        skid      = 4'h0;
        skid_hi   = 4'h0;
        skid_wide = 1'b0;
        skid_par = 1'b0;
        o_valid  = 1'b0;
        o_data   = 8'h00;
        o_par    = 1'b0;
        win      = 1'b0;
        acc_data = 8'h00;
        acc_par  = 1'b0;
pend_lo     = 4'h0;
pend_hi     = 4'h0;
pend_wide   = 1'b0;
pend_par    = 1'b0;
pend_par_hi = 1'b0;
o_beat_count = 4'd0;
    end

    assign o_ready = !stall;

    // reassembled buffered word: narrow words carry an implicit zero nibble
    wire [7:0] skid_word = {(skid_wide ? skid_hi : 4'h0), skid};

   // pending residue: narrow residues present an implicit zero upper nibble,
   // and the fold datapath is only four bits wide
   wire [3:0] pend_hi_cur = pend_wide ? pend_hi : 4'h0;
   wire       pend_ph_cur = pend_wide & pend_par_hi;
   wire [7:0] pend_data   = {pend_hi_cur, pend_lo};
   wire [3:0] pend_hi_nxt = pend_hi_cur ^ i_data[7:4];

    wire do_release = i_ce &&  stall &&  i_dready;
    wire do_direct  = i_ce && !stall &&  i_valid && (i_dready || !o_valid);
    wire do_capture = i_ce && !stall &&  i_valid && o_valid && !i_dready;
    wire do_drop    = i_ce && !stall && !i_valid && i_dready && o_valid;

    always @(posedge clk) begin
        if (rst) begin
            stall    <= 1'b0;
            skid      <= 4'h0;
            skid_hi   <= 4'h0;
            skid_wide <= 1'b0;
            skid_par <= 1'b0;
            o_valid  <= 1'b0;
            o_data   <= 8'h00;
            o_par    <= 1'b0;
            win      <= 1'b0;
            acc_data <= 8'h00;
            acc_par  <= 1'b0;
pend_lo     <= 4'h0;
pend_hi     <= 4'h0;
pend_wide   <= 1'b0;
pend_par    <= 1'b0;
pend_par_hi <= 1'b0;
o_beat_count <= 4'd0;
        end else begin
            // datapath
            if (do_release) begin
                o_valid <= 1'b1;
                o_data  <= skid_word;
                o_par   <= skid_par;
                stall   <= 1'b0;
            end else if (do_direct) begin
                o_valid <= 1'b1;
                o_data  <= i_data;
                o_par   <= ^i_data;
            end else if (do_capture) begin
                stall    <= 1'b1;
                skid      <= i_data[3:0];
                if (i_data[7:4] != 4'h0) begin
                    skid_hi   <= i_data[7:4];
                    skid_wide <= 1'b1;
                end else begin
                    skid_wide <= 1'b0;
                end
                skid_par <= ^i_data;
            end else if (do_drop) begin
                o_valid <= 1'b0;
            end

            // window: opened by a release, closed by i_close
            if (i_ce) begin
                if (i_close)         win <= 1'b0;
                else if (do_release) win <= 1'b1;
            end

            // in-window accumulation of released words
            if (do_release) begin
                if (win) begin
                    acc_data <= acc_data ^ skid_word;
                    acc_par  <= acc_par  ^ skid_par;
                end else begin
                    acc_data <= skid_word;
                    acc_par  <= skid_par;
                end
            end

          // pending tracker: a capture folds straight in through a four bit
          // datapath, so the upper nibble sits in its own slot and is only
          // clocked while the residue stays wide; a window close re-primes the
          // tracker with whatever word is still sitting in the skid slot
          if (i_ce && i_close) begin
              if (do_capture) begin
                  pend_lo   <= i_data[3:0];
                  pend_par  <= ^i_data;
                  if (i_data[7:4] != 4'h0) begin
                      pend_hi     <= i_data[7:4];
                      pend_par_hi <= ^i_data[7:4];
                      pend_wide   <= 1'b1;
                  end else begin
                      pend_wide   <= 1'b0;
                  end
              end else if (stall && !do_release) begin
                  pend_lo     <= skid;
                  pend_par    <= skid_par;
                  pend_hi     <= skid_hi;
                  pend_par_hi <= ^skid_hi;
                  pend_wide   <= skid_wide;
              end else begin
                  pend_lo   <= 4'h0;
                  pend_par  <= 1'b0;
                  pend_wide <= 1'b0;
              end
          end else if (do_capture) begin
              pend_lo <= pend_lo ^ i_data[3:0];
              if (i_data[7:4] != 4'h0) begin
                  if (pend_hi_nxt != 4'h0) begin
                      pend_hi     <= pend_hi_nxt;
                      pend_par_hi <= pend_ph_cur ^ (^i_data[7:4]);
                      pend_wide   <= 1'b1;
                      pend_par    <= pend_par ^ (^i_data);
                  end else begin
                      // upper nibble cancels out: retract its tracked parity
                      // instead of re-folding the whole byte
                      pend_wide <= 1'b0;
