   always @(*)
       o_ack_cnt = {n_win_opn, n_win_cls};

    // P: inside an open transfer window the engine is never simultaneously
    // reporting "busy" and "drained".
    always @(posedge i_clk)
        if (win)
            assert (!(busy && drained));

   // Q: the engine reports "drained" only once the issue-stage shadow has
   // counted the burst all the way down to zero beats.
   always @(posedge i_clk)
       assert (!drained || (shadow == 4'd0));

endmodule

