module dma_burst_dimmer (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,      // beat enable / idle when low
    input  wire       i_start,
    input  wire [3:0] i_beats,
    input  wire [3:0] i_duty,
    output wire       o_busy,
    output wire       o_beat,
output wire       o_pwm,
output reg  [3:0] o_ce_count
);

    // ---- DMA burst engine state ----
    reg [3:0] beats_left;   // beats remaining in the burst
    reg [3:0] done_cnt;     // beats already pushed out
    reg [3:0] total;        // beats requested by the accepted burst
    reg [3:0] duty;         // dimming level latched with the burst
    reg       busy;         // up exactly while beats remain
    reg [3:0] queued;       // beats accepted but not yet issued into the current chunk
   reg [3:0] chunk_pend;   // chunk staged for issue on the next beat
   // ---- fabric ledger: beats booked out to the fabric vs beats it consumed ----
   reg [3:0] n_iss;        // running count of beats issued to the fabric
   reg [3:0] n_ret;        // running count of beats the fabric has consumed

    initial beats_left = 4'd0;
    initial done_cnt   = 4'd0;
    initial total      = 4'd0;
    initial duty       = 4'd0;
    initial busy       = 1'b0;
    initial queued     = 4'd0;
   initial chunk_pend = 4'd0;
   initial n_iss      = 4'd0;
   initial n_ret      = 4'd0;
initial o_ce_count = 4'd0;

    // the fabric only accepts short chunks, so a long burst is issued piecewise
    localparam [3:0] CHUNK_MAX = 4'd4;
    wire [3:0] first_chunk = (i_beats > CHUNK_MAX) ? CHUNK_MAX : i_beats;
    wire [3:0] next_chunk  = (queued  > CHUNK_MAX) ? CHUNK_MAX : queued;
   // a beat is live on the bus exactly while the ledger shows work booked out
   wire outstanding = (n_iss != n_ret);

    always @(posedge i_clk) begin
        if (i_rst) begin
            beats_left <= 4'd0;
            done_cnt   <= 4'd0;
            total      <= 4'd0;
            duty       <= 4'd0;
            queued     <= 4'd0;
           chunk_pend <= 4'd0;
           n_iss      <= 4'd0;
           n_ret      <= 4'd0;
o_ce_count <= 4'd0;
            busy       <= 1'b0;
        end else if (i_start && !busy && (i_beats != 4'd0)) begin
            // accept a new burst
            beats_left <= first_chunk;
           n_iss      <= n_iss + first_chunk;
            queued     <= i_beats - first_chunk;
            total      <= i_beats;
            done_cnt   <= 4'd0;
            duty       <= i_duty;
            busy       <= 1'b1;
        end else if (i_ce) begin
            // retire one beat
            if (beats_left > 4'd1) begin
                beats_left <= beats_left - 4'd1;
            end else if (beats_left == 4'd1) begin
               // current chunk drained: stage the next chunk, the fabric
               // needs a cycle of turnaround before it can be issued
               beats_left <= 4'd0;
               chunk_pend <= next_chunk;
                queued     <= queued - next_chunk;
           end else if (chunk_pend != 4'd0) begin
               // staged chunk lands in the beat counter
               beats_left <= chunk_pend;
               chunk_pend <= 4'd0;
           end
           // ledger bookkeeping: one beat is consumed per enabled cycle, and a
           // staged chunk is booked out to the fabric when it lands
           if (beats_left != 4'd0)
               n_ret <= n_ret + 4'd1;
           else if (chunk_pend != 4'd0)
               n_iss <= n_iss + chunk_pend;
