module gfx_frame_fsm (
    input  wire clk,
    input  wire i_reset,
    input  wire i_ce,
    input  wire i_start,
    output wire o_vsync,
    output wire [2:0] o_state
);
    // binary-encoded frame pipeline states; 5,6,7 are unreachable encodings
    localparam [2:0] S_IDLE    = 3'd0;
    localparam [2:0] S_CLEAR   = 3'd1;
    localparam [2:0] S_DRAW    = 3'd2;
    localparam [2:0] S_BLIT    = 3'd3;
    localparam [2:0] S_PRESENT = 3'd4;
   // overlay plane pipeline stages (shares the framebuffer with the frame pipeline)
   localparam [1:0] OV_IDLE = 2'd0;
   localparam [1:0] OV_CLR  = 2'd1;
   localparam [1:0] OV_FILL = 2'd2;
   localparam [1:0] OV_SWAP = 2'd3;
   // hardware cursor plane: repaints the sprite after the overlay refresh
   localparam [1:0] CU_IDLE  = 2'd0;
   localparam [1:0] CU_FETCH = 2'd1;
   localparam [1:0] CU_PAINT = 2'd2;
   localparam [1:0] CU_DONE  = 2'd3;
// shared framebuffer write port: an update is staged here for one cycle
localparam [2:0] FB_NOP = 3'd0;
localparam [2:0] FB_CLR = 3'd1;
localparam [2:0] FB_OVL = 3'd2;
localparam [2:0] FB_CUR = 3'd3;

    reg [2:0] state;
    reg [1:0] draw_cnt;
    reg       cleared_seen;   // shadow: framebuffer was cleared this frame
   reg [1:0] ov_state;      // overlay plane pipeline
   reg       ov_pend;       // overlay refresh owed after the last frame
reg [2:0] fb_cmd;        // framebuffer update in flight to the shadow
reg [1:0] cur_state;     // hardware cursor plane pipeline
reg       cur_pend;      // cursor repaint owed after the last frame

    initial state        = S_IDLE;
    initial draw_cnt     = 2'd0;
    initial cleared_seen = 1'b0;
   initial ov_state     = OV_IDLE;
   initial ov_pend      = 1'b0;
initial fb_cmd       = FB_NOP;
initial cur_state    = CU_IDLE;
initial cur_pend     = 1'b0;

    wire draw_done = (draw_cnt == 2'd3);
   // framebuffer arbitration: the frame pipeline may only start a new frame
   // when no overlay refresh is running or owed
  wire fb_free = (ov_state == OV_IDLE) && !ov_pend &&
                 (cur_state == CU_IDLE) && !cur_pend;

    always @(posedge clk) begin
        if (i_reset) begin
            state        <= S_IDLE;
            draw_cnt     <= 2'd0;
            cleared_seen <= 1'b0;
           ov_state     <= OV_IDLE;
           ov_pend      <= 1'b0;
fb_cmd       <= FB_NOP;
           cur_state    <= CU_IDLE;
           cur_pend     <= 1'b0;
        end else if (i_ce) begin
            case (state)
                S_IDLE: begin
                   if (i_start && fb_free) begin
                        state    <= S_CLEAR;
                        draw_cnt <= 2'd0;
                    end
                end
                S_CLEAR: begin
// the clear pass hands its update to the framebuffer write port
// rather than touching the shadow directly
fb_cmd       <= FB_CLR;
                    state        <= S_DRAW;
                end
                S_DRAW: begin
                    if (draw_done)
                        state <= S_BLIT;
                    else
                        draw_cnt <= draw_cnt + 2'd1;
                end
                S_BLIT: begin
                    state <= S_PRESENT;
                end
                S_PRESENT: begin
                    state        <= S_IDLE;
                    draw_cnt     <= 2'd0;
                    cleared_seen <= 1'b0;
                   ov_pend      <= 1'b1;   // overlay gets the buffer next
                  cur_pend     <= 1'b1;   // cursor repaints after the overlay
                end
                default: begin
                    // encodings 5/6/7 never occur by construction; the
                    // synthesised decoder folds them onto the present stage
                    state <= S_PRESENT;
                end
            endcase

           // Overlay plane pipeline: same shape as the frame pipeline above,
           // but it borrows the framebuffer and the shared pass counter, so it
           // only runs in the gap between frames.
           case (ov_state)
               OV_IDLE: begin
                   if (ov_pend && state == S_IDLE) begin
                       ov_state <= OV_CLR;
                       ov_pend  <= 1'b0;
                   end
               end
               OV_CLR: begin
                   ov_state <= OV_FILL;
                   draw_cnt <= 2'd0;
               end
               OV_FILL: begin
// overlay writes land on the shared framebuffer, so the recorded
// clear stops describing its contents once this update retires
fb_cmd <= FB_OVL;
                   if (draw_cnt == 2'd1)
                       ov_state <= OV_SWAP;
                   else
                       draw_cnt <= draw_cnt + 2'd1;
               end
               OV_SWAP: begin
                   ov_state <= OV_IDLE;
                   draw_cnt <= 2'd0;
               end
           endcase

          // Hardware cursor plane: a third client of the framebuffer write
          // port.  It repaints the sprite once the overlay refresh has
          // retired, and reuses the shared pass counter for its fill loop.
          case (cur_state)
              CU_IDLE: begin
                  if (cur_pend && state == S_IDLE &&
                      ov_state == OV_IDLE && !ov_pend) begin
                      cur_state <= CU_FETCH;
                      cur_pend  <= 1'b0;
                  end
              end
              CU_FETCH: begin
                  cur_state <= CU_PAINT;
                  draw_cnt  <= 2'd0;
              end
              CU_PAINT: begin
                  if (draw_cnt == 2'd2)
                      cur_state <= CU_DONE;
                  else
                      draw_cnt <= draw_cnt + 2'd1;
              end
              CU_DONE: begin
                  cur_state <= CU_IDLE;
                  draw_cnt  <= 2'd0;
              end
          endcase
// Shared framebuffer write port.  The staged command retires into the
// shadow here, one cycle after the pass that issued it, and the port is
// re-armed in the same cycle.  The frame pipeline wins the port if both
// planes ask for it in the same cycle.
if (fb_cmd == FB_CLR)
    cleared_seen <= 1'b1;
else if (fb_cmd == FB_OVL || fb_cmd == FB_CUR)
    cleared_seen <= 1'b0;
if (state == S_CLEAR)
    fb_cmd <= FB_CLR;
else if (ov_state == OV_FILL)
    fb_cmd <= FB_OVL;
else if (cur_state == CU_PAINT)
    fb_cmd <= FB_CUR;
else
    fb_cmd <= FB_NOP;
        end
    end

    assign o_vsync = (state == S_PRESENT);
    assign o_state = state;

    // Precedence, global: presenting a frame implies the clear pass happened earlier
    always @(posedge clk)
        if (state == S_PRESENT)
            assert (cleared_seen);
