module gray_shadow_ctr (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,
    output wire [3:0] o_gray,
output wire [3:0] o_bin,
output reg  [3:0] ce_hist
);
    // Binary shadow counter and its gray-coded twin.  The gray register is
    // advanced by the classic single-bit-toggle rule, computed from the gray
    // value alone; the binary shadow is a plain increment.
// The shadow count is split: the low three bits take the increment, and the
// top bit is a separate flop toggled by a carry term that is precomputed one
// cycle ahead (lo_max), so the top bit never hangs off the low adder's carry
// chain.  lo_max is only re-evaluated on cycles that actually advance the
// count, so it is static while the counter is stalled.
reg [2:0] bin_lo;
reg       bin_hi;
reg       lo_max;
wire [3:0] bin = {bin_hi, bin_lo};
    reg [3:0] gray;
    reg       pv;
   reg [3:0] gray_s;
   reg       s_vld;
reg       ce_d;

initial bin_lo = 3'b000;
initial bin_hi = 1'b0;
initial lo_max = 1'b0;
    initial gray = 4'b0000;
    initial pv   = 1'b0;
   initial gray_s = 4'b0000;
   initial s_vld  = 1'b0;
initial ce_d    = 1'b0;
initial ce_hist = 4'b0000;

    // Next gray value: toggle bit 0 when the parity is even, otherwise toggle
    // the bit just above the lowest set bit (with the top bit handling wrap).
    function [3:0] gnext(input [3:0] g);
        begin
            if (!(^g))     gnext = g ^ 4'b0001;
            else if (g[0]) gnext = g ^ 4'b0010;
            else if (g[1]) gnext = g ^ 4'b0100;
            else           gnext = g ^ 4'b1000;
        end
    endfunction

   // Stage 1: the gray pointer is advanced one cycle ahead of the output
   // registers, so o_gray leaves the block straight off a flop instead of
   // through the toggle-select network.  s_vld marks the staged word as a
   // pending advance that the commit stage still owes the outputs.
   always @(posedge clk) begin
       if (rst) begin
           gray_s <= 4'b0000;
           s_vld  <= 1'b0;
ce_d    <= 1'b0;
ce_hist <= 4'b0000;
       end else begin
           s_vld <= i_ce;
ce_d    <= i_ce;
ce_hist <= {ce_hist[2:0], ce_d};
           if (i_ce) gray_s <= gnext(gray_s);
       end
   end

   // Stage 2: commit the staged pointer and bump the binary shadow in the
   // same cycle, so the two views never disagree at the outputs.

    always @(posedge clk) begin
        if (rst) begin
bin_lo <= 3'b000;
bin_hi <= 1'b0;
lo_max <= 1'b0;
            gray <= 4'b0000;
       end else if (s_vld) begin
bin_lo <= bin_lo + 3'b001;
bin_hi <= bin_hi ^ lo_max;
lo_max <= (bin_lo == 3'b110);
           gray <= gray_s;
        end
    end

    always @(posedge clk)
        pv <= 1'b1;

    assign o_gray = gray;
    assign o_bin  = bin;

    // Top bit of the gray word and top bit of the binary shadow: the most
    // significant gray bit is just the most significant binary bit, so neither
    // may move without the other.
    wire g_msb = gray[3];
    wire b_msb = bin[3];

    // P: whenever the gray MSB did not change, the shadow MSB did not change.
    always @(posedge clk)
        if (pv && $stable(g_msb))
            assert ($stable(b_msb));
endmodule

