    // fixed-priority arbiter with a lock bit that freezes the winner
    reg [3:0] grant;
    reg       lock;
    // shadow occupancy counter: how many grants are currently outstanding
    reg [2:0] occ;
    // lock-hold timer: beats the current owner has held the bus
    reg [2:0] hold_cnt;
   // bus turnaround: dead beats after a release before the slot is freed
   reg [1:0] tail_cnt;
   // one-deep drain slot: a released owner keeps its occupancy credit
   // here until the credit-return beat that follows the turnaround
   reg        drn;

    initial grant = 4'b0000;
    initial lock  = 1'b0;
    initial occ   = 3'd0;
    initial hold_cnt = 3'd0;
   initial tail_cnt = 2'd0;
   initial drn = 1'b0;

    wire        busy    = (grant != 4'b0000);
    wire        any_req = (i_req != 4'b0000);

