          else if (grp) gray_c <= bin_nxt ^ (bin_nxt >> 1);
          else          gray   <= bin_nxt ^ (bin_nxt >> 1);
          bin       <= bin_hold;
          bin_hold  <= bin_hold2;
          bin_hold2 <= bin_nxt;
          turn      <= !turn && !grp;
          grp       <= turn;
