module hist_precedence (
    input  wire       clk,
    input  wire       i_ce,
    input  wire       i_op,     // 0 = add one sample to bin i_sel, 1 = remove one
    input  wire [1:0] i_sel,
output reg  [5:0] total,
output reg  [3:0] ce_count
);
    // histogram bins
    reg [3:0] bin0, bin1, bin2, bin3;

    // shadow of the earlier event: which bin got the very first sample
    reg [1:0] first_bin;
    reg       saw_sample;

    // scope arming register: high until the first removal aimed at first_bin
    reg       pre_purge;

    // shadow high-water mark of the first-sampled bin's count
    reg [3:0] hi_first;

   // staged high-water update: the shadow compare is registered, so a
   // candidate count lands in hi_first one enabled cycle later
   reg [3:0] hw_pend;
   reg       hw_vld;
// distractor bookkeeping: history of the op input on enabled cycles
reg [3:0] op_shift;

    initial begin
        bin0       = 4'd0;
        bin1       = 4'd0;
        bin2       = 4'd0;
        bin3       = 4'd0;
        total      = 6'd0;
        first_bin  = 2'd0;
        saw_sample = 1'b0;
        pre_purge  = 1'b1;
        hi_first   = 4'd0;
       hw_pend    = 4'd0;
       hw_vld     = 1'b0;
op_shift   = 4'd0;
ce_count   = 4'd0;
    end

    wire [3:0] sel_cnt   = (i_sel == 2'd0) ? bin0 :
                           (i_sel == 2'd1) ? bin1 :
                           (i_sel == 2'd2) ? bin2 : bin3;

    wire [3:0] first_cnt = (first_bin == 2'd0) ? bin0 :
                           (first_bin == 2'd1) ? bin1 :
                           (first_bin == 2'd2) ? bin2 : bin3;

   // acquisition freezes once the first-sampled bin has saturated
   wire frozen = (hi_first == 4'd15);


   wire do_add = i_ce && !i_op && (total != 6'd31) && (sel_cnt != 4'd15) && !frozen;
    wire do_rem = i_ce &&  i_op && (sel_cnt != 4'd0);
    wire purge  = i_ce &&  i_op && saw_sample && (i_sel == first_bin);

    wire armed  = pre_purge && saw_sample;

    // count the first-sampled bin will hold after this cycle
    wire [3:0] first_nxt =
        (do_add && !saw_sample)                          ? (sel_cnt   + 4'd1) :
        (do_add && saw_sample && (i_sel == first_bin))    ? (first_cnt + 4'd1) :
        (do_rem && saw_sample && (i_sel == first_bin))    ? (first_cnt - 4'd1) :
                                                            first_cnt;

    always @(posedge clk) begin
        if (i_ce) begin
            if (do_add) begin
                total <= total + 6'd1;
                case (i_sel)
                    2'd0:    bin0 <= bin0 + 4'd1;
                    2'd1:    bin1 <= bin1 + 4'd1;
                    2'd2:    bin2 <= bin2 + 4'd1;
                    default: bin3 <= bin3 + 4'd1;
                endcase
                if (!saw_sample) begin
                    saw_sample <= 1'b1;
                    first_bin  <= i_sel;
                end
            end else if (do_rem) begin
                total <= total - 6'd1;
                case (i_sel)
                    2'd0:    bin0 <= bin0 - 4'd1;
                    2'd1:    bin1 <= bin1 - 4'd1;
                    2'd2:    bin2 <= bin2 - 4'd1;
                    default: bin3 <= bin3 - 4'd1;
                endcase
            end

            if (purge)
                pre_purge <= 1'b0;

           // commit the candidate captured on the previous enabled cycle
           if (hw_vld && (hw_pend > hi_first))
               hi_first <= hw_pend;


           if (do_add && !saw_sample) begin
               hw_pend <= sel_cnt + 4'd1;
               hw_vld  <= 1'b1;
           end else if (first_nxt > hi_first) begin
               hw_pend <= first_nxt;
               hw_vld  <= 1'b1;
           end else begin
               hw_vld  <= 1'b0;
           end
        end
    end

    // P: before any sample has ever been purged from the first-sampled bin,
    // the earlier arrival recorded in the shadow registers must still be
    // accounted for in the total-samples register.
    always @(posedge clk)
        if (armed) assert (total >= 6'd1);

    always @(posedge clk)
        if (armed) assert (total >= {2'b00, hi_first});
always @(posedge clk) begin
    if (i_ce) begin
        op_shift <= {op_shift[2:0], i_op};
        ce_count <= ce_count + 4'd1 + {3'd0, op_shift[3]};
    end
end
endmodule

