module elastic_two_entry (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_push,
    input  wire       i_pop,
    input  wire [7:0] i_data,
    output wire       o_valid,
    output wire       o_full,
    output wire [7:0] o_data,
    output wire [2:0] o_count
);

    // ---- two-entry elastic buffer -------------------------------------
    // one valid flag per slot, plus head/tail slot selectors.
    reg        v0, v1;      // slot occupancy flags
    reg        head, tail;  // which slot is read / written next
    reg [7:0]  d0, d1;      // slot payloads
    reg [2:0]  count;       // redundant occupancy counter
   reg [2:0]  credits;     // free slots left, advertised upstream

    initial v0    = 1'b0;
    initial v1    = 1'b0;
    initial head  = 1'b0;
    initial tail  = 1'b0;
    initial d0    = 8'h00;
    initial d1    = 8'h00;
    initial count = 3'd0;
   initial credits = 3'd2;

// status: valid/data come from the FLAGS, full comes from the credit count
assign o_full  = (credits == 3'd0);
    assign o_valid = v0 || v1;
    assign o_data  = head ? d1 : d0;
    assign o_count = count;

    wire do_push = i_push && !o_full;
    wire do_pop  = i_pop  &&  o_valid;

    // idle condition: i_push == 0 && i_pop == 0 leaves all state alone
    always @(posedge i_clk) begin
        if (i_rst) begin
            v0    <= 1'b0;
            v1    <= 1'b0;
            head  <= 1'b0;
            tail  <= 1'b0;
            d0    <= 8'h00;
            d1    <= 8'h00;
            count <= 3'd0;
credits <= 3'd2;
        end else begin
            if (do_push) begin
                if (tail == 1'b0) begin
                    v0 <= 1'b1;
                    d0 <= i_data;
                end else begin
                    v1 <= 1'b1;
                    d1 <= i_data;
                end
                tail <= ~tail;
            end

            if (do_pop) begin
                if (head == 1'b0)
                    v0 <= 1'b0;
                else
                    v1 <= 1'b0;
                head <= ~head;
            end

            count <= count + (do_push ? 3'd1 : 3'd0)
                            - (do_pop  ? 3'd1 : 3'd0);

           credits <= credits - (do_push ? 3'd1 : 3'd0)
                             + (do_pop  ? 3'd1 : 3'd0);
        end
    end

    // ---- property: while the buffer holds anything, the occupancy
    //      counter never exceeds the two-entry depth (the register is
    //      three bits wide, so 3..7 are representable).
    always @(posedge i_clk)
        if (o_valid)
            assert (count <= 3'd2);

   // ---- property: a lone resident word sits between the two pointers
   //      (head and tail must differ) and leaves exactly one credit.
   always @(posedge i_clk)
       if (count == 3'd1)
           assert ((head != tail) && (credits == 3'd1));

endmodule

