module pingpong_rotbuf (
    input  wire        clk,
    input  wire        step,      // enable / idle when low
    input  wire [15:0] din,
    input  wire [3:0]  amt,
    output reg  [15:0] dout,
    output wire        wr_half,
    output wire        rd_half
);
    // ------------------------------------------------------------------
    // one-cycle barrel rotator (staged shift-by-1/2/4/8 collapses to this)
    // ------------------------------------------------------------------
    wire [31:0] dbl = {din, din};
    wire [15:0] rot = dbl[15:0] >> amt | dbl[31:16] << (16 - amt);

    // ------------------------------------------------------------------
    // ping-pong double buffer: 2 halves of 4 words.
    // address = {half_select, index}
    // ------------------------------------------------------------------
    reg [2:0] waddr;
    reg [2:0] raddr;
    reg [15:0] mem [0:7];
    reg        pv;

   // registered write path: the rotate result and its destination slot are
   // captured on one enabled cycle and retired into the array on the next.
   reg [15:0] wdat_q;
   reg [2:0]  wadr_q;
   reg        wval_q;

   // per-port bank arbiter grant, raised one index ahead of the wrap so the
   // half-select mux is driven by a register instead of a comparator.
   reg        wsw_q;
   reg        rsw_q;

  // ------------------------------------------------------------------
  // scrub/refill channel: a second write channel that walks the half the
  // reader is draining and rewrites every word byte-swapped, sharing the
  // rotator and the single array write port with the main channel.
  // ------------------------------------------------------------------
  reg [1:0]  aidx;    // scrub word pointer inside its half
  reg        abank;   // half the scrubber is currently refilling
  reg        adone;   // pass complete, raised one slot ahead of the wrap
  reg [15:0] sdat_q;  // registered scrub write path, mirrors wdat_q/wadr_q
  reg [2:0]  sadr_q;
  reg        pgnt;    // scrubber owns the shared array port this slot

    integer i;
    initial begin
        waddr = 3'b000;   // writer starts in half 0
        raddr = 3'b100;   // reader starts in half 1
        dout  = 16'h0000;
        pv    = 1'b0;
       wdat_q = 16'h0000;
       wadr_q = 3'b000;
       wval_q = 1'b0;
       wsw_q  = 1'b0;
       rsw_q  = 1'b0;
      aidx   = 2'b00;
      abank  = 1'b1;
      adone  = 1'b0;
      sdat_q = 16'h0000;
      sadr_q = 3'b100;
      pgnt   = 1'b0;
        for (i = 0; i < 8; i = i + 1) mem[i] = 16'h0000;
    end

    assign wr_half = waddr[2];
    assign rd_half = raddr[2];

    // each side flips its own half when its own index field wraps
   // grant is requested one slot early and consumed on the wrap itself
   wire wgrant = (waddr[1:0] == 2'b10);
   wire rgrant = (raddr[1:0] == 2'b10);

  // the scrubber asks for the shared port on the last slot of its pass
  wire arq = (aidx == 2'b11);

