module wdt_absence (
    input  wire       clk,
    input  wire       i_ce,      // global enable / idle condition
    input  wire       arm,       // Q: opens the window
    input  wire       disarm,    // R: closes the window (may never arrive)
    input  wire       kick,      // pet the watchdog
    output reg  [3:0] cnt,
    output reg        expired,
    output reg        safe,
output reg        armed,
output reg [3:0] kick_cnt,
output reg [3:0] disarm_cnt
);
    localparam [3:0] LIMIT = 4'd10;  // timeout value
    localparam [3:0] WARN  = 4'd8;   // below this the timer is in the safe zone
    localparam [1:0] GRACE = LIMIT - WARN;  // warning-zone dwell before timeout
    reg [1:0] grace;                        // ticks elapsed since cnt hit WARN
reg [3:0] evt_shift;
localparam [3:0] STAGE = 4'd4;          // half of the pre-warning interval
reg [3:0] stage2;                       // pre-warning ticks past the halfway mark
localparam [3:0] QSTAGE = 4'd2;         // quarter of the pre-warning interval
reg [3:0] stage3;                       // pre-warning ticks in the final quarter
localparam [3:0] B_LIMIT = 4'd3;        // backup trip point, in prescaled units
reg [1:0] b_tick;                       // /4 prescaler of the backup watchdog
reg [3:0] b_cnt;                        // prescaled ticks since the last kick
reg       hard;                         // backup watchdog has tripped

    initial cnt     = 4'd0;
    initial expired = 1'b0;
    initial safe    = 1'b1;
    initial armed   = 1'b0;
    initial grace   = 2'd0;
initial kick_cnt = 4'd0;
initial disarm_cnt = 4'd0;
initial evt_shift = 4'd0;
initial stage2 = 4'd0;
initial stage3 = 4'd0;
initial b_tick = 2'd0;
initial b_cnt  = 4'd0;
initial hard   = 1'b0;

    always @(posedge clk) begin
        if (i_ce) begin
// bookkeeping only: how many kicks have been seen
if (kick)
kick_cnt <= kick_cnt + 4'd1;
evt_shift <= {evt_shift[2:0], disarm};
if (disarm && !arm)
disarm_cnt <= disarm_cnt + 4'd1 + {3'd0, evt_shift[3]};
            // window register: set by arm, cleared by disarm
            if (arm)
                armed <= 1'b1;
            else if (disarm)
                armed <= 1'b0;

            // the watchdog only runs inside the window
            if (armed) begin
                if (kick) begin
                    cnt     <= 4'd0;
stage2  <= 4'd0;
stage3  <= 4'd0;
                    grace   <= 2'd0;
                    expired <= 1'b0;
                    safe    <= 1'b1;
end else if (cnt < STAGE) begin
// first half of the pre-warning interval is held in cnt
                    cnt     <= cnt + 4'd1;
end else if (stage2 < QSTAGE) begin
// cnt is frozen at the halfway mark and the third quarter of
// the pre-warning interval accumulates here
stage2  <= stage2 + 4'd1;
end else if (stage3 < QSTAGE) begin
// final quarter before the warning threshold; dropping out of
// it is what takes the timer out of the safe zone
stage3  <= stage3 + 4'd1;
safe    <= ((stage3 + 4'd1) < QSTAGE);
                end else if (grace < GRACE) begin
// once every pre-warning stage is full the remaining ticks before
                    // timeout are accumulated here, so the warning-zone dwell
                    // can be reported on its own
                    grace   <= grace + 2'd1;
                    expired <= ((grace + 2'd1) == GRACE);
                    safe    <= 1'b0;
                end
            end

           // backup watchdog: same window and same kick, but clocked at a
           // quarter rate so it trips after the primary one; when it trips it
           // latches the expiry flag so the fault cannot be missed
           if (armed) begin
               if (kick) begin
                   b_tick <= 2'd0;
                   b_cnt  <= 4'd0;
                   hard   <= 1'b0;
               end else if (!hard) begin
                   if (b_tick == 2'd3) begin
                       b_tick <= 2'd0;
                       b_cnt  <= b_cnt + 4'd1;
                       if ((b_cnt + 4'd1) == B_LIMIT) begin
                           hard    <= 1'b1;
                           expired <= 1'b1;
                       end
                   end else begin
                       b_tick <= b_tick + 2'd1;
                   end
               end else begin
                   expired <= 1'b1;
               end
           end
        end
    end

    // P: once armed (and until disarmed, if ever), the timer can never report
    // both "expired" and "safe" at the same time.
    always @(*)
        if (armed)
            assert (!(expired && safe));
endmodule

