module phase_divider_pair (
    input  wire       clk,
    input  wire       ce,       // divider step enable; low = idle, all state held
    input  wire       resync,   // realigns both phase counters, retires the pristine scope
    output reg  [2:0] phase,    // primary phase counter, mod 5
    output reg  [2:0] cnt,      // skewed phase counter, mod 5, built 2 phases ahead
    output reg        en_load,  // divided enable: fires the cycle after phase wraps
    output reg        en_sample,// divided enable: fires the cycle after cnt wraps
    output reg        pristine  // high until the first resync has ever happened
);

    // Load/sample ledger: every load pulse and every sample pulse is logged
    // for the lifetime of the current alignment, so the buffer downstream can
    // account for the two divided enables it sees.
    reg  [3:0] n_load;   // count of load pulses issued
    reg  [3:0] n_samp;   // count of sample pulses issued

    // samples that do not have a matching load behind them yet
    wire [3:0] samp_ahead = n_samp - n_load;
    // a realignment can leave the ping-pong buffer starved; while the sample
    // side is two or more entries ahead, inject make-up load pulses
    wire       makeup     = (samp_ahead >= 4'd2);

   // Skew-buffer ledger: the sample pulse captures one entry into the
   // ping-pong skew buffer and the load pulse releases it to the sink, so
   // both sides are logged as the buffer sees them, on the divided enables.
   reg  [3:0] n_cap;    // entries captured by the sample side
   reg  [3:0] n_rel;    // entries released by the load side
// the bank write port is pipelined four deep (stage, format, protect, commit):
// a sample pulse enters the first stage and only lands in the array four
// enabled cycles later, so n_cap advances off the last stage.  The load side
// reads through a forwarding path, so occupancy counts the in-flight entries.
reg        cap_pend; // entry staged by the sample side, not yet committed
reg        cap_s2;   // write pipe stage 2 (format)
reg        cap_s3;   // write pipe stage 3 (protect)
reg        cap_s4;   // write pipe stage 4 (commit into the array)
// the load side is a read pipeline of the same depth (address, array read,
// ECC correct, output register): a release only leaves the array four
// enabled cycles after its load pulse.  An in-flight read is already spoken
// for, so it leaves the occupancy the moment the pulse is issued.
reg        rel_s1;   // read pipe stage 1 (address)
reg        rel_s2;   // read pipe stage 2 (array read)
reg        rel_s3;   // read pipe stage 3 (ECC correct)
reg        rel_s4;   // read pipe stage 4 (retire from the array)
wire [3:0] level     = n_cap + {3'd0, cap_pend} + {3'd0, cap_s2}
                       + {3'd0, cap_s3} + {3'd0, cap_s4} - n_rel
                       - {3'd0, rel_s1} - {3'd0, rel_s2}
                       - {3'd0, rel_s3} - {3'd0, rel_s4};
   // the load side must not release an entry the sample side has not
   // captured yet, so the phase-4 pulse waits for a filled buffer
   wire       bank_full = (level != 4'd0);

   // Load-side stall watchdog: the sink downstream must never be left
   // without a load pulse for long, so the gap since the last one is timed
   // and a make-up pulse is forced once that gap gets too wide.
   reg  [2:0] gap;      // enabled cycles since the last load pulse
   wire       wdog       = (gap >= 3'd6);
wire       load_pulse = ((phase == 3'd4) && bank_full) || makeup || wdog;

    // The skewed counter is constructed 2 phases ahead of the primary phase
    // counter, so the two divided-enable pulses are interleaved by design.
    initial phase     = 3'd0;
    initial cnt       = 3'd2;
    initial en_load   = 1'b0;
    initial en_sample = 1'b0;
    initial pristine  = 1'b1;
    initial n_load    = 4'd0;
    initial n_samp    = 4'd0;
initial n_cap     = 4'd0;
initial n_rel     = 4'd0;
initial cap_pend  = 1'b0;
initial cap_s2    = 1'b0;
initial cap_s3    = 1'b0;
initial cap_s4    = 1'b0;
initial rel_s1    = 1'b0;
initial rel_s2    = 1'b0;
initial rel_s3    = 1'b0;
initial rel_s4    = 1'b0;
   initial gap       = 3'd0;

    always @(posedge clk) begin
        if (resync) begin
            // hard realignment: both phase counters are slammed to zero, which
            // destroys the constructed skew (and retires the pristine scope)
            phase     <= 3'd0;
            cnt       <= 3'd0;
            en_load   <= 1'b0;
            en_sample <= 1'b0;
            pristine  <= 1'b0;
            n_load    <= 4'd0;
            n_samp    <= 4'd0;
n_cap     <= 4'd0;
n_rel     <= 4'd0;
cap_pend  <= 1'b0;
cap_s2    <= 1'b0;
cap_s3    <= 1'b0;
cap_s4    <= 1'b0;
rel_s1    <= 1'b0;
rel_s2    <= 1'b0;
rel_s3    <= 1'b0;
rel_s4    <= 1'b0;
           gap       <= 3'd0;
        end
        else if (ce) begin
            phase     <= (phase == 3'd4) ? 3'd0 : phase + 3'd1;
            cnt       <= (cnt   == 3'd4) ? 3'd0 : cnt   + 3'd1;
            // each divided enable pulses exactly when its phase counter wraps
           en_load   <= load_pulse;
            en_sample <= (cnt   == 3'd4);
            // ledger entries are made as the pulses are issued
           n_load    <= n_load + (load_pulse ? 4'd1 : 4'd0);
            n_samp    <= n_samp + ((cnt == 3'd4) ? 4'd1 : 4'd0);
cap_pend  <= en_sample;
cap_s2    <= cap_pend;
cap_s3    <= cap_s2;
cap_s4    <= cap_s3;
n_cap     <= n_cap + (cap_s4 ? 4'd1 : 4'd0);
rel_s1    <= en_load;
rel_s2    <= rel_s1;
rel_s3    <= rel_s2;
rel_s4    <= rel_s3;
n_rel     <= n_rel + (rel_s4 ? 4'd1 : 4'd0);
           gap       <= load_pulse ? 3'd0 : gap + 3'd1;
        end
    end

    // Absence: while the divider has never been resynced, the two divided
    // enables are never asserted in the same cycle.
    always @(posedge clk)
        if (pristine)
            assert (!(en_load && en_sample));

   // Alignment: while the divider has never been resynced, the sample pulse
   // always lands three enabled cycles into the current load window.
   always @(posedge clk)
       if (pristine)
           assert (!en_sample || (gap == 3'd3));

endmodule

