module elastic_occupancy (
    input  wire       clk,
    input  wire       rst,
    input  wire       push,
    input  wire       pop,
    input  wire [7:0] din,
    output wire [7:0] dout,
    output wire       o_empty,
    output wire       o_full,
    output wire [1:0] o_count
);
    // two-entry elastic buffer: d0 is the head (output side), d1 the tail slot.
    // occupancy is encoded twice: thermometer valid flags {v1,v0} and count.
    reg       v0, v1;
    reg [1:0] count;
    // upstream credit: number of empty slots, maintained incrementally so the
    // full indication does not have to decode the valid flags
    reg [1:0] free;
   // peak occupancy telemetry: high-water mark of the occupancy counter since
   // reset, sampled every cycle and read back on the data output while the
   // buffer is empty (the head slot carries no valid word then)
   reg [1:0] hwm;
  // the peak comparator is retimed behind a stage register: the occupancy
  // that will be resident next cycle is captured here and is compared
  // against the high-water mark on the following edge, so the occupancy
  // adders and the comparator no longer share one cycle of timing budget
  reg [1:0] peak_q;
 // the peak telemetry is filed per stage: hwm is the head buffer's mark and
 // hwm_b the spill stage's, so a deep backlog waiting in the spill stage is
 // not reported as deep head occupancy. peak_sel remembers which mark the
 // staged sample belongs to, since the comparison happens a cycle after the
 // sample is captured.
 reg [1:0] hwm_b;
 reg       peak_sel;
    reg [7:0] d0, d1;

   // spill stage: a second two-entry buffer sitting behind the head buffer so
   // a burst is not backpressured while the head buffer is draining. words
   // leave the spill stage in arrival order and refill the head buffer.
   reg       vb0, vb1;
   reg [1:0] cntb;
   reg [7:0] b0, b1;
  // landing register on the spill write path: din is electrically far from
  // the spill array, so a word routed to the spill stage is captured here
  // first and written into the array on a later cycle, once it has room
  reg       sv;
  reg [7:0] sd;

    initial v0    = 1'b0;
    initial v1    = 1'b0;
    initial count = 2'd0;
    initial free  = 2'd2;
   initial hwm   = 2'd0;
  initial peak_q = 2'd0;
 initial hwm_b    = 2'd0;
 initial peak_sel = 1'b0;
    initial d0    = 8'h00;
    initial d1    = 8'h00;
   initial vb0   = 1'b0;
   initial vb1   = 1'b0;
   initial cntb  = 2'd0;
   initial b0    = 8'h00;
   initial b1    = 8'h00;
  initial sv    = 1'b0;
  initial sd    = 8'h00;

    // handshake qualifiers are derived from the FLAGS, not from count
  wire push_a  = push && !v1 && !vb0 && !sv;      // straight in when nothing is queued
  wire push_b  = push && !sv && !vb1 && !push_a;  // otherwise the word is staged
  wire land    = sv && !vb1;               // staged word enters the spill array
   wire refill  = vb0 && !v1;               // backlog moves up when a slot frees
   wire do_push = push_a || refill;         // head buffer write enable
    wire do_pop  = pop  &&  v0;
   wire [7:0] a_din  = push_a ? din : b0;
  // next-state occupancy of whichever stage the upstream is feeding; the
  // single shared comparator sees it one cycle later, through peak_q
  wire [1:0] count_nxt = count + (do_push ? 2'd1 : 2'd0) - (do_pop ? 2'd1 : 2'd0);
 wire [1:0] cntb_nxt  = cntb  + (land ? 2'd1 : 2'd0) - (refill ? 2'd1 : 2'd0);
 wire       vb0_nxt   = (land && !refill) ? 1'b1 :
                        (refill && !land) ? vb1  : vb0;
 wire       sv_nxt    = push_b ? 1'b1 : (land ? 1'b0 : sv);
 // the spill-side telemetry reports the whole spill path: the array plus a
 // word still waiting in the landing register
 wire [1:0] bklg_nxt  = cntb_nxt + (sv_nxt ? 2'd1 : 2'd0);
 wire [1:0] occ_nxt   = (vb0_nxt || sv_nxt) ? bklg_nxt : count_nxt;

    always @(posedge clk) begin
        if (rst) begin
            v0    <= 1'b0;
            v1    <= 1'b0;
            count <= 2'd0;
            free  <= 2'd2;
           hwm   <= 2'd0;
          peak_q <= 2'd0;
         hwm_b    <= 2'd0;
         peak_sel <= 1'b0;
            d0    <= 8'h00;
            d1    <= 8'h00;
           vb0   <= 1'b0;
           vb1   <= 1'b0;
           cntb  <= 2'd0;
           b0    <= 8'h00;
           b1    <= 8'h00;
          sv    <= 1'b0;
          sd    <= 8'h00;
        end else begin
            if (do_push && !do_pop) begin
                if (!v0) begin
                   d0 <= a_din;
                    v0 <= 1'b1;
                end else begin
                   d1 <= a_din;
                    v1 <= 1'b1;
                end
            end else if (do_pop && !do_push) begin
                d0 <= d1;
                v0 <= v1;
                v1 <= 1'b0;
            end else if (do_push && do_pop) begin
                // simultaneous push/pop: occupancy and flags unchanged,
                // the new word lands directly in the head slot
               d0 <= a_din;
            end

            count <= count + (do_push ? 2'd1 : 2'd0) - (do_pop ? 2'd1 : 2'd0);
            free  <= free  - (do_push ? 2'd1 : 2'd0) + (do_pop ? 2'd1 : 2'd0);

           // the spill stage preserves arrival order: it only takes a word
           // once the head buffer cannot, and it empties into the head first
          if (land && !refill) begin
               if (!vb0) begin
                  b0  <= sd;
                   vb0 <= 1'b1;
               end else begin
                  b1  <= sd;
                   vb1 <= 1'b1;
               end
          end else if (refill && !land) begin
               b0  <= b1;
               vb0 <= vb1;
               vb1 <= 1'b0;
          end else if (land && refill) begin
              b0 <= sd;
           end
          cntb <= cntb + (land ? 2'd1 : 2'd0) - (refill ? 2'd1 : 2'd0);

          // the landing register holds its word until the array can take it
          if (push_b) begin
              sd <= din;
              sv <= 1'b1;
          end else if (land) begin
              sv <= 1'b0;
          end

          peak_q <= occ_nxt;
         // the channel select tracks the spill stage: it engages when a word
         // spills and releases when the last spilled word is handed up
         if (push_b)
             peak_sel <= 1'b1;
        else if (refill && cntb == 2'd1 && !sv)
             peak_sel <= 1'b0;
         if (!peak_sel) begin
             if (peak_q > hwm)
                 hwm <= peak_q;
         end else begin
             if (peak_q > hwm_b)
                 hwm_b <= peak_q;
         end
        end
    end

   assign dout    = v0 ? d0 : {6'b0, ((hwm_b > hwm) ? hwm_b : hwm)};
    assign o_empty = !v0;
    assign o_full   = (free == 2'd0);
    assign o_count  = count;

    // ---- property: a pop accepted last cycle must have been taken from a
    // ---- buffer whose count register said it was non-empty
    reg pv = 1'b0;
    always @(posedge clk)
        pv <= 1'b1;

    always @(posedge clk)
        if (pv && $past(pop) && $past(v0))
            assert ($past(count) != 2'd0);

    // ---- property: a push accepted last cycle must have gone into a buffer
    // ---- that both occupancy encodings called non-full
    always @(posedge clk)
        if (pv && $past(push) && !$past(v1))
            assert ($past(free) != 2'd0 && $past(count) != 2'd2);

   // ---- property: a cycle in which the upstream credit register reported no
   // ---- free slots must leave the peak occupancy telemetry pegged at two
   always @(posedge clk)
       if (pv && !$past(rst) && $past(free) == 2'd0)
           assert (hwm == 2'd2);
endmodule

