   reg  [3:0] n_rel;       // words popped back out of it

    initial begin
        stall    = 1'b0;
        skid      = 4'h0;
        skid_hi   = 4'h0;
        skid_wide = 1'b0;
        skid_par = 1'b0;
        o_valid  = 1'b0;
        o_data   = 8'h00;
        o_par    = 1'b0;
        win      = 1'b0;
        acc_data = 8'h00;
        acc_par  = 1'b0;
pend_lo     = 4'h0;
pend_hi     = 4'h0;
pend_wide   = 1'b0;
pend_par    = 1'b0;
pend_par_hi = 1'b0;
n_cap = 4'h0;
n_rel = 4'h0;
