   reg [3:0] out_a;
   reg [3:0] out_b;
  // lane A parks its first two credits in a private reserve slot so the
  // common case never touches the lane counter
  reg [1:0] rsv_a;
 // lane B gets the same private reserve slot, so both clients behave alike
 reg [1:0] rsv_b;
   // round-robin pointer: whose request is charged next
   reg       turn;
   // registered arbiter grant: the shelf port moves one credit per cycle
   reg       gnt_a;
   reg       gnt_b;
   reg       gnt_take;
   // shelf-port move pipeline: a granted credit needs four more cycles on the
   // shared port before the lane counters and the shelf see it
   reg       p1_a;
   reg       p1_b;
   reg       p1_take;
   reg       p2_a;
   reg       p2_b;
   reg       p2_take;
   reg       p3_a;
   reg       p3_b;
   reg       p3_take;
   reg       p4_a;
   reg       p4_b;
   reg       p4_take;

    initial used  = 4'd0;
    initial avail = CAP;
   initial out_a = 4'd0;
   initial out_b = 4'd0;
  initial rsv_a = 2'd0;
 initial rsv_b = 2'd0;
   initial turn  = 1'b0;
   initial gnt_a = 1'b0;
   initial gnt_b = 1'b0;
   initial gnt_take = 1'b0;
   initial p1_a = 1'b0;
   initial p1_b = 1'b0;
   initial p1_take = 1'b0;
   initial p2_a = 1'b0;
   initial p2_b = 1'b0;
   initial p2_take = 1'b0;
   initial p3_a = 1'b0;
   initial p3_b = 1'b0;
   initial p3_take = 1'b0;
   initial p4_a = 1'b0;
   initial p4_b = 1'b0;
   initial p4_take = 1'b0;
initial o_ce_beats = 4'd0;

 wire       lane_nz  = turn ? (out_b != 4'd0 || rsv_b != 2'd0)
                            : (out_a != 4'd0 || rsv_a != 2'd0);
   wire       arb_idle = !gnt_a && !gnt_b && !p1_a && !p1_b &&
                         !p2_a && !p2_b && !p3_a && !p3_b && !p4_a && !p4_b;

   // a request is only latched while the shared shelf port is free
   wire accept = i_ce && arb_idle &&
                (i_take ? (used != CAP) : lane_nz);

   // commit of the move that has finished walking the shelf port
   wire take_fire = (p4_a || p4_b) &&  p4_take;
   wire give_fire = (p4_a || p4_b) && !p4_take;

  // lane A fills the reserve before its counter and drains it first
   wire       a_fill  = p4_a &&  p4_take && (rsv_a != 2'd2);
   wire       a_drain = p4_a && !p4_take && (rsv_a != 2'd0);
  wire [1:0] rsv_a_nxt = a_fill  ? rsv_a + 2'd1 :
                         a_drain ? rsv_a - 2'd1 : rsv_a;
   wire [3:0] out_a_nxt = (p4_a &&  p4_take && !a_fill)  ? out_a + 4'd1 :
                          (p4_a && !p4_take && !a_drain) ? out_a - 4'd1 : out_a;
  // lane B fills its reserve before its counter and drains it first
  wire       b_fill  = p4_b &&  p4_take && (rsv_b != 2'd2);
  wire       b_drain = p4_b && !p4_take && (rsv_b != 2'd0);
  wire [1:0] rsv_b_nxt = b_fill  ? rsv_b + 2'd1 :
                         b_drain ? rsv_b - 2'd1 : rsv_b;
  wire [3:0] out_b_nxt = (p4_b &&  p4_take && !b_fill)  ? out_b + 4'd1 :
