module dma_burst_engine (
    input  wire       clk,
    input  wire       i_ce,     // idle condition: low freezes all state
    input  wire       start,    // Q: opens the status window
    input  wire [3:0] len,      // requested burst length (beats)
    input  wire       ack,      // R: host acknowledges, closes the window
    output reg        busy,
    output reg  [3:0] beats
);
    // shadow register: records the length that was requested earlier
    reg [3:0] req_len;
    // beats actually pushed out so far in the current burst
    reg [3:0] done_cnt;
    // window register: set by start, cleared by ack
    reg       armed;
   // beats deferred past the 8-beat hardware burst limit of the current request
   reg [3:0] resid;
// credit-return coalescing: the fabric returns completion credit in groups of
// four, so beats already pushed may sit here before reaching done_cnt
reg [2:0] pend;
// fabric issue stage: a beat handed to the fabric in this cycle has left
// beats but its completion credit only arrives on the following cycle
reg        iq;
// the fabric completion path is four cycles deep: a beat handed over now
// walks three further stages before its credit can be counted
reg        iq2;
reg        iq3;
reg        iq4;
// secondary scrub channel: the fabric asks for a short refresh burst between
// host bursts. It shares the single issue stage and credit counter with the
// host burst channel, so the credit path belongs to one channel at a time.
reg [3:0] scr_beats;
// credit path owner: 0 = host burst channel, 1 = scrub channel
reg       own;

    initial busy     = 1'b0;
    initial beats    = 4'd0;
    initial req_len  = 4'd0;
    initial done_cnt = 4'd0;
    initial armed    = 1'b0;
   initial resid    = 4'd0;
initial pend     = 3'd0;
initial iq       = 1'b0;
initial iq2      = 1'b0;
initial iq3      = 1'b0;
initial iq4      = 1'b0;
initial scr_beats = 4'd0;
initial own       = 1'b0;

// ownership of the credit path only changes hands while no credit is in flight
wire pipe_occ   = iq || iq2 || iq3 || iq4;
wire path_empty = !pipe_occ && (pend == 3'd0);

wire accept = start && !armed && (len != 4'd0) && (!own || path_empty);
   // the fabric accepts at most 8 beats in one burst; the rest is deferred
   wire [3:0] chunk = (len > 4'd8) ? 4'd8 : len;
wire [2:0] pend_nxt  = (pend == 3'd3) ? 3'd0 : pend + 3'd1;
// a start the host channel cannot take (its status window is still open) is
// turned into a scrub burst on the secondary channel
wire scr_load = start && armed && (scr_beats == 4'd0);
wire scr_push = (scr_beats != 4'd0) && (own || path_empty);

    always @(posedge clk) begin
        if (i_ce) begin
            if (accept) begin
               beats    <= chunk;
                req_len  <= len;      // shadow capture of the earlier event
               resid    <= len - chunk;
                done_cnt <= 4'd0;
pend     <= 3'd0;
iq       <= 1'b0;
iq2      <= 1'b0;
iq3      <= 1'b0;
iq4      <= 1'b0;
                busy     <= 1'b1;
                armed    <= 1'b1;
own      <= 1'b0;   // the host burst channel takes the credit path
end else if (busy && !own && beats != 4'd0) begin
               beats    <= (beats == 4'd1 && resid != 4'd0) ? resid : beats - 4'd1;
resid    <= (beats == 4'd1) ? 4'd0 : resid;
// one beat is handed to the fabric now; it must cross all four
// completion stages before its credit lands
iq       <= 1'b1;
iq2      <= iq;
iq3      <= iq2;
iq4      <= iq3;
// the beat issued four cycles ago returns its credit now, and is held
// here until a full group of four is ready
pend     <= iq4 ? pend_nxt : pend;
done_cnt <= (iq4 && pend == 3'd3) ? done_cnt + 4'd4 : done_cnt;
busy     <= 1'b1;
end else if (busy && !own && pipe_occ) begin
// every beat has been issued: walk what is still in flight down the
// completion stages until they and the credit counter are both empty
iq       <= 1'b0;
iq2      <= iq;
iq3      <= iq2;
iq4      <= iq3;
pend     <= iq4 ? pend_nxt : pend;
done_cnt <= (iq4 && pend == 3'd3) ? done_cnt + 4'd4 : done_cnt;
busy     <= (iq || iq2 || iq3) || ((iq4 ? pend_nxt : pend) != 3'd0);
end else if (busy && !own) begin
// trailing partial credit group flushed before the burst reports done
done_cnt <= done_cnt + {1'b0, pend};
pend     <= 3'd0;
busy     <= 1'b0;
end else if (scr_push) begin
// the scrub channel pushes a beat into the shared issue stage
scr_beats <= scr_beats - 4'd1;
iq        <= 1'b1;
iq2       <= iq;
iq3       <= iq2;
iq4       <= iq3;
pend      <= iq4 ? pend_nxt : pend;
own       <= 1'b1;
end else if (own && pipe_occ) begin
// scrub beats cross the same four completion stages
iq        <= 1'b0;
iq2       <= iq;
iq3       <= iq2;
iq4       <= iq3;
pend      <= iq4 ? pend_nxt : pend;
end else if (own) begin
// scrub traffic is never reported to the host: drop its partial credit
// group and hand the credit path back
pend      <= 3'd0;
own       <= 1'b0;
end else if (scr_load) begin
scr_beats <= 4'd4;
            end else if (armed && ack) begin
                armed    <= 1'b0;
            end
        end
    end

    // P, part 1: inside the window, while beats remain the burst cannot yet have
    // delivered everything that was requested earlier.
    always @(posedge clk)
        if (armed && busy)
            assert (done_cnt < req_len);

    // P, part 2: inside the window, once the engine is no longer busy the
    // delivered count must exactly match the earlier requested length.
    always @(posedge clk)
        if (armed && !busy)
            assert (done_cnt == req_len);

   // P, part 3: inside the window, while a deferred chunk is still queued the
   // beats already pushed plus the beats still held back must leave headroom
   // inside the length that was requested earlier.
   always @(posedge clk)
       if (armed && resid != 4'd0)
           assert (({1'b0,done_cnt} + {1'b0,resid}) < {1'b0,req_len});
endmodule

