module deb_evt_fifo (
    input  wire clk,
    input  wire i_ce,      // sample enable: low freezes all state
    input  wire raw,       // raw (noisy) button level
    input  wire pop,       // consumer request
    output wire empty,
    output wire full,
    output reg  o_level    // last popped debounced level
);
    // ---- debouncer: saturating stability counter ----
    reg [1:0] stab;
    reg       deb;

    // ---- event FIFO: pointers + occupancy ----
    reg [1:0] wptr, rptr;
    reg [2:0] count;
    reg [1:0] tail;        // shadow: write pointer snapshot taken at the last push
    reg       mem [0:3];
   reg [1:0] wnext;       // precomputed next write address (shared write-port adder)

   // ---- refresh generator: periodic level-refresh events ----
   // second producer on the shared FIFO write port: every fourth sample it
   // re-posts the current debounced level so a stalled consumer still gets a
   // fresh entry. Edge events own the port; a coincident refresh is held.
   reg [1:0] hb;
   reg       hb_pend;

   // ---- event ledger: free-running push/pop transfer counters ----
// a push is logged when the entry is written, a pop when the consumer's
// request is accepted, so the ledger difference is the number of entries
// not yet spoken for; empty is taken from it and therefore also throttles
// request acceptance. full is taken from the occupancy accumulator: a slot
// whose read is still in flight is not free for rewrite.
   reg [2:0] n_push, n_pop;
   wire [2:0] occ = n_push - n_pop;   // outstanding entries, mod 8

  // ---- read data phase: four-sample memory access latency ----
  // a pop request is acknowledged to the ledger the sample it is accepted,
  // but the entry is only retired -- rptr stepped and o_level updated --
  // when the request walks out of the access pipeline four samples later.
  reg       pop_s0, pop_s1, pop_s2, pop_s3;

  // ---- registered write port: capture stage in front of the array ----
  // the array has a registered write path: a push captures the slot address
  // and the level on one sample and the array cell is written the next. the
  // write pointer advances at capture so a following event addresses the next
  // slot, but the slot only counts as occupancy once the write has landed,
  // and the capture stage holds one transfer, so a push waits while one is in
  // flight. the entry is announced to the consumer at capture: the read data
  // phase is four samples long, so the write has landed before the read runs.
  reg       wr_pend;
  reg [1:0] wr_addr;
  reg       wr_data;

  // ---- array port ledger: free-running write/read access counters ----
  // the arbiter logs every array access: a write when it lands, a read when
  // its data phase runs. the excess of landed writes over performed reads is
  // the number of slots resident in the array, and a resident slot is not
  // available for rewrite, so the write-side backpressure comes from here.
  reg [2:0] n_wr, n_rd;
  wire [2:0] resident = n_wr - n_rd;

   // ---- free-slot counter: write-side backpressure ----
   // the write port books a slot when a transfer is captured and releases
   // it when that entry's read data phase runs, so a slot reserved for a
   // capture still in flight is never offered to a second producer.
   reg [2:0] space;


    // ---- scope register: high until the FIFO has ever been full ----
    reg       never_full;

    // ---- past-valid ----
    reg       pv;

    initial begin
        stab = 2'd0; deb = 1'b0;
        wptr = 2'd0; rptr = 2'd0; count = 3'd0;
        tail = 2'd0;
       wnext = 2'd1;
       hb = 2'd0; hb_pend = 1'b0;
       n_push = 3'd0; n_pop = 3'd0;
      wr_pend = 1'b0; wr_addr = 2'd0; wr_data = 1'b0;
      n_wr = 3'd0; n_rd = 3'd0;
     space = 3'd4;
pop_s0 = 1'b0; pop_s1 = 1'b0; pop_s2 = 1'b0; pop_s3 = 1'b0;
        never_full = 1'b1;
        pv = 1'b0;
        o_level = 1'b0;
        mem[0] = 1'b0; mem[1] = 1'b0; mem[2] = 1'b0; mem[3] = 1'b0;
    end

   assign empty = (occ == 3'd0);
assign full  = (resident == 3'd4) || (space == 3'd0);

    // a debounced edge is committed once raw has disagreed with deb for 3 samples
    wire deb_commit = (raw != deb) && (stab == 2'd2);

   wire hb_req   = (hb == 2'd3) || hb_pend;
   wire push_req = deb_commit || hb_req;
wire do_push  = i_ce && push_req && !full && !wr_pend;  // capture at the write port
wire wr_cmt   = i_ce && wr_pend;                        // captured transfer lands
wire pop_ack = i_ce && pop && !empty;   // request accepted this sample
wire do_pop  = i_ce && pop_s3;          // its data phase, four samples on

    always @(posedge clk) begin
        if (i_ce) begin
            if (raw != deb) begin
                if (stab == 2'd2) stab <= 2'd0;
                else              stab <= stab + 2'd1;
            end else begin
                stab <= 2'd0;
            end
            if (deb_commit) deb <= raw;

           // the captured transfer reaches the array one sample on
           if (wr_cmt) begin
               mem[wr_addr] <= wr_data;
               wr_pend      <= 1'b0;
           end


            if (do_push) begin
              wr_pend   <= 1'b1;
              wr_addr   <= wptr;
              wr_data   <= deb_commit ? raw : deb;
               wptr      <= wnext;
               tail      <= wnext;
               wnext     <= wnext + 2'd1;
            end

           // the refresh prescaler runs off the sample clock; a refresh
           // request retires only once it actually wins the write port
           hb <= hb + 2'd1;
if (hb_req) hb_pend <= deb_commit || full || wr_pend;

           // walk accepted read requests down the access pipeline
           pop_s0 <= pop_ack;
           pop_s1 <= pop_s0;
           pop_s2 <= pop_s1;
           pop_s3 <= pop_s2;

            if (do_pop) begin
                o_level <= mem[rptr];
                rptr    <= rptr + 2'd1;
            end

// log the push at the write and the pop at the accept, so the
// difference excludes reads that are still in flight
