  // arm(line1) -> start(line2) -> finish(line0)
  reg [1:0] stage_c;
  // port C's primed-and-unconsumed flag
  reg       start_tok_c;
 // shared-start-unit ledger: one entry logged per acquire, one per release
 reg [3:0] tok_acq;
 reg [3:0] tok_rel;
