wire       tail_pop  = skid2_valid && out_room;

    assign o_valid    = out_valid;
    assign o_code     = out_code;
    assign o_in_ready = in_ready;
assign o_fire_count = {n_in, n_out};

    always @(posedge clk) begin
        if (rst) begin
            src_phase  <= 2'd0;
            phase      <= 2'd0;
            out_valid  <= 1'b0;
            out_code   <= ARM;
            skid_valid <= 1'b0;
            skid_code  <= ARM;
           skid2_valid <= 1'b0;
           skid2_code  <= ARM;
           gap        <= 1'b0;
n_in       <= 2'd0;
n_out      <= 2'd0;
tail_cnt   <= 2'd0;
        end else if (step) begin
            // output register: drain skid first, else take the fresh word
            if (out_room) begin
                if (skid_valid) begin
                    out_valid <= 1'b1;
                    out_code  <= skid_code;
               end else if (in_valid && in_ready) begin
                    out_valid <= 1'b1;
                    out_code  <= in_code;
                end else begin
                    out_valid <= 1'b0;
                end
            end

            // skid buffer: only loaded while the stage is stalled
            if (skid_valid) begin
               if (out_room) begin
                   // head drains into the output register; refill it from
                   // the tail slot, or straight from the producer
                   if (skid2_valid) begin
                       skid_valid <= 1'b1;
                       skid_code  <= skid2_code;
                   end else if (in_valid && in_ready) begin
                       skid_valid <= 1'b1;
                       skid_code  <= in_code;
                   end else begin
                       skid_valid <= 1'b0;
                   end
               end
           end else if (in_valid && in_ready && !out_room) begin
                skid_valid <= 1'b1;
                skid_code  <= in_code;
            end

           // tail slot: only fills behind a full head slot while the
           // output register is blocked, and always shifts down on a drain
           if (skid2_valid) begin
               if (out_room)
                   skid2_valid <= 1'b0;
           end else if (in_valid && in_ready && skid_valid && !out_room) begin
               skid2_valid <= 1'b1;
               skid2_code  <= in_code;
