module uart_rx_onehot (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,      // baud tick / enable: low freezes all state
    input  wire       rx,
    input  wire       take,    // consumer accepts the byte parked in STOP
    output wire [7:0] o_data,
    output wire       o_ferr,
    output wire       o_busy
);
    // one-hot phase FSM:
    //   st[0]      IDLE
    //   st[1]      START bit
    //   st[2..9]   data bits D0..D7 (one state per bit)
    //   st[10]     STOP bit / byte parked
    reg [10:0] st;
    reg [3:0]  nbits;   // frame phase index: 0..10 only, though 4 bits hold 15
   reg [3:0]  dcnt;    // data bits already shifted into sr this frame: 0..8
    reg [7:0]  sr;
    reg        ferr;
    reg        pv;
   reg [3:0]  n_acq;   // ledger: frames acquired off the line (start bit seen)
   reg [3:0]  n_rel;   // ledger: frames released to the consumer (take at STOP)
   reg        active;  // a frame is in flight according to the ledger
  reg        owner;   // baud-tick arbiter: 1 = the idle timer owns this tick
  reg [3:0]  icnt;    // idle ticks seen by the line-idle timer: 0..11
 reg        rel_q;   // handoff staged one tick: take now acks on the next tick
 reg [7:0]  obuf;    // output holding register for the byte being handed off
reg        park;   // hand-off stage: owns the frame from the last data bit until the ack

    initial st    = 11'b000_0000_0001;
    initial nbits = 4'd0;
   initial dcnt  = 4'd0;
    initial sr    = 8'h00;
    initial ferr  = 1'b0;
    initial pv    = 1'b0;
   initial n_acq  = 4'd0;
   initial n_rel  = 4'd0;
   initial active = 1'b0;
  initial owner = 1'b0;
  initial icnt  = 4'd0;
 initial rel_q = 1'b0;
 initial obuf  = 8'h00;
initial park = 1'b0;

    wire idle   = st[0];
    wire startb = st[1];
    wire datab  = |st[9:2];
    wire stopb  = st[10];

    wire start_det = ce && idle   && !rx;   // falling edge of the line
   wire adv       = ce && active && !owner && (startb || datab); // count only the ticks this engine owns
wire done      = ce && stopb  && park && take;  // release only when the park stage holds the frame
wire in_flight = start_det || ((active || park) && !done); // receive engine or park stage claims the next tick
   wire quiet     = owner && (icnt == 4'd11);       // line idle for a whole frame time

    // next-state decode: every source bit drives exactly one destination bit
    reg [10:0] nxt;
    always @(*) begin
        nxt      = 11'd0;
        nxt[0]   = (st[0] && rx) || (st[10] && take);
        nxt[1]   = st[0] && !rx;
        nxt[2]   = st[1];
        nxt[3]   = st[2];
        nxt[4]   = st[3];
        nxt[5]   = st[4];
        nxt[6]   = st[5];
        nxt[7]   = st[6];
        nxt[8]   = st[7];
        nxt[9]   = st[8];
        nxt[10]  = st[9] || (st[10] && !take);
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            st    <= 11'b000_0000_0001;
            nbits <= 4'd0;
           dcnt  <= 4'd0;
            sr    <= 8'h00;
            ferr  <= 1'b0;
           n_acq  <= 4'd0;
           n_rel  <= 4'd0;
           active <= 1'b0;
           owner <= 1'b0;
           icnt  <= 4'd0;
          rel_q <= 1'b0;
          obuf  <= 8'h00;
park  <= 1'b0;
        end else if (ce) begin
            st <= nxt;
            if (start_det)     nbits <= 4'd1;   // load: start bit is phase 1
            else if (done)     nbits <= 4'd0;
            else if (adv)      nbits <= nbits + 4'd1;
            if (datab)         sr    <= {rx, sr[7:1]};
           if (start_det || done) dcnt <= 4'd0;
           else if (datab)        dcnt <= dcnt + 4'd1;
           if (done)          ferr  <= !rx || (dcnt != 4'd8); // stop bit high and a full byte
          else if (quiet)    ferr  <= 1'b0;                  // stale error retired once the line goes quiet
           // frame ledger: one acquire per start bit, one release per handoff
           if (start_det)     n_acq  <= n_acq + 4'd1;
if (rel_q)         n_rel  <= n_rel + 4'd1;
           if (start_det)     active <= 1'b1;
else if (st[9])    active <= 1'b0;   // last data bit: ownership passes to the park stage
if (st[9])         park   <= 1'b1;   // park stage takes the frame for the stop bit
else if (rel_q)    park   <= 1'b0;   // ... and lets go once the release has committed
// staged handoff: the byte is parked in obuf on take and the ledger
// release commits on the following tick, when the bus has been read
rel_q <= stopb && take;
if (done)          obuf  <= sr;
          // tick arbiter: every tick the frame engine will not use goes to the idle timer
          owner <= !in_flight;
          if (!owner)             icnt <= 4'd0;
          else if (icnt != 4'd11) icnt <= icnt + 4'd1;
        end
    end

   // with no byte parked, the data bus reads back the ledger for diagnostics
assign o_data = stopb ? sr : (park ? obuf : {n_acq, n_rel});
    assign o_ferr = ferr;
assign o_busy = !idle || active || park;

    // P: the phase counter changes on every phase change, and it never counts
    // past the 10 phases of a frame -- stated as a no-change check.
    always @(posedge clk)
        if (pv && $stable(nbits))
            assert ($stable(st) && nbits <= 4'd10);

   // P2: dcnt lags the phase index by the START phase plus the one-cycle
   // capture lag, so inside a frame it is always nbits-2 bits deep.
   always @(posedge clk)
       if (pv && o_busy && nbits >= 4'd2)
           assert (dcnt == nbits - 4'd2);
endmodule

