    reg [3:0] beats_left;   // beats remaining in the burst
    reg [3:0] done_cnt;     // beats already pushed out
    reg [3:0] total;        // beats requested by the accepted burst
    reg [3:0] duty;         // dimming level latched with the burst
    reg       busy;         // up exactly while beats remain
    reg [3:0] queued;       // beats accepted but not yet issued into the current chunk
   reg [3:0] chunk_pend;   // chunk staged for issue on the next beat
   // ---- fabric ledger: beats booked out to the fabric vs beats it consumed ----
   reg [3:0] n_iss;        // running count of beats issued to the fabric
   reg [3:0] n_ret;        // running count of beats the fabric has consumed
  reg       ret_pend;     // one retirement in flight to the completion counter

    initial beats_left = 4'd0;
    initial done_cnt   = 4'd0;
    initial total      = 4'd0;
    initial duty       = 4'd0;
    initial busy       = 1'b0;
    initial queued     = 4'd0;
   initial chunk_pend = 4'd0;
   initial n_iss      = 4'd0;
   initial n_ret      = 4'd0;
  initial ret_pend   = 1'b0;
initial o_ce_count = 4'd0;

    // the fabric only accepts short chunks, so a long burst is issued piecewise
    localparam [3:0] CHUNK_MAX = 4'd4;
    wire [3:0] first_chunk = (i_beats > CHUNK_MAX) ? CHUNK_MAX : i_beats;
    wire [3:0] next_chunk  = (queued  > CHUNK_MAX) ? CHUNK_MAX : queued;
   // a beat is live on the bus exactly while the ledger shows work booked out
   wire outstanding = (n_iss != n_ret);

    always @(posedge i_clk) begin
        if (i_rst) begin
            beats_left <= 4'd0;
            done_cnt   <= 4'd0;
            total      <= 4'd0;
            duty       <= 4'd0;
            queued     <= 4'd0;
           chunk_pend <= 4'd0;
           n_iss      <= 4'd0;
           n_ret      <= 4'd0;
          ret_pend   <= 1'b0;
o_ce_count <= 4'd0;
            busy       <= 1'b0;
