                    if (cls == 2'd3) begin
                       st_s  <= S_IDLE;   // closing quote ends the token
                      len_s <= own ? len_inc : 3'd0;
                    end else if (cls == 2'd0) begin
                       st_s  <= S_ESC;    // backslash: next char is literal
