reg [3:0] gnt_amt2;
reg [1:0] gnt_resv2;
reg       gnt_q3;
reg [3:0] gnt_amt3;
reg [1:0] gnt_resv3;
reg       gnt_q4;
reg [3:0] gnt_amt4;
reg [1:0] gnt_resv4;
reg       gnt_q5;
reg [3:0] gnt_amt5;
reg [1:0] gnt_resv5;

