gnt_q2      <= 1'b0;
gnt_amt2    <= 4'd0;
gnt_resv2   <= 2'd0;
gnt_q3      <= 1'b0;
gnt_amt3    <= 4'd0;
gnt_resv3   <= 2'd0;
gnt_q4      <= 1'b0;
gnt_amt4    <= 4'd0;
