gnt_q2    <= gnt_q;
gnt_amt2  <= gnt_amt;
gnt_resv2 <= gnt_resv;
gnt_q3    <= gnt_q2;
gnt_amt3  <= gnt_amt2;
gnt_resv3 <= gnt_resv2;
gnt_q4    <= gnt_q3;
gnt_amt4  <= gnt_amt3;
gnt_resv4 <= gnt_resv3;
gnt_q5    <= gnt_q4;
gnt_amt5  <= gnt_amt4;
gnt_resv5 <= gnt_resv4;
gnt_q     <= 1'b0;
         if (do_grant) begin
             gnt_q    <= 1'b1;
             gnt_amt  <= need;
             gnt_resv <= burst_start ? resv : escrow;
         end

         if (gnt_commit) begin
credits     <= credits - gnt_amt5;
escrow      <= gnt_resv5;
             outstanding <= outstanding + 4'd1;
           end else if (ret_done) begin
               credits <= credits + ret_amt;
