module credit_deadline (
    input  wire clk,
    input  wire i_ce,      // global enable: low => all state frozen
    input  wire rst,
    input  wire req,       // producer wants to spend a credit
    output wire grant,
output wire busy,
output reg [3:0] req_hist
);
    localparam [2:0] TOTAL = 3'd4;   // configured credit pool

    // credits held by the producer, credits outstanding at the consumer
    reg [2:0] credits;
    reg [2:0] outst;
   // registered handoff: a spent credit occupies the launch slot for one
   // enabled cycle before the consumer counts it as outstanding
   reg       snd;
    // consumer needs two enabled cycles to retire one outstanding credit
    reg       svc;
    // bounded-response deadline countdown for the outstanding credits
    reg [3:0] timer;
   // deferred deadline budget for the credits queued behind the head
   reg [3:0] bank;
   // governor watermark: deepest outstanding occupancy seen so far
   reg [2:0] peak;
reg last_req;

    initial begin
        credits = 3'd4;
        outst   = 3'd0;
       snd     = 1'b0;
        svc     = 1'b0;
        timer   = 4'd0;
       bank    = 4'd0;
       peak    = 3'd0;
req_hist = 4'd0;
last_req = 1'b0;
    end

   // once occupancy has ever peaked at the whole pool, hold off new
   // spends until the consumer has drained completely
  wire throttle  = (peak == TOTAL) && ((outst != 3'd0) || snd);
  // admission control: a new spend must be able to park its two cycle
  // budget behind the head credit, so the bank has to have room
  wire bank_room = (bank <= 4'd4);
 wire do_spend  = req && (credits != 3'd0) && !throttle && bank_room && !snd;
 // the launch slot drains into the outstanding set on the next enabled cycle
 wire do_launch = snd;
    wire do_return = (outst != 3'd0) && (svc == 1'b1);
  wire [2:0] outst_nxt = outst + (do_launch ? 3'd1 : 3'd0)
                                - (do_return ? 3'd1 : 3'd0);

  // a retiring head hands the deadline of the next credit out of the bank
 wire [3:0] bank_in   = bank + ((do_launch && (outst != 3'd0)) ? 4'd2 : 4'd0);
  wire [3:0] bank_take = (bank_in >= 4'd2) ? 4'd2 : bank_in;
  wire       reload    = do_return && (outst_nxt != 3'd0);

    assign grant = i_ce && do_spend;
   assign busy  = (outst != 3'd0) || snd;

    always @(posedge clk) begin
        if (i_ce) begin
            if (rst) begin
                credits <= TOTAL;
                outst   <= 3'd0;
               snd     <= 1'b0;
                svc     <= 1'b0;
                timer   <= 4'd0;
               bank    <= 4'd0;
               peak    <= 3'd0;
req_hist <= 4'd0;
last_req <= 1'b0;
            end else begin
                // credit conservation: one token moves per event
                credits <= credits - (do_spend  ? 3'd1 : 3'd0)
                                   + (do_return ? 3'd1 : 3'd0);
               outst   <= outst   + (do_launch ? 3'd1 : 3'd0)
                                   - (do_return ? 3'd1 : 3'd0);

               // the launch slot is one deep, so a new spend is only
               // accepted once the previous one has entered the pool
               snd     <= do_spend;

                // two-cycle service phase per outstanding credit
                if (outst == 3'd0)
                    svc <= 1'b0;
                else
                    svc <= ~svc;

               // watermark only ever rises
               if (outst_nxt > peak)
                   peak <= outst_nxt;

               // deadline budget: the head credit owns a two cycle deadline;
               // the budget of the credits queued behind it waits in the bank
               if (reload)
                   timer <= bank_take;
               else if (do_return)
                   timer <= 4'd0;
              else if (do_launch && (outst == 3'd0))
                   timer <= 4'd2;
               else
                   timer <= timer - ((timer != 4'd0) ? 4'd1 : 4'd0);

               bank <= bank_in - (reload ? bank_take : 4'd0);

// observability only: rolling history of the req input
last_req <= req;
req_hist <= {req_hist[2:0], last_req};
            end
        end
    end

    // Bounded response (safety): the countdown must never expire while a
    // credit is still outstanding at the consumer.
    always @(posedge clk)
        if (outst != 3'd0)
            assert (timer != 4'd0);

   // Quiescence (safety): once the whole pool is back at the producer
   // there is nothing left at the consumer, so the service phase must be
   // idle and the deadline budget must be fully spent.
   always @(posedge clk)
       if (credits == TOTAL)
           assert ((timer == 4'd0) && (svc == 1'b0));

   // Governor coherence (safety): the in-flight deadline budget never
   // exceeds two cycles per credit at the recorded peak occupancy.
   always @(posedge clk)
       assert (timer <= {peak, 1'b0});

endmodule

