    reg       latched;

   // Margin monitor: low-water mark of the grace window since the
   // watchdog was last armed.  Zero means the window has fully closed.
   reg [3:0] slack;

  // Adaptive grace window: how many ticks of grace each re-arm hands out.
  // o_elapsed/o_remain are always reported against the full 12-tick frame,
  // so a shortened window simply starts the elapsed count with a head
  // start instead of at zero.
