module fetch_credit_tracker (
    input  wire       clk,
    input  wire       rst,
    input  wire       en,        // idle condition: when low, nothing moves
    input  wire       fetch,     // issue an instruction into the fetch queue
    input  wire       retire,    // instruction leaves the queue
    output reg  [3:0] used,      // up counter: occupancy of the fetch queue
    output reg  [3:0] credits,   // down counter: remaining free slots
output wire       can_fetch,
output reg  [3:0] fetch_events
);
    // queue depth is 12, but both counters are 4 bits wide (0..15)
    localparam [3:0] DEPTH = 4'd12;

    // a retire frees a queue slot right away, but the credit itself only
    // reaches the free pool a cycle later, through this return stage
    reg        ret_credit;

   // an accepted fetch is registered in the allocate stage; it shows up
   // in the occupancy counter on the following cycle
   reg        alloc_pend;

   // credits withheld from the fetch free pool and parked for the
   // prefetch port while the queue is running hot
   reg  [1:0] resv;

   // purely observational statistics: saturating count of granted fetches
   reg        activity_seen;


    initial used    = 4'd0;
    initial credits = DEPTH;
    initial ret_credit = 1'b0;
   initial alloc_pend = 1'b0;
   initial resv = 2'd0;
   initial fetch_events = 4'd0;
   initial activity_seen = 1'b0;

    assign can_fetch = (credits != 4'd0);

    wire fetch_go  = fetch && !retire && (credits != 4'd0);
    wire retire_go = retire && !fetch && (used != 4'd0);

   // the queue is under pressure once occupancy reaches the top third
   wire hi_load     = (used >= 4'd8);
   // under pressure a returning credit is parked in the reserve instead
   wire ret_to_resv = ret_credit && hi_load && (resv != 2'd2);
   // once the pressure is off, reserved credits go back one per cycle
   wire resv_drain  = !ret_credit && !fetch_go && !hi_load && (resv != 2'd0);
   wire cred_inc    = (ret_credit && !ret_to_resv) || resv_drain;
   wire cred_dec    = fetch_go;

    always @(posedge clk) begin
        if (rst) begin
            used    <= 4'd0;
            credits <= DEPTH;
            ret_credit <= 1'b0;
           alloc_pend <= 1'b0;
           resv <= 2'd0;
           fetch_events <= 4'd0;
           activity_seen <= 1'b0;
        end else if (en) begin
           // occupancy reflects the allocate stage, one cycle behind the grant
           if (alloc_pend && !retire_go)
                used <= used + 4'd1;
           else if (!alloc_pend && retire_go)
                used <= used - 4'd1;

            // the free pool gives up a slot on fetch, and only gets one
            // back when a returning credit pops out of the return stage
           if (cred_dec && !cred_inc)
               credits <= credits - 4'd1;
           else if (cred_inc && !cred_dec)
               credits <= credits + 4'd1;

           // the reserve fills from parked returns and drains back later
           if (ret_to_resv)
               resv <= resv + 2'd1;
           else if (resv_drain)
               resv <= resv - 2'd1;

            // a retire hands its credit to the return stage
            ret_credit <= retire_go;
           // the grant hands its slot to the allocate stage
           alloc_pend <= fetch_go;
