                   if (ov_pend && state == S_IDLE) begin
                       ov_state <= OV_CLR;
                       ov_pend  <= 1'b0;
                   end
               end
               OV_CLR: begin
                   ov_state <= OV_FILL;
                   draw_cnt <= 2'd0;
