          // port.  It repaints the sprite once the overlay refresh has
          // retired, and reuses the shared pass counter for its fill loop.
          case (cur_state)
              CU_IDLE: begin
                  if (cur_pend && state == S_IDLE &&
                      ov_state == OV_IDLE && !ov_pend) begin
                      cur_state <= CU_FETCH;
                      cur_pend  <= 1'b0;
                  end
              end
              CU_FETCH: begin
                  cur_state <= CU_PAINT;
                  draw_cnt  <= 2'd0;
              end
              CU_PAINT: begin
                  if (draw_cnt == 2'd2)
                      cur_state <= CU_DONE;
                  else
                      draw_cnt <= draw_cnt + 2'd1;
              end
              CU_DONE: begin
                  cur_state <= CU_IDLE;
                  draw_cnt  <= 2'd0;
              end
