   // logged in n_acq, every retire in n_rel; both wrap at four bits. The
   // channel may only be taken when all logged acquires have been retired.
   reg [3:0] n_acq;
   reg [3:0] n_rel;

  // Retires post lazily: the completion cycle is already writing seven
  // registers, so it only raises rel_pend and the n_rel increment is folded
  // into the next acquire. The ledger counts a pending retire as already
  // retired, so a client can take the channel back to back without waiting
  // for the credit to be written down.
