module elevator_call_gen (
    input  wire       clk,
    input  wire       rst,
    input  wire       step,
    output reg  [1:0] floor,
    output reg        dir,
    output reg  [3:0] pending,
    output reg  [2:0] dry_cnt,
    output reg  [3:0] lf
);
// Pseudo-random hall-call source.  The shift chain and its feedback XOR
// are split across two flops: the tap is evaluated one cycle ahead into
// lf_fb and shifted in on the next enabled step, which keeps the XOR
// gate out of the shift path.  Taps are chosen so that the combined
// 5-bit generator state {lf, lf_fb} is maximal length (period 31).
reg lf_fb;
// Quiet watchdog: reloaded on every hall call and decremented on every
// silent enabled step.  It is the budget of steps the generator may stay
// quiet before the cab is handed a target of its own.
reg [2:0] quiet_wd;
// Reload accounting is split across two flops: on a hall call the counter
// is handed two ticks at once and the third rides in wd_carry, which is
// folded back into the counter on the following quiet step.  That keeps
// the counter's load path a constant, and the budget still outstanding is
// quiet_wd + wd_carry.
reg [1:0] wd_carry;
// Hall calls reach the cab through a one-deep request stage: the
// generator's decision and its floor are captured here and acted on
// the following enabled step, keeping the call decode off the
// pending-mask and watchdog paths.
reg       call_v;
reg [1:0] call_fl;

initial lf_fb   = 1'b0;
    initial lf      = 4'b0001;
    initial floor   = 2'd0;
    initial dir     = 1'b1;   // 1 = up, 0 = down
    initial pending = 4'b0000;
    initial dry_cnt = 3'd0;
    initial quiet_wd = 3'd3;
    initial call_v  = 1'b0;
    initial call_fl = 2'd0;
    initial wd_carry = 2'd0;

wire       lf_fb_next = lf[3] ^ lf[1];
wire [3:0] lf_next    = {lf[2:0], lf_fb};

// A pseudo-random hall call is issued unless the top three shift
// stages of the generator are all zero.
    wire       new_call   = (lf[3:1] != 3'b000);
    wire [1:0] call_floor = lf[1:0];

    wire at_top = (floor == 2'd3);
    wire at_bot = (floor == 2'd0);

    wire [1:0] floor_next = dir ? (at_top ? floor : floor + 2'd1)
                                : (at_bot ? floor : floor - 2'd1);
    wire       dir_next   = dir ? (at_top ? 1'b0 : 1'b1)
                                : (at_bot ? 1'b1 : 1'b0);

    // On the watchdog's last tick a call at the top floor is synthesized,
    // so a quiet generator cannot leave the cab without work.
wire [2:0] wd_left    = quiet_wd + {1'b0, wd_carry};
wire       wd_last    = (wd_left <= 3'd1);
    wire [3:0] set_mask   = call_v ? (4'b0001 << call_fl)
                                   : (wd_last ? 4'b1000 : 4'b0000);
    wire [3:0] clr_mask   = (4'b0001 << floor);

    always @(posedge clk) begin
        if (rst) begin
            lf      <= 4'b0001;
lf_fb   <= 1'b0;
            floor   <= 2'd0;
            dir     <= 1'b1;
            pending <= 4'b0000;
            dry_cnt <= 3'd0;
            quiet_wd <= 3'd3;
            call_v  <= 1'b0;
            call_fl <= 2'd0;
            wd_carry <= 2'd0;
        end else if (step) begin
            lf      <= lf_next;
lf_fb   <= lf_fb_next;
            call_v  <= new_call;
            call_fl <= call_floor;
            floor   <= floor_next;
            dir     <= dir_next;
            pending <= (pending | set_mask) & ~clr_mask;
            // consecutive enabled steps during which no new call appeared
            dry_cnt <= call_v ? 3'd0 : (dry_cnt + 3'd1);
            quiet_wd <= call_v ? 3'd2
                               : (quiet_wd == 3'd0 ? 3'd0 : quiet_wd - 3'd1)
                                 + (wd_carry != 2'd0 ? 3'd1 : 3'd0);
            // the deferred tick of the reload, merged one step later
            wd_carry <= call_v ? 2'd1
                               : (wd_carry == 2'd0 ? 2'd0 : wd_carry - 2'd1);
        end
    end

    // Bounded existence: the call-starvation streak never exceeds 3,
    // although the counter is 3 bits wide.
    assert property (dry_cnt <= 3'd3);

    // The watchdog always has budget left over: calls arrive in time.
    always @(posedge clk)
        assert (quiet_wd >= 3'd1);
endmodule

