  // condition from the step index and the configured ramp length instead of
  // reusing the voter's flag or its code compare.
  wire       prev_wrap = (pos == ring_len);
  // Ramp length carried by a wrap-point load word.
  wire [2:0] len_in    = code_in - base_code;

    always @(posedge clk) begin
        if (ce) begin
            if (load) begin
               if (!cfg_sel) begin
                shadow_a   <= code_in;
                shadow_b   <= code_in;
                shadow_c   <= code_in;
prev_lo   <= code_in[1:0] - 2'd1;
prev_hi_t <= code_in[2] ^ (code_in[1:0] == 2'd0);
prev_hi_f <= ~(code_in[2] ^ (code_in[1:0] == 2'd0));
               base_code  <= code_in;
               seed_code  <= code_in - 3'd1;
               top_code   <= code_in - 3'd1;
               at_top     <= 1'b0;
              // a fresh origin opens the ring out to its full length
              ring_len   <= 3'd7;
              pos        <= 3'd0;
               end else begin
                   // a second load moves the wrap point of the ramp
                   top_code <= code_in;
                  ring_len <= len_in;
                  at_top   <= (pos == len_in);
               end
               cfg_sel <= ~cfg_sel;
            end else begin
               if (at_top) begin
                   shadow_a   <= base_code;
                   shadow_b   <= base_code;
                   shadow_c   <= base_code;
               end else begin
                   shadow_a   <= shadow_a + 3'd1;
                   shadow_b   <= shadow_b + 3'd1;
                   shadow_c   <= shadow_c + 3'd1;
               end
               at_top <= (next_code == top_code);
             // the precedence index rolls with the code it records
             pos <= prev_wrap ? 3'd0 : pos + 3'd1;
              if (prev_wrap) begin
                  // reseed the precedence shadow to the origin's predecessor
                  prev_lo   <= seed_code[1:0];
                  prev_hi_t <= seed_code[2];
                  prev_hi_f <= ~seed_code[2];
              end else begin
                  prev_lo <= voted[1:0];
                  // the top bit only moves when the low part rolls over
                  if (prev_lo == 2'd3) begin
                      prev_hi_t <= prev_hi_f;
                      prev_hi_f <= prev_hi_t;
