// Priority arbiter for per-subchannel energy detect flags.
// Stage 0: combinational priority encode of the request vector.
// Stage 1: registered half-occupancy flags + priority-half decision.
// Stage 1b: the decision is retimed through a second register so the grant
//          flags and the accounting write leave stage 1 on the same path.
// Stage 2: registered valid, registered index (only meaningful while valid),
//          and the two half-band grant flags.
module wifi_pri_grant (
    input  wire       clk,
    input  wire       i_ce,
    input  wire [7:0] i_req,
    output reg        o_vld,
    output reg  [2:0] o_idx,
    output reg        o_grant_lo,
    output reg        o_grant_hi
);
    // ---------------- stage 0: combinational priority encoder ------------
    wire req_lo = |i_req[3:0];
    wire req_hi = |i_req[7:4];

    reg [2:0] enc;
    always @(*) begin
        casez (i_req)
            8'b???????1: enc = 3'd0;
            8'b??????10: enc = 3'd1;
            8'b?????100: enc = 3'd2;
            8'b????1000: enc = 3'd3;
            8'b???10000: enc = 3'd4;
            8'b??100000: enc = 3'd5;
            8'b?1000000: enc = 3'd6;
            8'b10000000: enc = 3'd7;
            default:     enc = 3'd0;
        endcase
    end

    // ---------------- stage 1 registers ---------------------------------
    reg       s1_vld;
    reg       s1_req_lo;
    reg       s1_req_hi;
    reg       s1_pri_hi;   // upper half wins only when lower half is empty
    reg [2:0] s1_idx;

  // ---------------- stage 1b: retimed decision -------------------------
  // The output pins and the retention-domain counters sit far apart, so the
  // stage-1 decision is carried one more register before it is used.
  reg       s1b_vld;
  reg       s1b_req_lo;
  reg       s1b_req_hi;
  reg       s1b_pri_hi;
  reg [2:0] s1b_idx;

   // ---------------- accounting park slot -------------------------------
   // cnt_hi lives in the slow retention domain and needs a cycle of its own
   // to absorb a write, so an upper-band grant is parked for one cycle
   // together with the energy flag of the cycle it came from.  Stage 1 stops
   // issuing while the slot is in use, so only one upper-band event is ever
   // in flight.
   reg       park_hi;
   reg       park_act;
  wire      acct_busy = (s1_vld && s1_pri_hi) || (s1b_vld && s1b_pri_hi) ||
                        park_hi;

   // ---------------- stage 2 grant accounting --------------------------
   // Per-band grant counters plus a counter of cycles in which any band
   // reported energy.  Firmware samples their low bits on the index bus
   // while the pipe is idle (o_idx carries no index when o_vld is low).
   reg [3:0] cnt_lo;
   reg [3:0] cnt_hi;
   reg [3:0] cnt_tot;

    initial begin
        s1_vld    = 1'b0;
        s1_req_lo = 1'b0;
        s1_req_hi = 1'b0;
        s1_pri_hi = 1'b0;
        s1_idx    = 3'd0;
      s1b_vld    = 1'b0;
      s1b_req_lo = 1'b0;
      s1b_req_hi = 1'b0;
      s1b_pri_hi = 1'b0;
      s1b_idx    = 3'd0;
       park_hi   = 1'b0;
       park_act  = 1'b0;
       cnt_lo     = 4'd0;
       cnt_hi     = 4'd0;
       cnt_tot    = 4'd0;
        o_vld      = 1'b0;
        o_idx      = 3'd0;
        o_grant_lo = 1'b0;
        o_grant_hi = 1'b0;
    end

    always @(posedge clk) begin
        if (i_ce) begin
            // stage 1 capture
s1_vld    <= (req_lo | req_hi) && !acct_busy;
            s1_req_lo <= req_lo;
            s1_req_hi <= req_hi;
            s1_pri_hi <= req_hi && !req_lo;
            s1_idx    <= enc;

           // stage 1b capture
           s1b_vld    <= s1_vld;
           s1b_req_lo <= s1_req_lo;
           s1b_req_hi <= s1_req_hi;
           s1b_pri_hi <= s1_pri_hi;
           s1b_idx    <= s1_idx;

            // stage 2 capture
           o_vld      <= s1b_vld;
           // idle index bus carries a compact counter status code
          o_idx      <= s1b_vld ? s1b_idx
                                : {cnt_tot[0], cnt_hi[0], cnt_lo[0]};
           o_grant_lo <= s1b_vld && s1b_req_lo;
           o_grant_hi <= s1b_vld && s1b_pri_hi;

          // grant accounting, driven off the retimed stage-1b decision
          park_hi  <= s1b_vld && s1b_pri_hi;
          park_act <= (s1b_vld && s1b_pri_hi) && (s1b_req_lo || s1b_req_hi);
          if (s1b_vld && s1b_req_lo)
               cnt_lo  <= cnt_lo  + 4'd1;
if (park_hi)
               cnt_hi  <= cnt_hi  + 4'd1;
if ((s1b_vld && !s1b_pri_hi && (s1b_req_lo || s1b_req_hi)) || park_act)
               cnt_tot <= cnt_tot + 4'd1;
        end
    end

    // P: while the encoded index is valid, the two half-band grants are
    //    never asserted together.
    always @(posedge clk)
        if (o_vld)
            assert (!(o_grant_lo && o_grant_hi));

   // Q: the per-band grant counters account for exactly the counted
   //    request cycles.
   always @(posedge clk)
       assert (cnt_tot == cnt_lo + cnt_hi);

endmodule


