module csa_accum_parity (
    input  wire       clk,
    input  wire       i_rst,
    input  wire       i_ce,
    input  wire       i_clear,
    input  wire [7:0] i_data,
    output wire [7:0] o_total,
output wire [7:0] o_ref,
output wire [3:0] o_evt_cnt
);
    // accumulator kept in carry-save form: two halves that always sum to the
    // true running total held in the reference register
    reg [7:0] acc_s = 8'h00;   // sum half
    reg [7:0] acc_c = 8'h00;   // carry half (always even by construction)
reg [3:0] total  = 4'h0;   // reference accumulator, low nibble slice
reg [3:0] tot_hi = 4'h0;   // reference accumulator, high nibble slice
    reg        hi_flag = 1'b0; // registered "total has reached the upper half";
                               // precomputed on the adder result so the flush
                               // path next cycle is just a flop-to-mux hop
reg [3:0] evt_cnt = 4'h0;  // distractor: counts enabled cycles with nonzero input
reg [1:0] fill = 2'b00;    // coarse fill level of the open window: bits 6:5 of
                           // the running total, published in the status nibble
                           // so the consumer can pace its reads

    wire [7:0] sum_bits   = acc_s ^ acc_c ^ i_data;
    wire [7:0] maj_bits   = (acc_s & acc_c) | (acc_s & i_data) | (acc_c & i_data);
    wire [7:0] carry_bits = {maj_bits[6:0], 1'b0};
// reference adder is built from two nibble slices so neither carry chain
// spans the whole word; the upper slice is only clocked on cycles where it
// can actually change, which keeps it quiet for small operands
wire [4:0] lo_sum     = {1'b0, total} + {1'b0, i_data[3:0]};
wire       lo_cout    = lo_sum[4];
wire [3:0] hi_sum     = tot_hi + i_data[7:4] + {3'b0, lo_cout};
wire       hi_en      = lo_cout || (i_data[7:4] != 4'h0);
wire [7:0] next_total = {hi_sum, lo_sum[3:0]};

    always @(posedge clk) begin
        if (i_rst) begin
            acc_s <= 8'h00;
            acc_c <= 8'h00;
total  <= 4'h0;
tot_hi <= 4'h0;
            hi_flag <= 1'b0;
evt_cnt <= 4'h0;
fill <= 2'b00;
        end else if (i_ce) begin
evt_cnt <= evt_cnt + {3'b0, (i_data != 8'h00)};
            if (i_clear || hi_flag) begin
                acc_s <= 8'h00;
                acc_c <= 8'h00;
total  <= 4'h0;
tot_hi <= 4'h0;
                hi_flag <= 1'b0;
fill <= 2'b00;
            end else begin
                acc_s <= sum_bits;
                acc_c <= carry_bits;
total   <= next_total[3:0];
if (hi_en)
    tot_hi <= next_total[7:4];
                hi_flag <= next_total[7];
fill <= next_total[6:5];
            end
        end
    end

    assign o_total = acc_s + acc_c;
assign o_ref   = {tot_hi, total};
// status nibble: coarse fill level in the top two bits, low two bits of the
// event count packed underneath it
assign o_evt_cnt = {fill, evt_cnt[1:0]};

    // P: while the unit is actually accumulating, the low bit of the sum half
    // alone already carries the parity of the true total.
    always @(posedge clk)
        if (i_ce && !i_clear)
            assert (acc_s[0] == total[0]);

    // P2: the flush flag was computed from the adder result, so it must still
    // describe the value the carry-save side is currently reporting.
    always @(posedge clk)
        assert (hi_flag == o_total[7]);

    // P3: the fill field is latched off the reference adder result, so it must
    // still match the coarse magnitude the carry-save side is reporting.
    always @(posedge clk)
        assert (fill == o_total[6:5]);
endmodule

