module fourphase_occupancy (
    input  wire       clk,
    input  wire       i_ce,          // global enable / idle when low
    input  wire       start,         // master wants a new transaction
    input  wire       dev_ack_ready, // device is ready to raise ack
    output reg        req,
    output reg        ack,
    output reg        busy,
    output reg [2:0]  occ,           // outstanding-transaction occupancy
output reg        armed,
output reg [3:0]  ce_ticks,
output reg [3:0]  start_hist
);
    // four-phase handshake sequencer:
    //   phase 0 : idle        (req=0, ack=0)
    //   phase 1 : req raised  (req=1, ack=0)
    //   phase 2 : ack raised  (req=1, ack=1)
    //   phase 3 : req dropped (req=0, ack=1)   -> ack drops, back to idle
    reg [1:0] phase;
    reg       pv;
reg [2:0] occ_pend;   // issued, not yet acknowledged
reg [3:0] ce_ticks_d;
reg [3:0] start_hist_d;

    initial begin
        phase = 2'd0;
        req   = 1'b0;
        ack   = 1'b0;
        busy  = 1'b0;
        occ   = 3'd0;
        armed = 1'b0;
        pv    = 1'b0;
occ_pend = 3'd0;
ce_ticks   = 4'd0;
ce_ticks_d = 4'd0;
start_hist   = 4'd0;
start_hist_d = 4'd0;
    end

    always @(posedge clk)
        pv <= 1'b1;

always @(posedge clk) begin
    if (i_ce) begin
        ce_ticks_d <= ce_ticks;
        ce_ticks   <= ce_ticks + {3'd0, start} + 4'd1;
    end else begin
        ce_ticks   <= ce_ticks_d;
    end
end

always @(posedge clk) begin
    if (i_ce) begin
        start_hist_d <= start_hist;
        start_hist   <= {start_hist[2:0], start ^ dev_ack_ready};
    end else begin
        start_hist   <= start_hist_d;
    end
end

    always @(posedge clk) begin
        if (i_ce) begin
            case (phase)
                2'd0: begin
                    // request may only be launched from idle
                    if (start) begin
                        req   <= 1'b1;
                        busy  <= 1'b1;      // busy mirrors the phase
occ_pend <= occ_pend + 3'd1;   // counted as pending until the device acks
                        phase <= 2'd1;
                    end
                end
                2'd1: begin
                    // req is held; it may not drop until ack rises
                    if (dev_ack_ready) begin
                        ack   <= 1'b1;
occ      <= occ + occ_pend;    // pending transfer is now accepted
occ_pend <= 3'd0;
                        phase <= 2'd2;
                    end
                end
                2'd2: begin
                    // ack seen -> now req is allowed to drop
                    req   <= 1'b0;
                    phase <= 2'd3;
                end
                2'd3: begin
                    // ack drops, transaction retires
                    ack   <= 1'b0;
                    busy  <= 1'b0;
                    occ   <= occ - 3'd1;
                    armed <= 1'b1;   // sticky: first completed handshake arms
                    phase <= 2'd0;
                end
            endcase
        end
    end

    // Property: once at least one handshake has completed (armed), every time the
    // busy flag rises the occupancy must not exceed two.
    always @(posedge clk)
        if (pv && armed && $rose(busy))
            assert (occ <= 3'd2);
endmodule

