module hdmi_agc (
    input wire clk,
    input wire rst,
    input wire en,
    input wire vsync_rise,
    input wire frame_end,
    input wire pix_valid,
    input wire [31:0] luma,
    output wire [31:0] o_pix,
    output wire [31:0] o_gain
);
    localparam [1:0] IDLE  = 2'd0;
    localparam [1:0] ARMED = 2'd1;
    localparam [1:0] ADAPT = 2'd2;
    localparam [1:0] DONE  = 2'd3;
    localparam [31:0] ARM_TH     = 32'd1000;
    localparam [31:0] TARGET     = 32'd50000;
    localparam [31:0] GSTEP      = 32'd16;
    localparam [31:0] ADAPT_LAST = 32'd63;

    reg [31:0] amp_est;
    reg [31:0] gain;
    reg [31:0] hist [0:63];
    reg [5:0]  wr_ptr;
    reg [31:0] adapt_cnt;
    reg [1:0]  phase;
    reg        arm_seen;
    reg        start_seen;
    reg        done_flag;
    reg        win;

    integer i;
    initial begin
        amp_est    = 32'd0;
        gain       = 32'h00010000;
        wr_ptr     = 6'd0;
        adapt_cnt  = 32'd0;
        phase      = IDLE;
        arm_seen   = 1'b0;
        start_seen = 1'b0;
        done_flag  = 1'b0;
        win        = 1'b0;
        for (i = 0; i < 64; i = i + 1)
            hist[i] = 32'd0;
    end

    wire [31:0] abs_luma = luma[31] ? (~luma + 32'd1) : luma;
    wire [31:0] scaled   = luma * {16'd0, gain[31:16]};
    wire [31:0] amp_next = (abs_luma > amp_est) ? abs_luma : (amp_est - (amp_est >> 4));

    always @(posedge clk) begin
        if (rst) begin
            amp_est    <= 32'd0;
            gain       <= 32'h00010000;
            wr_ptr     <= 6'd0;
            adapt_cnt  <= 32'd0;
            phase      <= IDLE;
            arm_seen   <= 1'b0;
            start_seen <= 1'b0;
            done_flag  <= 1'b0;
            win        <= 1'b0;
        end else if (en) begin
            if (vsync_rise) begin
                win        <= 1'b1;
                phase      <= IDLE;
                arm_seen   <= 1'b0;
                start_seen <= 1'b0;
                done_flag  <= 1'b0;
                adapt_cnt  <= 32'd0;
            end else if (frame_end) begin
                win <= 1'b0;
            end else if (win && pix_valid) begin
                hist[wr_ptr] <= scaled;
                wr_ptr       <= wr_ptr + 6'd1;
                amp_est      <= amp_next;
                case (phase)
                    IDLE: begin
                        if (amp_est > ARM_TH) begin
                            phase    <= ARMED;
                            arm_seen <= 1'b1;
                        end
                    end
                    ARMED: begin
                        if (wr_ptr == 6'd63) begin
                            phase      <= ADAPT;
                            start_seen <= 1'b1;
                        end
                    end
                    ADAPT: begin
                        if (amp_est < TARGET)
                            gain <= gain + GSTEP;
                        else if ((amp_est > TARGET) && (gain > GSTEP))
                            gain <= gain - GSTEP;
                        if (adapt_cnt == ADAPT_LAST) begin
                            phase     <= DONE;
                            done_flag <= 1'b1;
                        end else begin
                            adapt_cnt <= adapt_cnt + 32'd1;
                        end
                    end
                    default: ;
                endcase
            end
        end
    end

    assign o_pix  = hist[wr_ptr];
    assign o_gain = gain;

    always @(*) assert (!(win && done_flag) || start_seen);
    always @(*) assert (!(win && start_seen) || arm_seen);
endmodule

