module tcu_useq (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire [2:0]  op,
    input  wire        cond,
    input  wire [1:0]  sel,
    input  wire        tw_en,
    input  wire [1:0]  tw_idx,
    input  wire [15:0] tw_data,
    output wire [15:0] upc_o,
    output wire        ret_valid_o
);
    localparam [2:0] OP_INC  = 3'd0;
    localparam [2:0] OP_JMP  = 3'd1;
    localparam [2:0] OP_BR   = 3'd2;
    localparam [2:0] OP_CALL = 3'd3;
    localparam [2:0] OP_RET  = 3'd4;

    reg [15:0] upc;
    reg [15:0] jt0, jt1, jt2, jt3;
    reg [15:0] ret_reg;
    reg        ret_valid;
    reg [15:0] shadow_ret;
    reg        pv;

    initial upc = 16'h0000;
    initial jt0 = 16'h0000;
    initial jt1 = 16'h0000;
    initial jt2 = 16'h0000;
    initial jt3 = 16'h0000;
    initial ret_reg = 16'h0000;
    initial ret_valid = 1'b0;
    initial shadow_ret = 16'h0000;
    initial pv = 1'b0;

    reg [15:0] tgt;
    always @(*) begin
        case (sel)
            2'd0: tgt = jt0;
            2'd1: tgt = jt1;
            2'd2: tgt = jt2;
            default: tgt = jt3;
        endcase
    end

    wire [15:0] upc_inc = upc + 16'h0001;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            upc        <= 16'h0000;
            jt0        <= 16'h0000;
            jt1        <= 16'h0000;
            jt2        <= 16'h0000;
            jt3        <= 16'h0000;
            ret_reg    <= 16'h0000;
            ret_valid  <= 1'b0;
            shadow_ret <= 16'h0000;
        end else if (en) begin
            if (tw_en) begin
                case (tw_idx)
                    2'd0: jt0 <= tw_data;
                    2'd1: jt1 <= tw_data;
                    2'd2: jt2 <= tw_data;
                    default: jt3 <= tw_data;
                endcase
            end
            case (op)
                OP_INC:  upc <= upc_inc;
                OP_JMP:  upc <= tgt;
                OP_BR:   upc <= cond ? tgt : upc_inc;
                OP_CALL: begin
                    ret_reg    <= upc_inc;
                    shadow_ret <= upc_inc;
                    ret_valid  <= 1'b1;
                    upc        <= tgt;
                end
                OP_RET: begin
                    if (ret_valid) begin
                        upc       <= ret_reg;
                        ret_valid <= 1'b0;
                    end else begin
                        upc <= upc_inc;
                    end
                end
                default: upc <= upc_inc;
            endcase
        end
    end

    assign upc_o = upc;
    assign ret_valid_o = ret_valid;

    always @(posedge clk)
        if (pv && $past(en) && !$past(rst) && ($past(op) == 3'd4) && $past(ret_valid))
            assert (upc == $past(shadow_ret));
endmodule

