    reg wr_q = 1'b0;
    reg [63:0] wdata_q = 64'd0;
    reg [63:0] rdata_q = 64'd0;
    reg [63:0] txn_cnt = 64'd0;
    // core side
    reg req_s1 = 1'b0;
    reg req_s2 = 1'b0;
    reg tgt_seen = 1'b0;
    reg ack_tgl = 1'b0;
    reg [63:0] regs [0:15];
