    reg [1:0]  phase = IDLE;
    reg        armed_seen = 1'b0;
    reg        started_seen = 1'b0;
    reg        fin_q = 1'b0;
    reg [4:0]  cnt = 5'd0;
    reg [15:0] sumA = 16'd0;
    reg [15:0] sumB = 16'd0;

