            ta = {1'b0, a};
            tb = {1'b0, b};
            for (i = 0; i < 8; i = i + 1) begin
                ta = ta + {1'b0, d[i*16 +: 16]};
                if (ta >= 17'd65535) ta = ta - 17'd65535;
                tb = tb + ta;
                if (tb >= 17'd65535) tb = tb - 17'd65535;
            end
            fold = {tb[15:0], ta[15:0]};
        end
    endfunction

    wire [31:0] fold_run   = fold(sumA, sumB, in_data);
    wire [31:0] fold_first = fold(16'd0, 16'd0, in_data);

    always @(posedge clk) begin
        if (rst) begin
            phase <= IDLE;
            armed_seen <= 1'b0;
            started_seen <= 1'b0;
            fin_q <= 1'b0;
            cnt <= 5'd0;
            sumA <= 16'd0;
            sumB <= 16'd0;
        end else if (en) begin
            case (phase)
                IDLE: begin
                    if (arm) begin
                        phase <= ARMED;
                        armed_seen <= 1'b1;
                    end
                end
                ARMED: begin
                    if (in_valid) begin
                        phase <= RUN;
                        started_seen <= 1'b1;
                        cnt <= 5'd1;
                        sumA <= fold_first[15:0];
                        sumB <= fold_first[31:16];
                    end
                end
                RUN: begin
                    if (in_valid) begin
                        sumA <= fold_run[15:0];
                        sumB <= fold_run[31:16];
                        cnt <= cnt + 5'd1;
                        if (in_last || cnt == 5'd23) begin
                            phase <= DONE;
                            fin_q <= 1'b1;
                        end
                    end
                end
                DONE: begin
                    phase <= IDLE;
                    armed_seen <= 1'b0;
                    started_seen <= 1'b0;
                    fin_q <= 1'b0;
                    cnt <= 5'd0;
                end
            endcase
        end
    end

    always @(posedge clk)
        if (fin_q) assert (armed_seen && started_seen);
