                S_PWRUP: begin
                    if (cnt >= 16'd511) begin
                        state <= S_BANDCAL;
                        cnt   <= 16'd0;
                    end else begin
                        cnt <= cnt + 16'd1;
                    end
                end
                S_BANDCAL: begin
                    cnt <= 16'd0;
                    if (band_ok) begin
                        state <= S_CLOSE;
                    end else begin
                        band <= band + 4'd1;
                    end
                end
                S_CLOSE: begin
                    cnt <= cnt + 16'd1;
                    if (cnt >= 16'd200)
                        state <= S_LOCKWAIT;
                end
                S_LOCKWAIT: begin
                    if (!lock_in) begin
                        state <= S_BANDCAL;
                        cnt   <= 16'd0;
                    end else if (cnt >= 16'd1200) begin
                        state <= S_RUN;
                        cnt   <= 16'd0;
                    end else begin
                        cnt <= cnt + 16'd1;
                    end
                end
                S_RUN: begin
                    cnt <= 16'd0;
                    if (!lock_in)
                        state <= S_BANDCAL;
                end
                default: begin
                    state <= S_OFF;
                    cnt   <= 16'd0;
                end
            endcase
