module tpu_dct_xpose (
    input wire clk,
    input wire rst,
    input wire en,
    input wire [15:0] sample_in,
    output wire [15:0] acc_out
);
    reg phase = 1'b0;
    reg [15:0] wr_cnt = 16'd0;
    reg [15:0] rd_cnt = 16'd0;
    reg [15:0] wr_seen = 16'd0;
    reg [15:0] acc = 16'd0;
    reg [15:0] coef_idx = 16'd0;
    reg [15:0] mem [0:23];
    integer i;
    initial begin
        for (i = 0; i < 24; i = i + 1) mem[i] = 16'd0;
    end

    assign acc_out = acc;

    function [15:0] cosv;
        input [2:0] idx;
        begin
            case (idx)
                3'd0: cosv = 16'd23170;
                3'd1: cosv = 16'd32138;
                3'd2: cosv = 16'd30274;
                3'd3: cosv = 16'd27246;
                3'd4: cosv = 16'd23170;
                3'd5: cosv = 16'd18205;
                3'd6: cosv = 16'd12540;
                default: cosv = 16'd6393;
            endcase
        end
    endfunction

    wire [31:0] row_prod = sample_in * cosv(coef_idx[2:0]);
    wire [15:0] rd_word = (rd_cnt < 16'd24) ? mem[rd_cnt[4:0]] : 16'd0;
    wire [31:0] col_prod = rd_word * cosv(coef_idx[2:0]);

    always @(posedge clk) begin
        if (rst) begin
            phase <= 1'b0;
            wr_cnt <= 16'd0;
            rd_cnt <= 16'd0;
            wr_seen <= 16'd0;
            acc <= 16'd0;
            coef_idx <= 16'd0;
        end else if (en) begin
            if (!phase) begin
                if (wr_cnt == 16'd24) begin
                    phase <= 1'b1;
                    rd_cnt <= 16'd0;
                end else begin
                    if (wr_cnt < 16'd24) mem[wr_cnt[4:0]] <= row_prod[15:0];
                    wr_cnt <= wr_cnt + 16'd1;
                    wr_seen <= wr_cnt + 16'd1;
                    coef_idx <= coef_idx + 16'd1;
                end
            end else begin
                if (rd_cnt < 16'd24) begin
                    acc <= acc + col_prod[15:0];
                    rd_cnt <= rd_cnt + 16'd1;
                    coef_idx <= coef_idx + 16'd1;
                end else begin
                    phase <= 1'b0;
                    wr_cnt <= 16'd0;
                    wr_seen <= 16'd0;
                    rd_cnt <= 16'd0;
                    acc <= 16'd0;
                end
            end
        end
    end

    assert property (!phase || (rd_cnt <= wr_seen));
endmodule

