            b2  = ~|y8[7:4];
            y4  = b2 ? y8[3:0] : y8[7:4];
            b1  = ~|y4[3:2];
            y2  = b1 ? y4[1:0] : y4[3:2];
            b0  = ~y2[1];
            if (x == 64'd0)
                lzc_tree = 7'd64;
            else
