        if (rst) begin
            wp <= 64'd0;
            full_q <= 1'b0;
            empty_q <= 1'b1;
            load_own <= 1'b1;
            map_own <= 1'b0;
            armed <= 1'b0;
            out_q <= 64'd0;
        end else if (en) begin
            if (new_frame) begin
                wp <= 64'd0;
                empty_q <= 1'b1;
                full_q <= 1'b0;
                load_own <= 1'b1;
                map_own <= 1'b0;
