    reg [3:0]  wptr = 4'd0;
    reg [3:0]  rptr = 4'd0;
    reg [63:0] count = 64'd0;
    reg [63:0] af_thr = 64'd14;
    reg [63:0] ae_thr = 64'd2;
    reg        full_q = 1'b0;
    reg        empty_q = 1'b1;
    reg        afull_q = 1'b0;
    reg        aempty_q = 1'b1;
    reg        win_q = 1'b0;

    integer i;
    initial begin
        for (i = 0; i < 16; i = i + 1)
            mem[i] = 64'd0;
    end

    wire do_push = push && !full_q;
    wire do_pop  = pop  && !empty_q;

    assign rdata  = mem[rptr];
    assign full   = full_q;
    assign empty  = empty_q;
    assign afull  = afull_q;
    assign aempty = aempty_q;

    always @(posedge clk) begin
        if (!rst_n) begin
            wptr     <= 4'd0;
            rptr     <= 4'd0;
            count    <= 64'd0;
            af_thr   <= 64'd14;
            ae_thr   <= 64'd2;
            full_q   <= 1'b0;
            empty_q  <= 1'b1;
            afull_q  <= 1'b0;
            aempty_q <= 1'b1;
            win_q    <= 1'b0;
        end else if (en) begin
            if (cfg_we) begin
                af_thr <= cfg_af;
                ae_thr <= cfg_ae;
            end
