                win_q <= 1'b0;
            else if (arm)
                win_q <= 1'b1;
            if (do_push) begin
                mem[wptr] <= wdata;
                wptr <= wptr + 4'd1;
            end
            if (do_pop)
                rptr <= rptr + 4'd1;
            if (do_push && !do_pop) begin
                count   <= count + 64'd1;
                empty_q <= 1'b0;
                if (count == 64'd15)
                    full_q <= 1'b1;
                if (count + 64'd1 == af_thr)
                    afull_q <= 1'b1;
                if (count == ae_thr)
                    aempty_q <= 1'b0;
            end else if (do_pop && !do_push) begin
                count <= count - 64'd1;
                if (count == 64'd1)
                    empty_q <= 1'b1;
                if (count == 64'd16)
                    full_q <= 1'b0;
                if (count == af_thr)
                    afull_q <= 1'b0;
                if (count - 64'd1 == ae_thr)
                    aempty_q <= 1'b1;
            end
        end
    end

    assert property (!(win_q && full_q && empty_q));
