module spi_snoop_filter (
    input wire clk,
    input wire en,
    input wire sclk_rise,
    input wire mosi,
    output wire [4:0] o_occ
);
    reg [15:0] sr;
    reg [3:0]  bitcnt;
    reg [15:0] pvec [0:15];
    reg [4:0]  occ_cnt;
    reg        armed;

    integer k;
    initial begin
        sr = 16'd0;
        bitcnt = 4'd0;
        occ_cnt = 5'd0;
        armed = 1'b0;
        for (k = 0; k < 16; k = k + 1)
            pvec[k] = 16'd0;
    end

    wire [15:0] w   = {sr[14:0], mosi};
    wire [1:0]  op  = w[15:14];
    wire [3:0]  idx = w[13:10];
    wire [3:0]  cid = w[9:6];
    wire [15:0] cur = pvec[idx];
    wire [15:0] cmask = 16'd1 << cid;
    wire [15:0] set_v = cur | cmask;
    wire [15:0] clr_v = cur & ~cmask;

    always @(posedge clk) begin
        if (en && sclk_rise) begin
            sr <= w;
            bitcnt <= bitcnt + 4'd1;
            if (bitcnt == 4'd15) begin
                case (op)
                    2'b01: begin
                        pvec[idx] <= set_v;
                        if (cur == 16'd0)
                            occ_cnt <= occ_cnt + 5'd1;
                    end
                    2'b10: begin
                        pvec[idx] <= clr_v;
                        if (cur != 16'd0 && clr_v == 16'd0)
                            occ_cnt <= occ_cnt - 5'd1;
                    end
                    2'b11: begin
                        pvec[idx] <= 16'd0;
                        if (cur != 16'd0) begin
                            occ_cnt <= occ_cnt - 5'd1;
                            armed <= 1'b1;
                        end
                    end
                    default: ;
                endcase
            end
        end
    end

    assign o_occ = occ_cnt;

    always @(posedge clk)
        if (armed)
            assert (occ_cnt <= 5'd16);
endmodule

