module stepper_seq (
    input wire clk,
    input wire i_ce,
    input wire i_open,
    input wire i_close,
    input wire i_arm,
    input wire i_start,
    input wire [7:0] i_rate,
    input wire i_wr,
    input wire [2:0] i_waddr,
    input wire [127:0] i_wdata,
    output wire [127:0] o_coil,
    output wire o_done
);
    localparam [1:0] S_IDLE = 2'd0, S_ARMED = 2'd1, S_RUN = 2'd2, S_DONE = 2'd3;

    reg [1:0] fsm = S_IDLE;
    reg win = 1'b0;
    reg arm_seen = 1'b0;
    reg start_seen = 1'b0;
    reg [2:0] phase = 3'd0;
    reg [7:0] div = 8'd0;
    reg [7:0] rate = 8'd0;

    reg [127:0] pat [0:7];
    integer k;
    initial for (k = 0; k < 8; k = k + 1) pat[k] = 128'd1 << (k * 16);

    always @(posedge clk)
        if (i_ce && i_wr && !win)
            pat[i_waddr] <= i_wdata;

    always @(posedge clk) begin
        if (i_ce) begin
            if (!win) begin
                if (i_open) begin
                    win <= 1'b1;
                    fsm <= S_IDLE;
                    arm_seen <= 1'b0;
                    start_seen <= 1'b0;
                    phase <= 3'd0;
                    div <= 8'd0;
                end
            end else if (i_close) begin
                win <= 1'b0;
            end else begin
                case (fsm)
                    S_IDLE: if (i_arm) begin
                        fsm <= S_ARMED;
                        arm_seen <= 1'b1;
                        rate <= i_rate;
                    end
                    S_ARMED: if (i_start) begin
                        fsm <= S_RUN;
                        start_seen <= 1'b1;
                        div <= 8'd0;
                    end
                    S_RUN: begin
                        if (div == rate) begin
                            div <= 8'd0;
                            phase <= phase + 3'd1;
                            if (phase == 3'd7)
                                fsm <= S_DONE;
                        end else begin
                            div <= div + 8'd1;
                        end
                    end
                    default: if (i_arm) begin
                        fsm <= S_ARMED;
                        start_seen <= 1'b0;
                        rate <= i_rate;
                    end
                endcase
            end
        end
    end

    assign o_coil = pat[phase];
    assign o_done = (fsm == S_DONE);

    always @(*) if (win && fsm == S_DONE) assert (start_seen);
    always @(*) if (win && start_seen) assert (arm_seen);
endmodule

