module doorbell_sweep (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        ring,
    input  wire [5:0]  ring_ch,
    input  wire        ext,
    output reg         busy,
    output reg  [7:0]  svc_cnt,
    output reg  [47:0] pending
);
    reg [5:0] idx;
    reg [7:0] deadline;
    reg       armed;
    reg       pv;
    initial begin
        pending  = 48'd0;
        busy     = 1'b0;
        idx      = 6'd0;
        deadline = 8'd0;
        armed    = 1'b1;
        svc_cnt  = 8'd0;
        pv       = 1'b0;
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (i_ce) begin
            if (ext) armed <= 1'b0;
            if (busy) begin
                if (pending[idx]) svc_cnt <= svc_cnt + 8'd1;
                pending[idx] <= 1'b0;
                deadline <= deadline - 8'd1 + (ext ? 8'd16 : 8'd0);
                if (idx == 6'd47) begin
                    busy <= 1'b0;
                    idx  <= 6'd0;
                end else begin
                    idx <= idx + 6'd1;
                end
            end else if (pending != 48'd0) begin
                busy     <= 1'b1;
                idx      <= 6'd0;
                deadline <= 8'd48;
            end
            if (ring && (ring_ch < 6'd48)) pending[ring_ch] <= 1'b1;
        end
    end

    always @(posedge clk)
        if (armed && busy)
            assert (deadline != 8'd0);

    always @(posedge clk)
        if (pv && armed && $past(i_ce) && $past(busy) && !busy)
            assert ($past(deadline) == 8'd1);
