    reg [63:0]   cnt       = 64'd0;
    reg          wr_lat    = 1'b0;
    reg [4:0]    cs_lat    = 5'd0;
    reg [63:0]   addr_lat  = 64'd0;
    reg [63:0]   wdata_lat = 64'd0;
    reg [63:0]   rdata_lat = 64'd0;
    reg          oe        = 1'b0;
    reg          we        = 1'b0;
    reg          armed     = 1'b0;

