                        phase     <= P_SETUP;
                        cnt       <= 64'd0;
                        wr_lat    <= req_wr;
                        cs_lat    <= req_cs;
                        addr_lat  <= req_addr;
                        wdata_lat <= req_wdata;
                        armed     <= 1'b1;
