                        phase <= P_HOLD;
                        cnt   <= 64'd0;
                        if (!wr_lat) rdata_lat <= i_rdata;
                        oe    <= 1'b0;
                        we    <= 1'b0;
                    end else begin
                        cnt <= cnt + 64'd1;
                    end
                end
                P_HOLD: begin
                    if (cnt >= t_hold) begin
                        phase <= P_IDLE;
                        cnt   <= 64'd0;
                    end else begin
                        cnt <= cnt + 64'd1;
                    end
                end
            endcase
        end
