module stream_buffer (
    input wire clk,
    input wire ce,
    input wire flush,
    input wire [31:0] miss_addr,
    input wire fill,
    input wire [31:0] fill_data,
    input wire req,
    input wire [31:0] req_addr,
    output wire hit,
    output wire [31:0] hit_data,
    output wire [31:0] hit_tag
);
    reg [31:0] head = 32'd0;
    reg [31:0] tail = 32'd0;
    reg [6:0]  count = 7'd0;
    reg [5:0]  wptr = 6'd0;
    reg [5:0]  rptr = 6'd0;
    reg [63:0] valid = 64'd0;
    reg [31:0] tag_mem  [0:63];
    reg [31:0] data_mem [0:63];
    reg [31:0] fills = 32'd0;
    reg [31:0] hits  = 32'd0;
    reg armed = 1'b1;
    reg pv = 1'b0;
    integer i;
    initial begin
        for (i = 0; i < 64; i = i + 1) begin
            tag_mem[i]  = 32'd0;
            data_mem[i] = 32'd0;
        end
    end

    wire do_fill = ce && !flush && fill && (count != 7'd64);
    wire do_hit  = ce && !flush && req && (count != 7'd0) && (req_addr == head);

    assign hit      = do_hit;
    assign hit_data = data_mem[rptr];
    assign hit_tag  = tag_mem[rptr];

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (ce) begin
            if (flush) begin
                head  <= miss_addr + 32'd1;
                tail  <= miss_addr + 32'd1;
                count <= 7'd0;
                wptr  <= 6'd0;
                rptr  <= 6'd0;
                valid <= 64'd0;
                armed <= 1'b0;
            end else begin
                if (do_fill) begin
                    tag_mem[wptr]  <= tail;
                    data_mem[wptr] <= fill_data;
                    tail  <= tail + 32'd1;
                    wptr  <= wptr + 6'd1;
                    fills <= fills + 32'd1;
                end
                if (do_hit) begin
                    rptr <= rptr + 6'd1;
                    head <= head + 32'd1;
                    hits <= hits + 32'd1;
                end
                valid <= (valid | (do_fill ? (64'd1 << wptr) : 64'd0))
                         & ~(do_hit ? (64'd1 << rptr) : 64'd0);
                case ({do_fill, do_hit})
                    2'b10:   count <= count + 7'd1;
                    2'b01:   count <= count - 7'd1;
                    default: count <= count;
                endcase
            end
        end
    end

    always @(posedge clk)
        if (pv && armed && $stable(fills) && $past(fills == hits))
            assert ($stable(hits));
endmodule

