module lza_normalizer (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_ce,
    input  wire        i_ld,
    input  wire [31:0] i_a,
    input  wire [31:0] i_b,
    output reg  [31:0] o_sum,
    output wire        o_done
);
    function [31:0] clz32;
        input [31:0] v;
        integer i;
        reg found;
        begin
            clz32 = 32'd32;
            found = 1'b0;
            for (i = 31; i >= 0; i = i - 1) begin
                if (!found && v[i]) begin
                    clz32 = 31 - i;
                    found = 1'b1;
                end
            end
        end
    endfunction

    reg [31:0] ind = 32'd0;
    reg [31:0] rem = 32'd32;
    initial o_sum = 32'd0;

    wire [31:0] t_str = i_a ^ i_b;
    wire [31:0] g_str = i_a & i_b;
    wire [31:0] f_new = t_str | g_str;

    wire [31:0] lz_of_ind = clz32(ind);
    wire busy = (rem != 32'd0) && (rem != 32'd32);

    assign o_done = (rem == 32'd0);

    always @(posedge clk) begin
        if (rst) begin
            ind   <= 32'd0;
            rem   <= 32'd32;
            o_sum <= 32'd0;
        end else if (i_ce) begin
            if (i_ld) begin
                ind   <= f_new;
                rem   <= clz32(f_new);
                o_sum <= i_a + i_b;
            end else if (busy) begin
                ind   <= ind << 1;
                rem   <= rem - 32'd1;
                o_sum <= o_sum << 1;
            end
        end
    end

    always @(posedge clk)
        if (o_done) assert (ind[31]);
endmodule

