    input wire i_reset,
    input wire i_ce,
    input wire i_load,
    input wire i_abort,
    input wire [63:0] i_dest,
    input wire [63:0] i_field,
    input wire [5:0] i_off,
    input wire [6:0] i_len,
    output wire [63:0] o_result,
    output wire o_done
);
    reg [1:0] phase = 2'd0;
    reg [63:0] dest = 64'd0;
    reg [63:0] field = 64'd0;
    reg [63:0] shifted = 64'd0;
    reg [63:0] mask = 64'd0;
    reg [63:0] result = 64'd0;
    reg [5:0] off = 6'd0;
    reg [6:0] len = 7'd0;
    reg armed_seen = 1'b0;
    reg start_seen = 1'b0;
    reg done_seen = 1'b0;
    reg pre_r = 1'b1;

    wire [63:0] lowmask = (len >= 7'd64) ? {64{1'b1}} : ((64'd1 << len) - 64'd1);

    always @(posedge clk) begin
        if (i_reset) begin
            phase <= 2'd0;
            armed_seen <= 1'b0;
            start_seen <= 1'b0;
            done_seen <= 1'b0;
        end else if (i_ce) begin
            if (i_abort && (phase != 2'd0)) begin
                phase <= 2'd0;
                pre_r <= 1'b0;
            end else begin
                case (phase)
                    2'd0: if (i_load) begin
                        dest <= i_dest;
                        field <= i_field;
                        off <= i_off;
                        len <= (i_len > 7'd64) ? 7'd64 : i_len;
                        phase <= 2'd1;
                        armed_seen <= 1'b1;
                    end
                    2'd1: begin
                        shifted <= field << off;
                        mask <= lowmask << off;
                        phase <= 2'd2;
                        start_seen <= 1'b1;
                    end
                    2'd2: begin
                        result <= (dest & ~mask) | (shifted & mask);
                        phase <= 2'd3;
                        done_seen <= 1'b1;
                    end
                    default: phase <= 2'd0;
                endcase
            end
        end
    end

    assign o_result = result;
    assign o_done = (phase == 2'd3);

    always @(posedge clk)
        if (pre_r) assert (!done_seen || (start_seen && armed_seen));
