module vend_ctrl (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire       coin_valid,
    input  wire [7:0] coin_val,
    input  wire       select,
    input  wire       cancel,
    output wire       vend,
    output wire       change_ret,
    output wire [7:0] change_out
);
    localparam [1:0] S_IDLE    = 2'd0;
    localparam [1:0] S_COLLECT = 2'd1;
    localparam [1:0] S_VEND    = 2'd2;
    localparam [1:0] S_CHANGE  = 2'd3;
    localparam [7:0] PRICE     = 8'd75;

    reg [1:0] state;
    reg [7:0] credit;
    reg [7:0] change_amt;
    reg       vend_r;
    reg       chg_r;
    reg       pv;
    initial begin
        state = S_IDLE; credit = 8'd0; change_amt = 8'd0;
        vend_r = 1'b0; chg_r = 1'b0; pv = 1'b0;
    end

    wire [8:0] sum     = {1'b0, credit} + {1'b0, coin_val};
    wire [7:0] sat_sum = sum[8] ? 8'd255 : sum[7:0];

    assign vend       = vend_r;
    assign change_ret = chg_r;
    assign change_out = change_amt;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            state <= S_IDLE; credit <= 8'd0; change_amt <= 8'd0;
            vend_r <= 1'b0; chg_r <= 1'b0;
        end else if (ce) begin
            case (state)
                S_IDLE: begin
                    if (coin_valid) begin
                        credit <= sat_sum;
                        state  <= S_COLLECT;
                    end
                end
                S_COLLECT: begin
                    if (select && credit >= PRICE) begin
                        credit <= credit - PRICE;
                        state  <= S_VEND;
                        vend_r <= 1'b1;
                    end else if (cancel) begin
                        change_amt <= credit;
                        credit     <= 8'd0;
                        state      <= S_CHANGE;
                        chg_r      <= 1'b1;
                    end else if (coin_valid) begin
                        credit <= sat_sum;
                    end
                end
                S_VEND: begin
                    vend_r <= 1'b0;
                    if (credit != 8'd0) begin
                        change_amt <= credit;
                        credit     <= 8'd0;
                        state      <= S_CHANGE;
                        chg_r      <= 1'b1;
                    end else begin
                        state <= S_IDLE;
                    end
                end
                S_CHANGE: begin
                    chg_r      <= 1'b0;
                    change_amt <= 8'd0;
                    state      <= S_IDLE;
                end
            endcase
        end
    end

    always @(posedge clk)
        if (pv && $rose(vend_r))
            assert (!chg_r);
endmodule

