                if (i_start) begin
                    busy <= 1'b1;
                    shift_r <= i_shift;
                    win_len <= 64'd1 << i_shift;
                    countdown <= 64'd1 << i_shift;
                    win_cnt <= 64'd0;
                    acc <= 64'd0;
                end
