module forth_rng_word (
    input  wire       clk,
    input  wire       ce,
    input  wire       go,
    output wire [7:0] rnd,
    output reg        busy
);
    reg [7:0] prng;
    reg [7:0] cd;
    reg [7:0] steps;
    initial begin prng = 8'h5A; cd = 8'd0; steps = 8'd0; busy = 1'b0; end

    // 8-bit xorshift (7,5,3)
    wire [7:0] x1 = prng ^ (prng << 7);
    wire [7:0] x2 = x1 ^ (x1 >> 5);
    wire [7:0] x3 = x2 ^ (x2 << 3);

    assign rnd = prng;

    always @(posedge clk) begin
        if (ce) begin
            if (!busy) begin
                if (go) begin
                    busy  <= 1'b1;
                    steps <= 8'd0;
                    cd    <= 8'd8;
                end
            end else begin
                prng <= x3;
                cd   <= cd - 8'd1;
                if (steps == 8'd7)
                    busy <= 1'b0;
                else
                    steps <= steps + 8'd1;
            end
        end
    end

    // countdown never expires while the request is outstanding
    always @(posedge clk)
        if (busy)
            assert (cd != 8'd0);

    // on the final shift round, exactly one tick of budget remains
    always @(posedge clk)
        if (busy && steps == 8'd7)
            assert (cd == 8'd1);
endmodule

