    assign o_rd   = adv;
    assign o_eol  = adv && eol;
    assign o_eof  = adv && eof;

    always @(posedge clk) begin
        if (start)
            armed <= 1'b1;
        if (adv) begin
            if (eof) begin
                base     <= base_in;
                cur_addr <= base_in;
                line     <= 32'd0;
                px       <= 32'd0;
            end else if (eol) begin
                px       <= 32'd0;
                line     <= line + 32'd1;
                cur_addr <= cur_addr + 32'd1;
            end else begin
                px       <= px + 32'd1;
                cur_addr <= cur_addr + 32'd1;
            end
        end
    end

    // after scanout has been started, the fetch address stays inside the frame
    always @(posedge clk)
        if (armed)
            assert (cur_addr - base <= 32'd1023);
