module axis_scan_lockup (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_ce,
    input  wire        i_sof,
    input  wire        i_eof,
    input  wire        i_vld,
    input  wire [63:0] i_data,
    output wire        o_vld,
    output wire [63:0] o_data
);
    // Scan segment A (MAC-side domain): 4 beats of 64-bit stream data
    reg [3:0]   a_v;
    reg [255:0] a_d;
    // Lockup latch between segments: holds A's tail beat for a half cycle
    reg         lk_v;
    reg [63:0]  lk_d;
    // Scan segment B (UDP-side domain): 4 beats
    reg [3:0]   b_v;
    reg [255:0] b_d;
    // Occupancy of valid beats across the whole chain (8 entries + lockup)
    reg [63:0]  occ;
    // Packet window: opened by start-of-frame, closed by end-of-frame
    reg         armed;

    initial a_v   = 4'b0000;
    initial a_d   = 256'd0;
    initial lk_v  = 1'b0;
    initial lk_d  = 64'd0;
    initial b_v   = 4'b0000;
    initial b_d   = 256'd0;
    initial occ   = 64'd0;
    initial armed = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            a_v   <= 4'b0000;
            a_d   <= 256'd0;
            lk_v  <= 1'b0;
            lk_d  <= 64'd0;
            b_v   <= 4'b0000;
            b_d   <= 256'd0;
            occ   <= 64'd0;
            armed <= 1'b0;
        end else if (i_ce) begin
            a_v   <= {a_v[2:0], i_vld};
            a_d   <= {a_d[191:0], i_data};
            lk_v  <= a_v[3];
            lk_d  <= a_d[255:192];
            b_v   <= {b_v[2:0], lk_v};
            b_d   <= {b_d[191:0], lk_d};
            occ   <= occ + {63'd0, i_vld} - {63'd0, b_v[3]};
            armed <= (armed | i_sof) & ~i_eof;
        end
    end

    assign o_vld  = b_v[3];
    assign o_data = b_d[255:192];

    always @(*)
        assert (!armed || occ <= 64'd9);
endmodule

