                busy <= 1'b1;
                pos <= 64'd0;
                cd <= K;
                a_r <= a_in;
                b_r <= b_in;
                op_r <= op;
                lsz_r <= lsz;
                carry <= 1'b0;
            end
        end
    end

    assign busy_o = busy;
    assign result = res;
    assign lane_flags = flg;

    always @(*) if (busy) assert (cd != 64'd0);
    always @(*) if (!busy) assert (cd == 64'd0);
