module rns_alu (
    input wire clk,
    input wire en,
    input wire [1:0] op,
    input wire [7:0] op_a,
    output wire [7:0] result,
    output wire rns_zero
);
    localparam OP_LOAD = 2'd0;
    localparam OP_ADD  = 2'd1;
    localparam OP_SUB  = 2'd2;
    localparam OP_MUL  = 2'd3;

    // residue registers, one per modulus channel (moduli 5 and 7)
    reg [2:0] r5;
    reg [2:0] r7;
    // binary mirror accumulator modulo 35 (= 5*7)
    reg [7:0] acc;
    // sticky scope register: set at the first LOAD
    reg armed;

    initial begin
        r5 = 3'd0;
        r7 = 3'd0;
        acc = 8'd0;
        armed = 1'b0;
    end

    // operand residues
    wire [15:0] opw = {8'd0, op_a};
    wire [15:0] a5  = opw % 16'd5;
    wire [15:0] a7  = opw % 16'd7;
    wire [15:0] a35 = opw % 16'd35;

    wire [15:0] r5w  = {13'd0, r5};
    wire [15:0] r7w  = {13'd0, r7};
    wire [15:0] accw = {8'd0, acc};

    // channel 5
    wire [15:0] n5_add = (r5w + a5) % 16'd5;
    wire [15:0] n5_sub = (r5w + 16'd5 - a5) % 16'd5;
    wire [15:0] n5_mul = (r5w * a5) % 16'd5;
    // channel 7
    wire [15:0] n7_add = (r7w + a7) % 16'd7;
    wire [15:0] n7_sub = (r7w + 16'd7 - a7) % 16'd7;
    wire [15:0] n7_mul = (r7w * a7) % 16'd7;
    // binary mirror mod 35
    wire [15:0] nb_add = (accw + a35) % 16'd35;
    wire [15:0] nb_sub = (accw + 16'd35 - a35) % 16'd35;
    wire [15:0] nb_mul = (accw * a35) % 16'd35;

    always @(posedge clk) begin
        if (en) begin
            case (op)
                OP_LOAD: begin
                    r5 <= a5[2:0];
                    r7 <= a7[2:0];
                    acc <= a35[7:0];
                    armed <= 1'b1;
                end
                OP_ADD: begin
                    r5 <= n5_add[2:0];
                    r7 <= n7_add[2:0];
                    acc <= nb_add[7:0];
                end
                OP_SUB: begin
                    r5 <= n5_sub[2:0];
                    r7 <= n7_sub[2:0];
                    acc <= nb_sub[7:0];
                end
                default: begin
                    r5 <= n5_mul[2:0];
                    r7 <= n7_mul[2:0];
                    acc <= nb_mul[7:0];
                end
            endcase
        end
    end

    assign result = acc;
    assign rns_zero = (r5 == 3'd0) && (r7 == 3'd0);

    // Absence after first LOAD: RNS zero flag and nonzero binary mirror never together
    assert property (!armed || !((r5 == 3'd0) && (r7 == 3'd0) && (acc != 8'd0)));
endmodule

