    reg        in_reset    = 1'b0;
    reg [31:0] shift       = 32'd0;
    reg [31:0] bit_cnt     = 32'd0;
    reg [31:0] pulse_timer = 32'd0;
    reg [31:0] gap_cnt     = 32'd0;
    reg [31:0] deadline    = 32'd0;

    assign busy_o = busy;
    assign ready  = !busy;

    always @(*) begin
        dout = busy && !in_reset && (pulse_timer < (shift[23] ? T_HI1 : T_HI0));
    end

    always @(posedge clk) begin
        if (rst) begin
            busy        <= 1'b0;
            in_reset    <= 1'b0;
            shift       <= 32'd0;
            bit_cnt     <= 32'd0;
            pulse_timer <= 32'd0;
            gap_cnt     <= 32'd0;
            deadline    <= 32'd0;
