            if (!busy) begin
                if (start) begin
                    busy        <= 1'b1;
                    in_reset    <= 1'b0;
                    shift       <= {8'd0, color};
                    bit_cnt     <= N_BITS;
                    pulse_timer <= 32'd0;
                    gap_cnt     <= 32'd0;
                    deadline    <= K;
                end
            end else begin
                deadline <= deadline - 32'd1;
                if (!in_reset) begin
                    if (pulse_timer == T_BIT - 32'd1) begin
                        pulse_timer <= 32'd0;
                        shift       <= shift << 1;
                        if (bit_cnt == 32'd1) begin
                            bit_cnt  <= 32'd0;
                            in_reset <= 1'b1;
                            gap_cnt  <= T_RESET;
                        end else begin
                            bit_cnt <= bit_cnt - 32'd1;
                        end
                    end else begin
                        pulse_timer <= pulse_timer + 32'd1;
                    end
                end else begin
                    if (gap_cnt == 32'd1) begin
                        gap_cnt  <= 32'd0;
                        in_reset <= 1'b0;
                        busy     <= 1'b0;
                    end else begin
                        gap_cnt <= gap_cnt - 32'd1;
                    end
                end
            end
        end
    end

    always @(posedge clk)
        if (busy)
            assert (deadline != 32'd0);
