module tapeout_i2f (
    input wire clk,
    input wire en,
    input wire arm,
    input wire start,
    input wire [7:0] din,
    input wire q_sess,
    input wire r_sess,
    output reg [7:0] fout,
    output reg fin
);
    localparam [1:0] IDLE = 2'd0, ARMED = 2'd1, NORM = 2'd2, DONE = 2'd3;

    reg [1:0] phase;
    reg arm_f, start_f;
    reg [7:0] mant;
    reg [3:0] exp;
    reg win;

    initial begin
        phase = IDLE; arm_f = 1'b0; start_f = 1'b0;
        mant = 8'd0; exp = 4'd0; fout = 8'd0; fin = 1'b0; win = 1'b0;
    end

    wire guard_b = mant[3];
    wire sticky_b = |mant[2:0];
    wire rup = guard_b && (sticky_b || mant[4]);
    wire [2:0] mfrac = mant[6:4];
    wire [2:0] mr = (rup && mfrac != 3'b111) ? (mfrac + 3'd1) : mfrac;
    wire [7:0] rounded = (mant == 8'd0) ? 8'd0 : {1'b0, exp, mr};

    always @(posedge clk) begin
        if (en) begin
            if (q_sess) begin
                win <= 1'b1;
                arm_f <= 1'b0;
                start_f <= 1'b0;
                phase <= IDLE;
                fin <= 1'b0;
            end else begin
                if (r_sess) win <= 1'b0;
                fin <= 1'b0;
                case (phase)
                    IDLE: if (arm) begin
                        mant <= din; exp <= 4'd7; arm_f <= 1'b1; phase <= ARMED;
                    end
                    ARMED: if (start) begin
                        start_f <= 1'b1; phase <= NORM;
                    end
                    NORM: begin
                        if (mant != 8'd0 && !mant[7]) begin
                            mant <= mant << 1;
                            exp <= exp - 4'd1;
                        end else begin
                            phase <= DONE;
                            fin <= 1'b1;
                            fout <= rounded;
                        end
                    end
                    DONE: if (arm) begin
                        mant <= din; exp <= 4'd7; arm_f <= 1'b1; phase <= ARMED;
                    end
                endcase
            end
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && win && $past(win) && fin)
            assert ($past(arm_f) && $past(start_f));
endmodule

