module wl_map_scan (
    input wire clk,
    input wire rst,
    input wire en,
    input wire req,
    input wire [4:0] lblk,
    output reg busy,
    output reg done
);
    reg [4:0]  map_mem   [0:31];
    reg [15:0] erase_cnt [0:31];
    reg [5:0]  scan_idx;
    reg [5:0]  countdown;
    reg [4:0]  best_idx;
    reg [15:0] best_cnt;
    reg [4:0]  tgt;
    integer i;

    initial busy = 1'b0;
    initial done = 1'b0;
    initial scan_idx = 6'd0;
    initial countdown = 6'd0;
    initial best_idx = 5'd0;
    initial best_cnt = 16'hFFFF;
    initial tgt = 5'd0;
    initial begin
        for (i = 0; i < 32; i = i + 1) begin
            map_mem[i] = i;
            erase_cnt[i] = 16'd0;
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            busy <= 1'b0;
            done <= 1'b0;
            scan_idx <= 6'd0;
            countdown <= 6'd0;
            best_idx <= 5'd0;
            best_cnt <= 16'hFFFF;
            tgt <= 5'd0;
            for (i = 0; i < 32; i = i + 1) begin
                map_mem[i] <= i;
                erase_cnt[i] <= 16'd0;
            end
        end else if (en) begin
            done <= 1'b0;
            if (!busy) begin
                if (req) begin
                    busy <= 1'b1;
                    tgt <= lblk;
                    scan_idx <= 6'd0;
                    countdown <= 6'd33;
                    best_cnt <= 16'hFFFF;
                end
            end else if (scan_idx < 6'd32) begin
                if (erase_cnt[scan_idx[4:0]] < best_cnt) begin
                    best_idx <= scan_idx[4:0];
                    best_cnt <= erase_cnt[scan_idx[4:0]];
                end
                scan_idx <= scan_idx + 6'd1;
                countdown <= countdown - 6'd1;
            end else if (scan_idx == 6'd32) begin
                map_mem[tgt] <= best_idx;
                if (erase_cnt[best_idx] != 16'hFFFF)
                    erase_cnt[best_idx] <= erase_cnt[best_idx] + 16'd1;
                busy <= 1'b0;
                countdown <= countdown - 6'd1;
                done <= 1'b1;
            end
        end
    end

    always @(posedge clk)
        if (busy) assert (countdown != 6'd0);
endmodule

