        if (rst) begin
            env  <= 64'd0;
            gain <= UNITY;
            tgt  <= UNITY;
            pend <= 1'b0;
            cd   <= 64'd0;
            step <= 64'd0;
            win  <= 1'b0;
            for (i = 0; i < 8; i = i + 1) hist[i] <= UNITY;
