            case (a)
                4'd0:  rom = 32'd0;
                4'd1:  rom = 32'd3;
                4'd2:  rom = 32'd5;
                4'd3:  rom = 32'd8;
                4'd4:  rom = 32'd7;
                4'd5:  rom = 32'd10;
                4'd6:  rom = 32'd12;
                4'd7:  rom = 32'd15;
                4'd8:  rom = 32'd11;
                4'd9:  rom = 32'd14;
                4'd10: rom = 32'd16;
                4'd11: rom = 32'd19;
                4'd12: rom = 32'd18;
                4'd13: rom = 32'd21;
                4'd14: rom = 32'd23;
                default: rom = 32'd26;
            endcase
        end
    endfunction

    reg [31:0] x0, x1, x2, x3;
    reg [63:0] acc;
    reg [31:0] cnt;
    reg [31:0] rem;
    reg        busy;
    reg        win;

    initial x0 = 32'd0;
    initial x1 = 32'd0;
    initial x2 = 32'd0;
    initial x3 = 32'd0;
    initial acc = 64'd0;
    initial cnt = 32'd0;
    initial rem = 32'd32;
    initial busy = 1'b0;
    initial win = 1'b0;

    wire [3:0]  addr  = {x3[0], x2[0], x1[0], x0[0]};
    wire [63:0] slice = {32'd0, rom(addr)} << cnt;

    always @(posedge clk) begin
        if (rst) begin
            x0   <= 32'd0;
            x1   <= 32'd0;
            x2   <= 32'd0;
            x3   <= 32'd0;
            acc  <= 64'd0;
            cnt  <= 32'd0;
            rem  <= 32'd32;
            busy <= 1'b0;
            win  <= 1'b0;
        end else if (en) begin
            if (!busy) begin
                if (start) begin
                    x0   <= d0;
                    x1   <= d1;
                    x2   <= d2;
                    x3   <= d3;
                    acc  <= 64'd0;
                    cnt  <= 32'd0;
                    rem  <= 32'd32;
                    busy <= 1'b1;
                    win  <= 1'b1;
                end
            end else begin
                acc <= acc + slice;
                x0  <= {1'b0, x0[31:1]};
                x1  <= {1'b0, x1[31:1]};
                x2  <= {1'b0, x2[31:1]};
                x3  <= {1'b0, x3[31:1]};
                cnt <= cnt + 32'd1;
                rem <= rem - 32'd1;
                if (cnt == 32'd31) begin
                    busy <= 1'b0;
                    win  <= 1'b0;
                end
            end
        end
    end

    assign y    = acc;
    assign done = busy && en && (cnt == 32'd31);

    // A1 / A2: bounded counts inside the window
    always @(*) if (win) assert (cnt <= 32'd32);
    always @(*) if (win) assert (rem <= 32'd32);
endmodule

