    input  wire       clk,
    input  wire       rst_n,
    input  wire       en,
    input  wire [7:0] pri_data,
    input  wire [7:0] bak_data,
    input  wire       pri_fault,
    input  wire       pri_ok,
    output wire [7:0] out_data
);
    reg [7:0] health     = 8'd0;
    reg       arm_f      = 1'b0;
    reg       start_f    = 1'b0;
    reg       fin_f      = 1'b0;
    reg       active_src = 1'b0;
    reg       pv         = 1'b0;

