module sd_line_fill_uart #(
    parameter [15:0] CLKS_PER_BIT = 16'd16
) (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire        rx,
    input  wire        flush,
    output wire [15:0] o_occ,
    output wire        o_full,
    output wire        o_ferr,
    output wire [15:0] o_word0
);
    localparam [1:0] S_IDLE  = 2'd0;
    localparam [1:0] S_START = 2'd1;
    localparam [1:0] S_DATA  = 2'd2;
    localparam [1:0] S_STOP  = 2'd3;

    reg [1:0]  st;
    reg [15:0] baud_cnt;
    reg [15:0] bit_cnt;
    reg [15:0] shreg;
    reg [15:0] line [0:7];
    reg [2:0]  wr_ptr;
    reg [15:0] occ;
    reg        line_full;
    reg        frame_err;
    reg        armed;
    reg        rx_prev;

    integer i;
    initial begin
        st = S_IDLE;
        baud_cnt = 16'd0;
        bit_cnt = 16'd0;
        shreg = 16'd0;
        wr_ptr = 3'd0;
        occ = 16'd0;
        line_full = 1'b0;
        frame_err = 1'b0;
        armed = 1'b0;
        rx_prev = 1'b1;
        for (i = 0; i < 8; i = i + 1) line[i] = 16'd0;
    end

    always @(posedge clk) begin
        if (rst) begin
            st <= S_IDLE;
            baud_cnt <= 16'd0;
            bit_cnt <= 16'd0;
            shreg <= 16'd0;
            wr_ptr <= 3'd0;
            occ <= 16'd0;
            line_full <= 1'b0;
            frame_err <= 1'b0;
            armed <= 1'b0;
            rx_prev <= 1'b1;
        end else if (en) begin
            rx_prev <= rx;
            case (st)
                S_IDLE: begin
                    baud_cnt <= 16'd0;
                    bit_cnt <= 16'd0;
                    if (rx_prev && !rx) st <= S_START;
                end
                S_START: begin
                    if (baud_cnt == (CLKS_PER_BIT >> 1) - 16'd1) begin
                        baud_cnt <= 16'd0;
                        if (!rx) st <= S_DATA;
                        else st <= S_IDLE;
                    end else begin
                        baud_cnt <= baud_cnt + 16'd1;
                    end
                end
                S_DATA: begin
                    if (baud_cnt == CLKS_PER_BIT - 16'd1) begin
                        baud_cnt <= 16'd0;
                        shreg <= {rx, shreg[15:1]};
                        if (bit_cnt == 16'd15) begin
                            bit_cnt <= 16'd0;
                            st <= S_STOP;
                        end else begin
                            bit_cnt <= bit_cnt + 16'd1;
                        end
                    end else begin
                        baud_cnt <= baud_cnt + 16'd1;
                    end
                end
                S_STOP: begin
                    if (baud_cnt == CLKS_PER_BIT - 16'd1) begin
                        baud_cnt <= 16'd0;
                        st <= S_IDLE;
                        if (!rx) begin
                            frame_err <= 1'b1;
                        end else if (!line_full) begin
                            line[wr_ptr] <= shreg;
                            wr_ptr <= wr_ptr + 3'd1;
                            occ <= occ + 16'd1;
                            line_full <= ((occ + 16'd1) == 16'd8);
                            armed <= 1'b1;
                        end
                    end else begin
                        baud_cnt <= baud_cnt + 16'd1;
                    end
                end
            endcase
            if (flush) begin
                occ <= 16'd0;
                wr_ptr <= 3'd0;
                line_full <= 1'b0;
                frame_err <= 1'b0;
            end
        end
    end

    assign o_occ = occ;
    assign o_full = line_full;
    assign o_ferr = frame_err;
    assign o_word0 = line[0];

    always @(posedge clk)
        if (armed)
            assert (occ <= 16'd8);
endmodule


