module json_key_fuzzy_match (
    input wire clk,
    input wire rst,
    input wire en,
    input wire [7:0] key_in,
    input wire [7:0] query,
    input wire ld_tol,
    input wire [3:0] tol_in,
    input wire q_open,
    input wire q_close,
