module hdmi_line_window (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire        line_start,
    input  wire        line_stop,
    input  wire [31:0] sample_in,
    output reg  [31:0] y
);
    reg [31:0] win_rom [0:255];
    reg [31:0] idx;
    reg [31:0] dn;
    reg        win;

    integer i;
    initial begin
        for (i = 0; i < 256; i = i + 1) begin
            if (i < 128)
                win_rom[i] = i * i * 4;
            else
                win_rom[i] = (255 - i) * (255 - i) * 4;
        end
    end

    initial begin
        idx = 32'd0;
        dn  = 32'd255;
        win = 1'b0;
        y   = 32'd0;
    end

    wire [32:0] coef_sum = {1'b0, win_rom[idx[7:0]]} + {1'b0, win_rom[dn[7:0]]};
    wire [31:0] coef     = coef_sum[32:1];
    wire [63:0] prod     = sample_in * coef;

    always @(posedge clk) begin
        if (rst) begin
            idx <= 32'd0;
            dn  <= 32'd255;
            win <= 1'b0;
            y   <= 32'd0;
        end else if (en) begin
            if (dn == 32'd0) begin
                idx <= 32'd0;
                dn  <= 32'd255;
            end else begin
                idx <= idx + 32'd1;
                dn  <= dn - 32'd1;
            end
            win <= line_start ? 1'b1 : (line_stop ? 1'b0 : win);
            y   <= prod[31:0];
        end
    end

    assert property (!win || idx <= 32'd255);
endmodule

