module jls_pausible_clkctl (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire areq,
    input wire mutex_gnt,
    input wire [31:0] din,
    input wire sof,
    input wire eof,
    input wire [7:0] raddr,
    output wire [31:0] dout,
    output wire ring_clk_en
);
    localparam [1:0] IDLE = 2'd0, ARMED = 2'd1, STARTED = 2'd2;

    reg [1:0] phase = 2'd0;
    reg hs_latch = 1'b0;
    reg clk_en = 1'b1;
    reg [31:0] arm_cnt = 32'd0;
    reg [31:0] start_cnt = 32'd0;
    reg [31:0] fin_cnt = 32'd0;
    reg [7:0] wptr = 8'd0;
    reg win = 1'b0;
    reg [31:0] linebuf [0:255];

    integer i;
    initial begin
        for (i = 0; i < 256; i = i + 1)
            linebuf[i] = 32'd0;
    end

    assign dout = linebuf[raddr];
    assign ring_clk_en = clk_en;

    always @(posedge clk) begin
        if (!rst_n) begin
            phase <= IDLE;
            hs_latch <= 1'b0;
            clk_en <= 1'b1;
            arm_cnt <= 32'd0;
            start_cnt <= 32'd0;
            fin_cnt <= 32'd0;
            wptr <= 8'd0;
            win <= 1'b0;
        end else if (en) begin
            if (eof)
                win <= 1'b0;
            else if (sof)
                win <= 1'b1;
            case (phase)
                IDLE: begin
                    if (areq) begin
                        hs_latch <= 1'b1;
                        phase <= ARMED;
                        arm_cnt <= arm_cnt + 32'd1;
                    end
                end
                ARMED: begin
                    if (mutex_gnt) begin
                        clk_en <= 1'b0;
                        phase <= STARTED;
                        start_cnt <= start_cnt + 32'd1;
                    end
                end
                STARTED: begin
                    wptr <= wptr + 8'd1;
                    hs_latch <= 1'b0;
                    clk_en <= 1'b1;
                    phase <= IDLE;
                    fin_cnt <= fin_cnt + 32'd1;
                end
                default: begin
                    phase <= IDLE;
                end
            endcase
        end
    end

    always @(posedge clk) begin
        if (rst_n && en && phase == STARTED)
            linebuf[wptr] <= din;
    end

    always @(posedge clk)
        if (win && phase == 2'd2)
            assert (arm_cnt == start_cnt && start_cnt == fin_cnt + 32'd1 && !clk_en);
endmodule

