    input wire rst,
    input wire en,
    input wire wr,
    input wire [2:0] wr_idx,
    input wire [2:0] wr_func,
    input wire lock_req,
    input wire [7:0] gpio_out,
    input wire pll_clk,
    input wire dac_bit,
    input wire uart_tx,
    output wire [7:0] pad_out,
    output wire o_err,
    output wire o_locked
);
    reg [23:0] func_sel;
    reg [31:0] wr_cnt;
    reg [31:0] cm_cnt;
    reg err;
    reg locked;
    reg pre_lock;
    integer k;

    initial begin
        func_sel = 24'd0;
        wr_cnt = 32'd0;
        cm_cnt = 32'd0;
        err = 1'b0;
        locked = 1'b0;
        pre_lock = 1'b1;
    end

    always @(posedge clk) begin
        if (rst) begin
            func_sel <= 24'd0;
            wr_cnt <= 32'd0;
            cm_cnt <= 32'd0;
