            if (wr && !locked) begin
                for (k = 0; k < 8; k = k + 1)
                    if (wr_idx == k) func_sel[k*3 +: 3] <= wr_func;
                wr_cnt <= wr_cnt + 32'd1;
                cm_cnt <= cm_cnt + 32'd1;
            end
            err <= err | (wr_cnt != cm_cnt);
            if (lock_req) begin
                locked <= 1'b1;
                pre_lock <= 1'b0;
            end
        end
    end

    genvar g;
    generate
        for (g = 0; g < 8; g = g + 1) begin : pads
            wire [2:0] fs = func_sel[g*3 +: 3];
