    reg        last_lvl;
    reg [31:0] shreg;
    reg [31:0] bits_left;
    reg [31:0] deadline;
    reg        busy;
    reg        err;
    reg        win;
    reg        pv;

    initial begin
        phase = 32'd0;
        last_lvl = 1'b0;
        shreg = 32'd0;
        bits_left = 32'd0;
        deadline = 32'd0;
        busy = 1'b0;
        err = 1'b0;
        win = 1'b0;
        pv = 1'b0;
    end

    assign mid_strobe = busy && (phase == 32'd8);
    assign done  = en && busy && !abort && (phase == 32'd15) && (bits_left == 32'd1);
    assign word  = shreg[15:0];
    assign err_o = err;

