    always @(posedge clk) begin
        if (en) begin
            if (abort) begin
                busy <= 1'b0;
                win  <= 1'b0;
            end else if (sof && !busy) begin
                busy      <= 1'b1;
                win       <= 1'b1;
                bits_left <= 32'd16;
                phase     <= 32'd0;
                deadline  <= 32'd256;
                err       <= 1'b0;
            end else if (busy) begin
                deadline <= (deadline != 32'd0) ? (deadline - 32'd1) : 32'd0;
                if (phase == 32'd15) begin
                    phase     <= 32'd0;
                    bits_left <= bits_left - 32'd1;
                    if (bits_left == 32'd1) begin
                        busy <= 1'b0;
                        win  <= 1'b0;
                    end
                end else begin
                    phase <= phase + 32'd1;
                end
                if (phase == 32'd4)
                    last_lvl <= rx;
                if (phase == 32'd12) begin
                    if (last_lvl != rx)
                        shreg <= {shreg[30:0], last_lvl};
                    else begin
                        shreg <= {shreg[30:0], 1'b0};
                        err   <= 1'b1;
                    end
                    last_lvl <= rx;
                end
            end
        end
    end

    always @(posedge clk)
        if (pv && win && $rose(mid_strobe))
            assert (deadline != 32'd0);
