    input wire clk,
    input wire rst,
    input wire en,
    input wire flush,
    input wire [63:0] din,
    output wire [63:0] o_dout,
    output wire o_tick
);
    localparam [5:0]  LAST = 6'd47;
    localparam [63:0] WIN  = 64'd48;

    reg [5:0]  phase;
    reg [63:0] acc;
    reg [63:0] dout;
    reg [63:0] in_cnt;
    reg [63:0] out_cnt;
    reg        tick;
    reg        pre_flush;
    reg        pv;

    initial begin
        phase = 6'd0;
        acc = 64'd0;
        dout = 64'd0;
        in_cnt = 64'd0;
        out_cnt = 64'd0;
        tick = 1'b0;
        pre_flush = 1'b1;
        pv = 1'b0;
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            phase <= 6'd0;
            acc <= 64'd0;
            dout <= 64'd0;
            in_cnt <= 64'd0;
            out_cnt <= 64'd0;
            tick <= 1'b0;
            pre_flush <= 1'b1;
        end else if (en) begin
            if (flush) begin
                phase <= 6'd0;
                acc <= 64'd0;
                tick <= 1'b0;
                pre_flush <= 1'b0;
