                in_cnt <= in_cnt + 64'd1;
                if (phase == LAST) begin
                    phase <= 6'd0;
                    dout <= acc + din;
                    acc <= 64'd0;
                    out_cnt <= out_cnt + 64'd1;
                    tick <= 1'b1;
                end else begin
                    phase <= phase + 6'd1;
                    acc <= acc + din;
                    tick <= 1'b0;
                end
            end
        end
    end

    assign o_dout = dout;
    assign o_tick = tick;

    always @(posedge clk)
        if (pv && !rst && pre_flush && $rose(tick))
            assert (in_cnt == WIN * out_cnt);
endmodule


