module SsiFir8 (
    input  wire        clk,
    input  wire        en,
    input  wire        load_req,
    input  wire [31:0] coef_in,
    input  wire        s_valid,
    input  wire [31:0] s_data,
    input  wire        frame_end,
    output wire [31:0] y,
    output wire        y_valid
);
    reg [31:0] tap  [0:7];
    reg [31:0] coef [0:7];
    reg [31:0] fill_cnt = 32'd0;
    reg        primed   = 1'b0;
    reg        loading  = 1'b0;
    reg [31:0] load_ptr = 32'd0;
    reg        win      = 1'b0;
    reg        pv       = 1'b0;
    integer i;

    initial begin
        for (i = 0; i < 8; i = i + 1) begin
            tap[i]  = 32'd0;
            coef[i] = 32'd0;
        end
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (en) begin
            if (load_req) begin
                loading  <= 1'b1;
                load_ptr <= 32'd0;
                fill_cnt <= 32'd0;
                primed   <= 1'b0;
            end else begin
                primed <= (fill_cnt >= 32'd8);
                if (loading) begin
                    coef[load_ptr[2:0]] <= coef_in;
                    if (load_ptr == 32'd7) begin
                        loading  <= 1'b0;
                        load_ptr <= 32'd0;
                    end else begin
                        load_ptr <= load_ptr + 32'd1;
                    end
                end else if (s_valid) begin
                    for (i = 7; i > 0; i = i - 1)
                        tap[i] <= tap[i-1];
                    tap[0]   <= s_data;
                    fill_cnt <= (fill_cnt < 32'd8) ? (fill_cnt + 32'd1) : 32'd8;
                end
            end
            if (load_req)
                win <= 1'b1;
            else if (frame_end)
                win <= 1'b0;
        end
    end

    assign y = tap[0]*coef[0] + tap[1]*coef[1] + tap[2]*coef[2] + tap[3]*coef[3]
             + tap[4]*coef[4] + tap[5]*coef[5] + tap[6]*coef[6] + tap[7]*coef[7];
    assign y_valid = primed;

    always @(posedge clk)
        if (pv && $past(win))
            assert (!($past(primed) && $past(loading)));
endmodule

