    input wire [31:0] err_syn,
    input wire [31:0] err_addr,
    input wire sw_ack
);
    localparam [1:0] IDLE = 2'd0, ARMED = 2'd1, CAPT = 2'd2, DONE = 2'd3;

    reg [1:0]  phase;
    reg [31:0] syn_q, addr_q;
    reg        type_q;
    reg [31:0] ce_cnt, ue_cnt;
    reg [31:0] log_mem [0:127];
    reg [6:0]  wp;
    reg        arm_seen, start_seen, fin_seen;

    integer i;
    initial begin
        phase = IDLE;
        syn_q = 32'd0;
        addr_q = 32'd0;
        type_q = 1'b0;
        ce_cnt = 32'd0;
        ue_cnt = 32'd0;
        wp = 7'd0;
        arm_seen = 1'b0;
        start_seen = 1'b0;
        fin_seen = 1'b0;
        for (i = 0; i < 128; i = i + 1) log_mem[i] = 32'd0;
    end

    always @(posedge clk) begin
        if (!rst_n) begin
            phase <= IDLE;
            syn_q <= 32'd0;
            addr_q <= 32'd0;
            type_q <= 1'b0;
            ce_cnt <= 32'd0;
            ue_cnt <= 32'd0;
            wp <= 7'd0;
            arm_seen <= 1'b0;
            start_seen <= 1'b0;
            fin_seen <= 1'b0;
