        input [7:0] a;
        isnan = (a[6:2] == 5'h1F) && (a[1:0] != 2'b00);
    endfunction

    function [7:0] key;
        input [7:0] a;
        key = a[7] ? ~a : (a | 8'h80);
    endfunction

    function [7:0] fmax;
        input [7:0] a;
        input [7:0] b;
        begin
            if (isnan(a) && isnan(b)) fmax = 8'h7E;
            else if (isnan(a)) fmax = b;
            else if (isnan(b)) fmax = a;
            else if (key(a) >= key(b)) fmax = a;
            else fmax = b;
        end
    endfunction

    function [7:0] fmin;
        input [7:0] a;
        input [7:0] b;
        begin
            if (isnan(a) && isnan(b)) fmin = 8'h7E;
            else if (isnan(a)) fmin = b;
            else if (isnan(b)) fmin = a;
            else if (key(a) <= key(b)) fmin = a;
            else fmin = b;
        end
    endfunction

    function fle;
        input [7:0] a;
        input [7:0] b;
        fle = !isnan(a) && !isnan(b) && (key(a) <= key(b));
    endfunction

    wire [7:0] nmax = fmax(mx, x);
    wire [7:0] nmin = fmin(mn, x);

    always @(posedge clk) begin
        if (rst) begin
            mx <= 8'hFC;
            mn <= 8'h7C;
            res <= 8'h00;
            inv <= 1'b0;
            armed <= 1'b0;
        end else if (en && valid) begin
            mx <= nmax;
            mn <= nmin;
            res <= op ? nmin : nmax;
            inv <= isnan(x) && !x[1];
            armed <= 1'b1;
        end
