module tplan_banner_gen (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire arm_req,
    input wire start_req,
    input wire abort_req,
    input wire wr_en,
    input wire [4:0] wr_addr,
    input wire [63:0] wr_data,
    output wire [7:0] o_pix,
    output wire o_done
);
    localparam [1:0] IDLE = 2'd0, ARMED = 2'd1, RUN = 2'd2, FIN = 2'd3;

    reg [63:0] char_mem [0:23];
    reg [63:0] col_cnt;
    reg [63:0] row_cnt;
    reg [63:0] frame_cnt;
    reg [1:0]  phase;
    reg        arm_seen;
    reg        start_seen;
    reg        done;
    reg        before_abort;
    reg [7:0]  pix_row;

    integer i;
    initial begin
        for (i = 0; i < 24; i = i + 1)
            char_mem[i] = 64'd32;
    end
    initial col_cnt = 64'd0;
    initial row_cnt = 64'd0;
    initial frame_cnt = 64'd0;
    initial phase = IDLE;
    initial arm_seen = 1'b0;
    initial start_seen = 1'b0;
    initial done = 1'b0;
    initial before_abort = 1'b1;
    initial pix_row = 8'h00;

    function [7:0] font_row;
        input [7:0] c;
        input [2:0] r;
        begin
            case (c)
                8'h54: font_row = (r == 3'd0) ? 8'hFE : 8'h10;
                8'h50: font_row = (r < 3'd4) ? 8'hFC : 8'h80;
                8'h41: font_row = (r == 3'd0) ? 8'h38 : ((r == 3'd4) ? 8'hFE : 8'h82);
                8'h53: font_row = (r[0]) ? 8'h80 : 8'h7C;
                8'h20: font_row = 8'h00;
                default: font_row = c ^ {r, r, r[1:0]};
            endcase
        end
    endfunction

    wire [7:0] cur_char = (col_cnt < 64'd24) ? char_mem[col_cnt[4:0]][7:0] : 8'h20;
    wire last_col = (col_cnt >= 64'd23);
    wire last_row = (row_cnt >= 64'd7);

    always @(posedge clk) begin
        if (!rst_n) begin
            col_cnt <= 64'd0;
            row_cnt <= 64'd0;
            frame_cnt <= 64'd0;
            phase <= IDLE;
            arm_seen <= 1'b0;
            start_seen <= 1'b0;
            done <= 1'b0;
            before_abort <= 1'b1;
            pix_row <= 8'h00;
        end else if (en) begin
            if (wr_en && (wr_addr < 5'd24))
                char_mem[wr_addr] <= wr_data;
            if (abort_req) begin
                phase <= IDLE;
                arm_seen <= 1'b0;
                start_seen <= 1'b0;
                done <= 1'b0;
                before_abort <= 1'b0;
            end else begin
                case (phase)
                    IDLE: begin
                        if (arm_req) begin
                            phase <= ARMED;
                            arm_seen <= 1'b1;
                            done <= 1'b0;
                        end
                    end
                    ARMED: begin
                        if (start_req) begin
                            phase <= RUN;
                            start_seen <= 1'b1;
                            col_cnt <= 64'd0;
                            row_cnt <= 64'd0;
                        end
                    end
                    RUN: begin
                        pix_row <= font_row(cur_char, row_cnt[2:0]);
                        if (last_col) begin
                            col_cnt <= 64'd0;
                            if (last_row) begin
                                row_cnt <= 64'd0;
                                phase <= FIN;
                                done <= 1'b1;
                                frame_cnt <= frame_cnt + 64'd1;
                            end else begin
                                row_cnt <= row_cnt + 64'd1;
                            end
                        end else begin
                            col_cnt <= col_cnt + 64'd1;
                        end
                    end
                    FIN: begin
                        if (arm_req) begin
                            phase <= ARMED;
                            arm_seen <= 1'b1;
                            done <= 1'b0;
                        end
                    end
                endcase
            end
        end
    end

    assign o_pix = pix_row;
    assign o_done = done;

    always @(posedge clk)
        if (before_abort && done)
            assert (arm_seen && start_seen);
endmodule

