module huff_decoder64 (
    input wire clk,
    input wire rst,
    input wire start,
    input wire step,
    input wire wr_en,
    input wire wr_idx,
    input wire [63:0] bits_in,
    input wire [63:0] wr_code,
    input wire [63:0] wr_len,
    output wire busy,
    output wire [63:0] o_sym,
    output wire [63:0] o_nsym
);
    localparam [63:0] MAXLEN = 64'd8;

    // decode window / request outstanding
    reg win = 1'b0;
    // bit accumulator, consumed-code shift register, bit position, completion countdown
    reg [63:0] acc = 64'd0;
    reg [63:0] code_acc = 64'd0;
    reg [63:0] bitpos = 64'd0;
    reg [63:0] cnt = 64'd0;
    reg [63:0] sym = 64'd0;
    reg [63:0] nsym = 64'd0;
    // two-entry code table (code word + length)
    reg [63:0] code0 = 64'd0;
    reg [63:0] len0 = 64'd1;
    reg [63:0] code1 = 64'd2;
    reg [63:0] len1 = 64'd2;

    wire [63:0] nbits = bitpos + 64'd1;
    wire [63:0] ncode = {code_acc[62:0], acc[63]};
    wire hit0 = (nbits == len0) && (ncode == code0);
    wire hit1 = (nbits == len1) && (ncode == code1);
    wire esc  = (nbits == MAXLEN);

    always @(posedge clk) begin
        if (rst) begin
            win <= 1'b0;
            acc <= 64'd0;
            code_acc <= 64'd0;
            bitpos <= 64'd0;
            cnt <= 64'd0;
            nsym <= 64'd0;
        end else begin
            if (wr_en) begin
                if (wr_idx) begin
                    code1 <= wr_code;
                    len1 <= wr_len;
                end else begin
                    code0 <= wr_code;
                    len0 <= wr_len;
                end
            end
            if (win) begin
                if (step) begin
                    acc <= acc << 1;
                    code_acc <= ncode;
                    bitpos <= nbits;
                    cnt <= cnt - 64'd1;
                    if (hit0 || hit1 || esc) begin
                        win <= 1'b0;
                        nsym <= nsym + 64'd1;
                        sym <= hit0 ? 64'd0 : (hit1 ? 64'd1 : 64'd2);
                    end
                end
            end else if (start) begin
                win <= 1'b1;
                acc <= bits_in;
                code_acc <= 64'd0;
                bitpos <= 64'd0;
                cnt <= MAXLEN;
            end
        end
    end

    assign busy = win;
    assign o_sym = sym;
    assign o_nsym = nsym;

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && $past(win))
            assert ($past(cnt) != 64'd0);
endmodule


