module lpm_engine (
    input  wire        clk,
    input  wire        insert,
    input  wire        flush,
    input  wire [63:0] ins_prefix,
    input  wire [6:0]  ins_len,
    input  wire [63:0] key,
    output reg         hit,
    output reg  [4:0]  match_addr,
    output reg  [6:0]  match_len,
    output wire [63:0] o_count
);
    reg [63:0] prefix_mem [0:31];
    reg [6:0]  len_mem    [0:31];
    reg [31:0] valid;
    reg [5:0]  wr_ptr;
    reg [63:0] count;
    reg        armed;

    integer k;
    initial begin
        valid  = 32'd0;
        wr_ptr = 6'd0;
        count  = 64'd0;
        armed  = 1'b1;
        for (k = 0; k < 32; k = k + 1) begin
            prefix_mem[k] = 64'd0;
            len_mem[k]    = 7'd0;
        end
    end

    function [63:0] pmask;
        input [6:0] l;
        begin
            if (l >= 7'd64) pmask = ~64'd0;
            else            pmask = ~(~64'd0 >> l);
        end
    endfunction

    wire [6:0] ins_len_sat = (ins_len > 7'd64) ? 7'd64 : ins_len;

    always @(posedge clk) begin
        if (flush) begin
            valid  <= 32'd0;
            wr_ptr <= 6'd0;
            armed  <= 1'b0;
        end else if (insert && wr_ptr < 6'd32) begin
            prefix_mem[wr_ptr[4:0]] <= ins_prefix & pmask(ins_len_sat);
            len_mem[wr_ptr[4:0]]    <= ins_len_sat;
            valid[wr_ptr[4:0]]      <= 1'b1;
            wr_ptr <= wr_ptr + 6'd1;
            count  <= count + 64'd1;
        end
    end

    integer i;
    always @(*) begin
        hit        = 1'b0;
        match_addr = 5'd0;
        match_len  = 7'd0;
        for (i = 0; i < 32; i = i + 1) begin
            if (valid[i] && (((key ^ prefix_mem[i]) & pmask(len_mem[i])) == 64'd0)
                && (!hit || len_mem[i] > match_len)) begin
                hit        = 1'b1;
                match_addr = i[4:0];
                match_len  = len_mem[i];
            end
        end
    end

    assign o_count = count;

    always @(*)
        if (armed)
            assert (count <= 64'd32);
endmodule


