        if (rst) begin
            integ1 <= 128'd0;
            integ2 <= 128'd0;
            comb1_dly <= 128'd0;
            comb2_dly <= 128'd0;
            dout <= 128'd0;
            phase <= 2'd0;
            seen_nz <= 1'b0;
            vld <= 1'b0;
