            integ1 <= integ1 + din;
            integ2 <= integ2 + integ1;
            phase <= phase + 2'd1;
            if (din != 128'd0)
                seen_nz <= 1'b1;
            if (phase == 2'd3) begin
                comb1_dly <= integ2;
                comb2_dly <= c1;
                dout <= c2;
                vld <= 1'b1;
            end else begin
                vld <= 1'b0;
            end
        end
    end

