module const_slicer (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire       req,
    input  wire       cfg_we,
    input  wire [1:0] cfg_order,
    input  wire [7:0] in_i,
    input  wire [7:0] in_q,
    output reg  [3:0] dec_bits,
    output reg  [7:0] err_i,
    output reg  [7:0] err_q,
    output reg        done,
    output wire       busy_o
);
    reg [1:0] mod_order;
    reg [7:0] sym_i, sym_q;
    reg       busy;
    reg [7:0] cd;
    reg [7:0] phase;
    reg       pre_cfg;
    reg       pv;

    initial begin
        mod_order = 2'd1; sym_i = 8'd0; sym_q = 8'd0;
        busy = 1'b0; cd = 8'd0; phase = 8'd0;
        dec_bits = 4'd0; err_i = 8'd0; err_q = 8'd0; done = 1'b0;
        pre_cfg = 1'b1; pv = 1'b0;
    end

    assign busy_o = busy;

    wire si = sym_i[7];
    wire sq = sym_q[7];
    wire mi = sym_i[7] ^ sym_i[6];
    wire mq = sym_q[7] ^ sym_q[6];
    wire qam = mod_order[1];

    wire [7:0] qam_pt_i = si ? (mi ? 8'hA0 : 8'hE0) : (mi ? 8'h60 : 8'h20);
    wire [7:0] qam_pt_q = sq ? (mq ? 8'hA0 : 8'hE0) : (mq ? 8'h60 : 8'h20);
    wire [7:0] psk_pt_i = si ? 8'hC0 : 8'h40;
    wire [7:0] psk_pt_q = sq ? 8'hC0 : 8'h40;

    wire [7:0] pt_i = qam ? qam_pt_i : psk_pt_i;
    wire [7:0] pt_q = qam ? qam_pt_q : ((mod_order == 2'd0) ? 8'h00 : psk_pt_q);
    wire [3:0] bits = qam ? {mq, sq, mi, si}
                    : ((mod_order == 2'd0) ? {3'b000, si} : {2'b00, sq, si});

    always @(posedge clk) begin
        if (rst) begin
            busy  <= 1'b0;
            cd    <= 8'd0;
            phase <= 8'd0;
            done  <= 1'b0;
        end else if (ce) begin
            done <= 1'b0;
            if (cfg_we && !busy)
                mod_order <= cfg_order;
            if (!busy) begin
                if (req) begin
                    sym_i <= in_i;
                    sym_q <= in_q;
                    busy  <= 1'b1;
                    cd    <= 8'd4;
                    phase <= 8'd0;
                end
            end else begin
                cd <= cd - 8'd1;
                if (phase == 8'd3) begin
                    busy     <= 1'b0;
                    phase    <= 8'd0;
                    dec_bits <= bits;
                    err_i    <= sym_i - pt_i;
                    err_q    <= sym_q - pt_q;
                    done     <= 1'b1;
                end else begin
                    phase <= phase + 8'd1;
                end
            end
        end
    end

    always @(posedge clk)
        if (!rst && ce && cfg_we && !busy)
            pre_cfg <= 1'b0;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && pre_cfg && $past(busy))
            assert ($past(cd) != 8'd0);
endmodule

