module razor_shadow_stage (
    input  wire        clk,
    input  wire        rst,
    input  wire        ce,
    input  wire [63:0] d_main,
    input  wire [63:0] d_late,
    output reg  [63:0] main_q,
    output reg  [63:0] shadow_q,
    output reg  [63:0] err_cnt,
    output reg         razor_err
);
    localparam [1:0] IDLE    = 2'd0;
    localparam [1:0] ARMED   = 2'd1;
    localparam [1:0] STARTED = 2'd2;
    localparam [1:0] DONE    = 2'd3;

    reg [1:0] phase = IDLE;
    reg armed = 1'b0;
    reg started = 1'b0;
    reg finished = 1'b0;

    initial begin
        main_q    = 64'd0;
        shadow_q  = 64'd0;
        err_cnt   = 64'd0;
        razor_err = 1'b0;
    end

    always @(posedge clk) begin
        if (rst) begin
            phase     <= IDLE;
            armed     <= 1'b0;
            started   <= 1'b0;
            finished  <= 1'b0;
            main_q    <= 64'd0;
            shadow_q  <= 64'd0;
            err_cnt   <= 64'd0;
            razor_err <= 1'b0;
        end else if (ce) begin
            case (phase)
                IDLE: begin
                    main_q   <= d_main;
                    armed    <= 1'b1;
                    started  <= 1'b0;
                    finished <= 1'b0;
                    phase    <= ARMED;
                end
                ARMED: begin
                    shadow_q <= d_late;
                    started  <= 1'b1;
                    phase    <= STARTED;
                end
                STARTED: begin
                    razor_err <= (main_q != shadow_q);
                    if (main_q != shadow_q) begin
                        main_q  <= shadow_q;
                        err_cnt <= err_cnt + 64'd1;
                    end
                    finished <= 1'b1;
                    phase    <= DONE;
                end
                default: begin
                    armed    <= 1'b0;
                    started  <= 1'b0;
                    finished <= 1'b0;
                    phase    <= IDLE;
                end
            endcase
        end
    end

    always @(posedge clk)
        if (finished) assert (started && armed);
endmodule

