    input  wire        ce,
    input  wire        start,
    input  wire        op_rd,
    input  wire [4:0]  phy_ad,
    input  wire [4:0]  reg_ad,
    input  wire [15:0] wr_data,
    input  wire        mdio_i,
    output wire        mdio_o,
    output wire        mdio_oe,
    output wire        busy,
    output wire [63:0] o_rd_data
