                if (cfg_we)
                    cfg_opcode <= cfg_wdata;
                if (req) begin
                    armed     <= 1'b1;
                    busy      <= 1'b1;
                    cs_active <= 1'b1;
                    cnt       <= 32'd20;
                    nib       <= 32'd0;
                    pf_valid  <= 1'b0;
                    sh_out    <= {cfg_opcode, addr};
                end
            end else begin
                cnt    <= cnt - 32'd1;
                sh_out <= {sh_out[27:0], 4'h0};
