                chain[0] <= sample;
                for (i = 1; i < 48; i = i + 1) chain[i] <= chain[i-1];
                valid <= {valid[46:0], 1'b1};
                if (count != DEPTH) count <= count + 64'd1;
            end
        end
    end

    assign rd_data   = (rd_idx < 6'd48) ? chain[rd_idx] : 64'd0;
    assign is_frozen = frozen;
    assign captured  = count;

    always @(posedge clk)
        if (pv && $rose(frozen))
            assert (valid == 48'hFFFFFFFFFFFF);
