    reg [63:0] residue;
    reg        win;
    reg [63:0] in_cnt;
    reg [63:0] out_cnt;

    initial begin
        off = 3'd0; residue = 64'd0; win = 1'b0;
        in_cnt = 64'd0; out_cnt = 64'd0;
        out_data = 64'd0; out_tail = 64'd0;
        out_valid = 1'b0; tail_valid = 1'b0;
    end

    wire [5:0]  sh     = {off, 3'b000};
    wire [5:0]  sop_sh = {sop_off, 3'b000};
    wire [6:0]  lsh    = 7'd64 - {1'b0, sh};
    wire [63:0] merged = residue | (in_data << lsh);

    always @(posedge clk) begin
        if (rst) begin
            off <= 3'd0; residue <= 64'd0; win <= 1'b0;
            in_cnt <= 64'd0; out_cnt <= 64'd0;
            out_data <= 64'd0; out_tail <= 64'd0;
            out_valid <= 1'b0; tail_valid <= 1'b0;
