            out_valid  <= 1'b0;
            tail_valid <= 1'b0;
            if (!win) begin
                if (sop) begin
                    off     <= sop_off;
                    residue <= in_data >> sop_sh;
                    win     <= 1'b1;
                    in_cnt  <= in_cnt + 64'd1;
                end
            end else begin
                out_data  <= merged;
                out_valid <= 1'b1;
                in_cnt    <= in_cnt + 64'd1;
                if (eop) begin
                    out_tail   <= in_data >> sh;
                    tail_valid <= 1'b1;
                    out_cnt    <= out_cnt + 64'd2;
                    residue    <= 64'd0;
                    win        <= 1'b0;
                end else begin
                    residue <= in_data >> sh;
