module fp_align_shifter (
    input  wire        clk,
    input  wire        rst,
    input  wire        load,
    input  wire        i_ce,
    input  wire [63:0] a_exp,
    input  wire [63:0] a_sig,
    input  wire [63:0] b_exp,
    input  wire [63:0] b_sig,
    output reg  [63:0] sig,
    output reg  [63:0] exp_out,
    output reg  [63:0] cnt,
    output reg         g,
    output reg         r,
    output reg         s,
    output wire        busy
);
    // shadow: some nonzero bit has been shifted out of the significand
    reg lost  = 1'b0;
    // sticky scope register: set at the first accepted alignment request
    reg armed = 1'b0;

    initial sig     = 64'd0;
    initial exp_out = 64'd0;
    initial cnt     = 64'd0;
    initial g       = 1'b0;
    initial r       = 1'b0;
    initial s       = 1'b0;

    assign busy = (cnt != 64'd0);

    always @(posedge clk) begin
        if (rst) begin
            sig     <= 64'd0;
            exp_out <= 64'd0;
            cnt     <= 64'd0;
            g       <= 1'b0;
            r       <= 1'b0;
            s       <= 1'b0;
            lost    <= 1'b0;
        end else if (load) begin
            armed <= 1'b1;
            if (a_exp >= b_exp) begin
                exp_out <= a_exp;
                sig     <= b_sig;
                cnt     <= a_exp - b_exp;
            end else begin
                exp_out <= b_exp;
                sig     <= a_sig;
                cnt     <= b_exp - a_exp;
            end
            g    <= 1'b0;
            r    <= 1'b0;
            s    <= 1'b0;
            lost <= 1'b0;
        end else if (i_ce && cnt != 64'd0) begin
            sig  <= {1'b0, sig[63:1]};
            g    <= sig[0];
            r    <= g;
            s    <= s | r;
            lost <= lost | sig[0];
            cnt  <= cnt - 64'd1;
        end
    end

    // precedence, after first load: sticky set now => a nonzero bit was shifted out earlier
    always @(*) assert (!armed || !s || lost);
