module dadda4x4 (
    input  wire [3:0] a,
    input  wire [3:0] b,
    output wire [7:0] p
);
    // partial products pij = a[i] & b[j], weight i+j
    wire p00 = a[0] & b[0];
    wire p01 = a[0] & b[1];
    wire p02 = a[0] & b[2];
    wire p03 = a[0] & b[3];
    wire p10 = a[1] & b[0];
    wire p11 = a[1] & b[1];
    wire p12 = a[1] & b[2];
    wire p13 = a[1] & b[3];
    wire p20 = a[2] & b[0];
    wire p21 = a[2] & b[1];
    wire p22 = a[2] & b[2];
    wire p23 = a[2] & b[3];
    wire p30 = a[3] & b[0];
    wire p31 = a[3] & b[1];
    wire p32 = a[3] & b[2];
    wire p33 = a[3] & b[3];
    // Dadda stage 1: reduce max column height 4 -> 3 (two half adders)
    wire s1 = p03 ^ p12;
    wire c1 = p03 & p12;
    wire s2 = p13 ^ p22;
    wire c2 = p13 & p22;
    // Dadda stage 2: reduce height 3 -> 2 (one half adder, three full adders)
    wire s3 = p02 ^ p11;
    wire c3 = p02 & p11;
    wire s4 = s1 ^ p21 ^ p30;
    wire c4 = (s1 & p21) | (s1 & p30) | (p21 & p30);
    wire s5 = s2 ^ p31 ^ c1;
    wire c5 = (s2 & p31) | (s2 & c1) | (p31 & c1);
    wire s6 = p23 ^ p32 ^ c2;
    wire c6 = (p23 & p32) | (p23 & c2) | (p32 & c2);
    // final carry-propagate adder over columns 1..6
    wire [5:0] row_x = {p33, s6, s5, s4, s3, p01};
    wire [5:0] row_y = {c6, c5, c4, c3, p20, p10};
    wire [6:0] cpa = {1'b0, row_x} + {1'b0, row_y};
    assign p = {cpa, p00};
endmodule

module dadda_simd_mul (
    input  wire         clk,
    input  wire         i_ce,
    input  wire         i_load,
    input  wire         i_flush,
    input  wire [127:0] i_data,
    output wire [127:0] o_prod
);
    reg [127:0] op_r;
    reg [127:0] prod_r;
    reg         v1;
    reg [1:0]   op_gen;
    reg [1:0]   p_gen;
    reg         armed;
    reg         pv;
    initial op_r   = 128'h0;
    initial prod_r = 128'h0;
    initial v1     = 1'b0;
    initial op_gen = 2'd0;
    initial p_gen  = 2'd0;
    initial armed  = 1'b0;
    initial pv     = 1'b0;

    // 16 lanes, each lane packs {a[3:0], b[3:0]} in 8 bits of the operand word
    wire [127:0] tree_p;
    genvar k;
    generate
        for (k = 0; k < 16; k = k + 1) begin : lane
            dadda4x4 u_mul (
                .a(op_r[8*k+7:8*k+4]),
                .b(op_r[8*k+3:8*k]),
                .p(tree_p[8*k+7:8*k])
            );
        end
    endgenerate

    always @(posedge clk) begin
        if (i_ce) begin
            if (v1) begin
                prod_r <= tree_p;
                p_gen  <= op_gen;
            end
            if (i_load) begin
                op_r   <= i_data;
                op_gen <= op_gen + 2'd1;
                v1     <= 1'b1;
            end else if (v1) begin
                v1 <= 1'b0;
            end
            if (i_flush)
                armed <= 1'b0;
            else if (i_load)
                armed <= 1'b1;
        end
    end

    assign o_prod = prod_r;

    always @(posedge clk) pv <= 1'b1;

    // after first load until flush: never (product tag unchanged AND product changed)
    always @(posedge clk)
        if (pv && armed && $stable(p_gen))
            assert ($stable(prod_r));
endmodule

