module mesi_pair (
    input wire clk,
    input wire rst,
    input wire step,
    input wire who,
    input wire wr,
    output reg [1:0] st_a,
    output reg [1:0] st_b,
    output reg bus_req,
    output reg [31:0] bus_cnt,
    output reg [31:0] wb_cnt
);
    localparam [1:0] ST_I = 2'b00;
    localparam [1:0] ST_S = 2'b01;
    localparam [1:0] ST_E = 2'b10;
    localparam [1:0] ST_M = 2'b11;

    initial st_a = ST_I;
    initial st_b = ST_I;
    initial bus_req = 1'b0;
    initial bus_cnt = 32'd0;
    initial wb_cnt = 32'd0;

    always @(posedge clk) begin
        if (rst) begin
            st_a <= ST_I;
            st_b <= ST_I;
            bus_req <= 1'b0;
            bus_cnt <= 32'd0;
            wb_cnt <= 32'd0;
        end else if (step) begin
            bus_req <= 1'b0;
            if (!who) begin
                if (wr) begin
                    if (st_a == ST_E) begin
                        st_a <= ST_M;
                    end else if (st_a != ST_M) begin
                        st_a <= ST_M;
                        if (st_b == ST_M) wb_cnt <= wb_cnt + 32'd1;
                        st_b <= ST_I;
                        bus_req <= 1'b1;
                        bus_cnt <= bus_cnt + 32'd1;
                    end
                end else if (st_a == ST_I) begin
                    bus_req <= 1'b1;
                    bus_cnt <= bus_cnt + 32'd1;
                    if (st_b == ST_I) begin
                        st_a <= ST_E;
                    end else begin
                        st_a <= ST_S;
                        if (st_b == ST_M) wb_cnt <= wb_cnt + 32'd1;
                        st_b <= ST_S;
                    end
                end
            end else begin
                if (wr) begin
                    if (st_b == ST_E) begin
                        st_b <= ST_M;
                    end else if (st_b != ST_M) begin
                        st_b <= ST_M;
                        if (st_a == ST_M) wb_cnt <= wb_cnt + 32'd1;
                        st_a <= ST_I;
                        bus_req <= 1'b1;
                        bus_cnt <= bus_cnt + 32'd1;
                    end
                end else if (st_b == ST_I) begin
                    bus_req <= 1'b1;
                    bus_cnt <= bus_cnt + 32'd1;
                    if (st_a == ST_I) begin
                        st_b <= ST_E;
                    end else begin
                        st_b <= ST_S;
                        if (st_a == ST_M) wb_cnt <= wb_cnt + 32'd1;
                        st_a <= ST_S;
                    end
                end
            end
        end
    end

    always @(posedge clk)
        assert (!(st_a == ST_M && st_b == ST_M));
