module xs3_cell_seq (
    input  wire         clk,
    input  wire         rst,
    input  wire         step,
    input  wire         arm,
    input  wire         go,
    input  wire         clr,
    input  wire [127:0] a_in,
    input  wire [127:0] b_in,
    output reg  [127:0] result,
    output reg          carry_out
);
    reg [127:0] opa;
    reg [127:0] opb;
    reg [1:0]   phase;
    reg         armed_seen;
    reg         start_seen;
    reg         done;

    initial begin
        opa = 128'd0; opb = 128'd0; result = 128'd0; carry_out = 1'b0;
        phase = 2'd0; armed_seen = 1'b0; start_seen = 1'b0; done = 1'b0;
    end

    // Combinational excess-3 adder: 32 digits, binary add then +3/-3 correction
    wire [32:0]  c;
    wire [127:0] xs3_sum;
    assign c[0] = 1'b0;
    genvar i;
    generate
        for (i = 0; i < 32; i = i + 1) begin : g_dig
            wire [4:0] raw = {1'b0, opa[4*i +: 4]} + {1'b0, opb[4*i +: 4]} + {4'd0, c[i]};
            assign c[i+1] = raw[4];
            assign xs3_sum[4*i +: 4] = raw[4] ? (raw[3:0] + 4'd3) : (raw[3:0] - 4'd3);
        end
    endgenerate

    always @(posedge clk) begin
        if (rst) begin
            phase <= 2'd0; armed_seen <= 1'b0; start_seen <= 1'b0; done <= 1'b0;
        end else if (step) begin
            case (phase)
                2'd0: if (arm) begin
                    opa <= a_in;
                    armed_seen <= 1'b1;
                    phase <= 2'd1;
                end
                2'd1: if (go) begin
                    opb <= b_in;
                    start_seen <= 1'b1;
                    phase <= 2'd2;
                end
                2'd2: begin
                    result <= xs3_sum;
                    carry_out <= c[32];
                    done <= 1'b1;
                    phase <= 2'd3;
                end
                default: if (clr) begin
                    armed_seen <= 1'b0;
                    start_seen <= 1'b0;
                    done <= 1'b0;
                    phase <= 2'd0;
                end
            endcase
        end
    end

    always @(posedge clk)
        if (done)
            assert (start_seen && armed_seen);
endmodule

