module wstrobe_demux_bank (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_we,
    input  wire [4:0]  i_addr,
    input  wire [63:0] i_data,
    input  wire        i_ce,
    output wire [31:0] o_strobe,
    output wire        o_busy,
    output wire [63:0] o_num_valid
);
    reg        pending;
    reg [4:0]  addr_q;
    reg [63:0] data_q;
    reg [31:0] valid;
    reg [63:0] num_valid;
    reg        armed;
    reg [63:0] bank [0:31];
    integer i;
    initial begin
        pending = 1'b0;
        addr_q = 5'd0;
        data_q = 64'd0;
        valid = 32'd0;
        num_valid = 64'd0;
        armed = 1'b0;
        for (i = 0; i < 32; i = i + 1) bank[i] = 64'd0;
    end

    wire fire = pending && i_ce;
    wire [31:0] strobe = fire ? (32'd1 << addr_q) : 32'd0;
    wire newly_valid = |(strobe & ~valid);

    reg [63:0] valid_pop;
    integer k;
    always @(*) begin
        valid_pop = 64'd0;
        for (k = 0; k < 32; k = k + 1)
            valid_pop = valid_pop + {63'd0, valid[k]};
    end

    always @(posedge clk) begin
        if (rst) begin
            pending <= 1'b0;
            valid <= 32'd0;
            num_valid <= 64'd0;
        end else begin
            if (fire) begin
                pending <= 1'b0;
                valid <= valid | strobe;
                if (newly_valid)
                    num_valid <= num_valid + 64'd1;
                armed <= 1'b1;
            end else if (i_we && !pending) begin
                pending <= 1'b1;
                addr_q <= i_addr;
                data_q <= i_data;
            end
        end
    end

    always @(posedge clk) begin
        for (i = 0; i < 32; i = i + 1)
            if (!rst && strobe[i]) bank[i] <= data_q;
    end

    assign o_strobe = strobe;
    assign o_busy = pending;
    assign o_num_valid = num_valid;

    assert property (!armed || (num_valid <= 64'd32));
endmodule


