    reg [31:0] key = 32'd0;
    reg [31:0] v = 32'd0;
    reg [31:0] timer = 32'd0;
    reg [31:0] rnd = 32'd0;
    reg [1:0] op = 2'b00;
    initial busy = 1'b0;
    initial out_data = 32'd0;
    initial reseed_ctr = 32'd0;

    always @(posedge clk) begin
        if (rst) begin
            key <= 32'd0;
            v <= 32'd0;
            timer <= 32'd0;
            rnd <= 32'd0;
            op <= 2'b00;
            busy <= 1'b0;
            out_data <= 32'd0;
            reseed_ctr <= 32'd0;
        end else if (ce) begin
            if (!busy) begin
                if (cmd != 2'b00) begin
                    busy <= 1'b1;
                    op <= cmd;
                    rnd <= 32'd0;
                    timer <= 32'd8;
                end
            end else begin
                v <= v + 32'd1;
                key <= {key[26:0], key[31:27]} ^ (v + 32'h9E3779B9) ^ ((op != 2'b11) ? entropy : 32'd0);
                rnd <= rnd + 32'd1;
                timer <= timer - 32'd1;
                if (rnd == 32'd5) begin
                    busy <= 1'b0;
                    timer <= 32'd0;
                    rnd <= 32'd0;
                    case (op)
                        2'b01: reseed_ctr <= 32'd1;
                        2'b10: reseed_ctr <= 32'd1;
                        2'b11: begin
                            reseed_ctr <= reseed_ctr + 32'd1;
                            out_data <= v ^ key;
                        end
                        default: reseed_ctr <= reseed_ctr;
                    endcase
                end
            end
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && $past(busy)) assert ($past(timer) != 32'd0);
