module bypass_xact_reg (
    input  wire        clk,
    input  wire        ce,
    input  wire        arm,
    input  wire        start,
    input  wire        finish,
    input  wire        open_w,
    input  wire        close_w,
    input  wire [31:0] din,
    output wire [31:0] dout,
    output wire        bypass_en
);
    // phase: 0 idle, 1 armed (word captured), 2 started (bypass engaged), 3 finished
    reg [1:0]  phase;
    reg        arm_seen;
    reg        start_seen;
    reg        win;
    reg [31:0] stored;
    reg [31:0] xact_cnt;
    reg        pv;

    initial begin
        phase = 2'd0;
        arm_seen = 1'b0;
        start_seen = 1'b0;
        win = 1'b0;
        stored = 32'd0;
        xact_cnt = 32'd0;
        pv = 1'b0;
    end

    // bypass multiplexer: steer input straight through while started,
    // the stored copy is left untouched
    assign bypass_en = (phase == 2'd2);
    assign dout = bypass_en ? din : stored;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (ce) begin
            if (open_w)       win <= 1'b1;
            else if (close_w) win <= 1'b0;

            case (phase)
                2'd0: if (arm) begin
                    phase    <= 2'd1;
                    arm_seen <= 1'b1;
                    stored   <= din;
                end
                2'd1: if (start) begin
                    phase      <= 2'd2;
                    start_seen <= 1'b1;
                end
                2'd2: if (finish) begin
                    phase    <= 2'd3;
                    xact_cnt <= xact_cnt + 32'd1;
                end
                default: begin
                    phase      <= 2'd0;
                    arm_seen   <= 1'b0;
                    start_seen <= 1'b0;
                end
            endcase
        end
    end

    // chain precedence inside the window: a finish is only observed if
    // arm and start had both happened in the previous cycle's record
    always @(posedge clk)
        if (pv && win && phase == 2'd3)
            assert ($past(start_seen) && $past(arm_seen));
endmodule

