{"cti_reasoning":"In S, valid = 32'h7FFFFFFF (31 entries occupied) and occ = 32. P holds because valid is nonzero and 32 <= 32. R is violated because valid_cnt = 31 differs from occ = 32. With en low the design holds S for any number of cycles. One step with en=1, alloc=1 and issue=0 then allocates the last free entry (full is still 0): valid becomes all ones and occ becomes 33, so P fails.","cti_state":[{"signal":"valid","value":"32'h7FFFFFFF"},{"signal":"occ","value":"64'd32"},{"signal":"valid_cnt","value":"64'd31"},{"signal":"dep_flat","value":"1024'd0"},{"signal":"dep_or","value":"32'h00000000"},{"signal":"pend","value":"32'h00000000"},{"signal":"wake_cnt","value":"64'd0"}],"invariants":["occ == valid_cnt","pend == dep_or","(dep_or & ~valid) == 32'd0"],"verilog":"module pico_wakeup (
    input wire        clk,
    input wire        rst_n,
    input wire        en,
    input wire        alloc,
    input wire [31:0] alloc_deps,
    input wire        issue,
    input wire [4:0]  issue_idx
);
    reg [31:0]   valid    = 32'd0;
    reg [1023:0] dep_flat = 1024'd0;
    reg [31:0]   pend     = 32'd0;
    reg [63:0]   occ      = 64'd0;
    reg [63:0]   wake_cnt = 64'd0;

    initial valid    = 32'd0;
    initial dep_flat = 1024'd0;
    initial pend     = 32'd0;
    initial occ      = 64'd0;
    initial wake_cnt = 64'd0;

    wire full = &valid;

    // lowest free index
    reg [4:0] free_idx;
    integer a;
    always @(*) begin
        free_idx = 5'd0;
        for (a = 31; a >= 0; a = a - 1)
            if (!valid[a]) free_idx = a[4:0];
    end

    // popcount of valid (status helper)
    reg [63:0] valid_cnt;
    integer b;
    always @(*) begin
        valid_cnt = 64'd0;
        for (b = 0; b < 32; b = b + 1)
            valid_cnt = valid_cnt + {63'd0, valid[b]};
    end

    // per-row OR of dependency matrix (status helper)
    reg [31:0] dep_or;
    integer c;
    always @(*) begin
        for (c = 0; c < 32; c = c + 1)
            dep_or[c] = |dep_flat[c*32 +: 32];
    end

    wire alloc_fire = alloc && !full;
    wire issue_fire = issue && valid[issue_idx] && !pend[issue_idx];
    wire [31:0] clr_mask   = issue_fire ? (32'd1 << issue_idx) : 32'd0;
    wire [31:0] alloc_mask = alloc_fire ? (32'd1 << free_idx)  : 32'd0;
    wire [31:0] new_deps   = alloc_deps & valid & ~clr_mask;

    reg [1023:0] dep_nxt;
    reg [31:0]   pend_nxt;
    reg [63:0]   woke;
    integer k;
    always @(*) begin
        woke = 64'd0;
        dep_nxt = dep_flat;
        pend_nxt = pend;
        for (k = 0; k < 32; k = k + 1) begin
            if (alloc_mask[k]) begin
                dep_nxt[k*32 +: 32] = new_deps;
                pend_nxt[k] = |new_deps;
            end else if (clr_mask[k]) begin
                dep_nxt[k*32 +: 32] = 32'd0;
                pend_nxt[k] = 1'b0;
            end else begin
                dep_nxt[k*32 +: 32] = dep_flat[k*32 +: 32] & ~clr_mask;
                pend_nxt[k] = pend[k] && (|(dep_flat[k*32 +: 32] & ~clr_mask));
                if (pend[k] && !pend_nxt[k])
                    woke = woke + 64'd1;
            end
        end
    end

    wire [31:0] valid_nxt = (valid | alloc_mask) & ~clr_mask;

    always @(posedge clk) begin
        if (!rst_n) begin
            valid    <= 32'd0;
            dep_flat <= 1024'd0;
            pend     <= 32'd0;
            occ      <= 64'd0;
            wake_cnt <= 64'd0;
        end else if (en) begin
            valid    <= valid_nxt;
            dep_flat <= dep_nxt;
            pend     <= pend_nxt;
            wake_cnt <= wake_cnt + woke;
            if (alloc_fire && !issue_fire)
                occ <= occ + 64'd1;
            else if (issue_fire && !alloc_fire)
                occ <= occ - 64'd1;
        end
    end

    always @(posedge clk)
        if (|valid) assert (occ <= 64'd32);
endmodule","top_module":"pico_wakeup","clock":"clk","antecedents":["|valid"],"sanity_covers":["occ == 64'd2","valid == 32'h00000003"]}

{"cti_reasoning":"With lt_r=1, eq_r=1, gt_r=0, gt_q=0 the flags are not one-hot, so R is violated. P holds because its guard gt_r && !gt_q is false, and with en=0 the design sits in this state for any number of cycles. One step with en=1, load=0 takes the eq branch: gt_r becomes 1, eq_r becomes 0 and gt_q stays 0, but lt_r stays 1, so the guard fires while lt_r=1 and P fails.","cti_state":[{"signal":"mode_r","value":"1'b0"},{"signal":"cnt_r","value":"8'd3"},{"signal":"len_r","value":"8'd5"},{"signal":"lt_r","value":"1'b1"},{"signal":"eq_r","value":"1'b1"},{"signal":"gt_r","value":"1'b0"},{"signal":"gt_q","value":"1'b0"}],"invariants":["(lt_r && !eq_r && !gt_r) || (!lt_r && eq_r && !gt_r) || (!lt_r && !eq_r && gt_r)","!lt_r || cur_lt","!eq_r || cur_eq","!gt_r || !cur_lt"],"verilog":"module arrow_bound_cmp (
