                        sync      <= 1'b1;
                        match_run <= 64'd0;
                    end else begin
                        match_run <= match_run + 64'd1;
                    end
                end else begin
                    match_run <= 64'd0;
                end
            end else begin
                // locked: free-run the local reference
                ref_sr    <= {ref_sr[62:0], pred};
                match_run <= 64'd0;
                if (mism) begin
                    if (lose) begin
                        sync    <= 1'b0;
                        bad_run <= 64'd0;
                    end else begin
                        bad_run <= bad_run + 64'd1;
                    end
                end else begin
                    bad_run <= 64'd0;
                end
            end
            // measurement window: opened by arm while locked, closed by disarm or sync loss
