                    r7 <= a7[2:0];
                    acc <= a35[7:0];
                    armed <= 1'b1;
                end
                OP_ADD: begin
                    r5 <= n5_add[2:0];
                    r7 <= n7_add[2:0];
                    acc <= nb_add[7:0];
