            wire PP = p3 & p2 & p1 & p0;
            assign gcarry[j+1] = GG | (PP & c0);
        end
    endgenerate
    assign cla_next = cp ^ cc;

    always @(posedge clk) begin
        pv <= 1'b1;
        if (en) begin
            rca_sum <= rca_next;
            cla_sum <= cla_next;
            armed   <= armed | therm[63];
        end
