        input [11:0] s;
        reg [11:0] s2;
        reg found;
        integer j;
        begin
            golay_err = 24'h000000;
            found = 1'b0;
            if (wt12(s) <= 4'd3) begin
                golay_err = {12'h000, s};
                found = 1'b1;
            end
