            dn  <= 32'd255;
            win <= 1'b0;
            y   <= 32'd0;
        end else if (en) begin
            if (dn == 32'd0) begin
                idx <= 32'd0;
                dn  <= 32'd255;
            end else begin
                idx <= idx + 32'd1;
                dn  <= dn - 32'd1;
