                RUN: begin
                    res   <= {fbit, res[7:1]};
                    opa   <= {1'b0, opa[7:1]};
                    opb   <= {1'b0, opb[7:1]};
                    carry <= (op_r[1] == 1'b0) ? cout : 1'b0;
