{"cti_reasoning":"With armed=1, active_cnt=1 and active=16'h0003, the property holds because sched_idle is false. The invariant fails because two active bits are set while the counter says one. With step, enq_valid and cfg_we all low the scheduler can sit here indefinitely. A single step then dispatches queue 0 (lowest vtime, index 0), whose backlog is 1, so active[0] clears and active_cnt drops to 0. The next state has sched_idle and backlogged both true, which violates P.","cti_state":[{"signal":"armed","value":"1'b1"},{"signal":"active","value":"16'h0003"},{"signal":"active_cnt","value":"5'd1"},{"signal":"backlog","value":"256'h00000000000000000000000000000000000000000000000000000000_00010001"},{"signal":"vtime","value":"256'd0"},{"signal":"weight","value":"256'h0001000100010001000100010001000100010001000100010001000100010001"},{"signal":"gvt","value":"16'd0"}],"invariants":["active_cnt == {4'd0,active[0]} + {4'd0,active[1]} + {4'd0,active[2]} + {4'd0,active[3]} + {4'd0,active[4]} + {4'd0,active[5]} + {4'd0,active[6]} + {4'd0,active[7]} + {4'd0,active[8]} + {4'd0,active[9]} + {4'd0,active[10]} + {4'd0,active[11]} + {4'd0,active[12]} + {4'd0,active[13]} + {4'd0,active[14]} + {4'd0,active[15]}"],"verilog":"module wfq_sched16 (
    input  wire        clk,
    input  wire        step,
    input  wire        enq_valid,
    input  wire [3:0]  enq_q,
    input  wire        cfg_we,
    input  wire [3:0]  cfg_q,
    input  wire [15:0] cfg_weight,
    output wire        enq_ready,
    output wire        backlogged,
    output wire [3:0]  grant_q,
    output wire        sched_idle
);
    // scheduling state array: 16 queues x 16-bit virtual time / weight / backlog
    reg [255:0] vtime;
    reg [255:0] weight;
    reg [255:0] backlog;
    reg [15:0]  active;
    reg [4:0]   active_cnt;
    reg [15:0]  gvt;
    reg         armed;

    initial begin
        vtime      = 256'd0;
        weight     = {16{16'd1}};
        backlog    = 256'd0;
        active     = 16'd0;
        active_cnt = 5'd0;
        gvt        = 16'd0;
        armed      = 1'b0;
    end

    // weighted fair selection: active queue with smallest virtual time
    reg [3:0]  sel;
    reg [15:0] best_vt;
    reg        found;
    integer j;
    always @(*) begin
        found = 1'b0;
        sel = 4'd0;
        best_vt = 16'd0;
        for (j = 0; j < 16; j = j + 1)
            if (active[j] && (!found || vtime[j*16 +: 16] < best_vt)) begin
                found = 1'b1;
                sel = j[3:0];
                best_vt = vtime[j*16 +: 16];
            end
    end

    wire [15:0] sel_backlog = backlog[sel*16 +: 16];
    wire [15:0] sel_weight  = weight[sel*16 +: 16];
    wire [15:0] enq_backlog = backlog[enq_q*16 +: 16];
    wire [15:0] enq_vt      = vtime[enq_q*16 +: 16];

    wire dispatch = step && (active != 16'd0);
    wire do_enq   = enq_valid && !step && (enq_backlog != 16'hFFFF);

    always @(posedge clk) begin
        if (cfg_we)
            weight[cfg_q*16 +: 16] <= cfg_weight;
        if (dispatch) begin
            armed <= 1'b1;
            gvt <= best_vt;
            vtime[sel*16 +: 16] <= best_vt + sel_weight;
