                        st  <= S_IDENT;
                        len <= 3'd1;
                    end else if (cls == 2'd2) begin
                        st  <= S_NUM;
                        len <= 3'd1;
                    end else if (cls == 2'd3) begin
                        st  <= S_STR;
                        len <= 3'd0;
                    end else begin
                        st  <= S_IDLE;
                        len <= 3'd0;
