{"cti_reasoning": "The state 5'b00101 (IDLE and TXPRE bits both set) satisfies P because the decoded owners are radio_tx=1 and radio_rx=0, so they are never simultaneously asserted; it violates R because two one-hot bits are set instead of exactly one. With step low the FSM sits there forever, and one step with rx_start=1 makes nxt[1]=IDLE&rx_start=1 and nxt[3]=TXPRE=1, giving 5'b01010 where radio_rx (RX bit) and radio_tx (TX bit) are both asserted, breaking P.", "cti_state": [{"signal": "state", "value": "5'b00101"}, {"signal": "step", "value": "1'b1"}, {"signal": "rx_start", "value": "1'b1"}, {"signal": "tx_req", "value": "1'b0"}, {"signal": "rst", "value": "1'b0"}], "invariants": ["state == 5'b00001 || state == 5'b00010 || state == 5'b00100 || state == 5'b01000 || state == 5'b10000"], "verilog": "module wifi_radio_owner_fsm (
    input  wire clk,
    input  wire rst,
    input  wire step,      // idle/enable: low freezes all state
    input  wire rx_start,  // preamble detected by the receiver
    input  wire tx_req,    // MAC wants the air for a frame
    output wire radio_tx,  // transmit chain owns the radio
    output wire radio_rx   // receive chain owns the radio
);
    // one-hot MAC air-interface FSM:
    //   bit0 = IDLE, bit1 = RX_FRAME, bit2 = TX_PREAMBLE,
    //   bit3 = TX_DATA, bit4 = ACK_WAIT
    reg [4:0] state;
    initial state = 5'b00001;

    wire s_idle  = state[0];
    wire s_rx    = state[1];
    wire s_txpre = state[2];
    wire s_tx    = state[3];
    wire s_ackw  = state[4];

    // next-state as a per-bit OR of its legal source states
    wire [4:0] nxt;
    assign nxt[0] = (s_idle & ~rx_start & ~tx_req) | s_rx | s_ackw;
    assign nxt[1] = s_idle & rx_start;                 // RX wins the air
