    initial gnt_idx   = 2'd0;
    initial timer     = 3'd0;
    initial elapsed   = 3'd0;

    always @(posedge clk) begin
        if (rst) begin
            gnt_valid <= 1'b0;
            gnt_idx   <= 2'd0;
            timer     <= 3'd0;
            elapsed   <= 3'd0;
        end else if (i_ce) begin
            if (!gnt_valid) begin
                if (enc_valid) begin
                    gnt_valid <= 1'b1;
                    gnt_idx   <= enc_idx;
                    timer     <= BUDGET;   // credits left
                    elapsed   <= 3'd0;     // cycles burnt
