            skid     <= 8'h00;
            skid_par <= 1'b0;
            o_valid  <= 1'b0;
            o_data   <= 8'h00;
            o_par    <= 1'b0;
            win      <= 1'b0;
            acc_data <= 8'h00;
            acc_par  <= 1'b0;
