    // one-hot phase FSM:
    //   st[0]      IDLE
    //   st[1]      START bit
    //   st[2..9]   data bits D0..D7 (one state per bit)
    //   st[10]     STOP bit / byte parked
    reg [10:0] st;
    reg [3:0]  nbits;   // frame phase index: 0..10 only, though 4 bits hold 15
    reg [7:0]  sr;
    reg        ferr;
    reg        pv;

    initial st    = 11'b000_0000_0001;
    initial nbits = 4'd0;
    initial sr    = 8'h00;
    initial ferr  = 1'b0;
    initial pv    = 1'b0;

    wire idle   = st[0];
    wire startb = st[1];
    wire datab  = |st[9:2];
    wire stopb  = st[10];

