        nxt[3]   = st[2];
        nxt[4]   = st[3];
        nxt[5]   = st[4];
        nxt[6]   = st[5];
        nxt[7]   = st[6];
        nxt[8]   = st[7];
        nxt[9]   = st[8];
        nxt[10]  = st[9] || (st[10] && !take);
