    // so whenever the high-occupancy flag rises it rises to exactly three.
    always @(posedge clk)
        if (pv && $rose(occ_hi))
            assert (ones == 3'd3);
endmodule", "top_module": "gray_quantum_counter", "clock": "clk", "antecedents": ["$rose(occ_hi)"], "sanity_covers": ["ones == 3'd3", "bin == 4'd9"]}

{"cti_reasoning": "The state lfsr=0 (the LFSR all-zeros lockup) with credit=used=0 satisfies both assertions, since gnt_a, gnt_b, f_full and f_empty are all low, but it violates R (lfsr must be nonzero and credit+used must equal 4). With ce low the design sits in that state forever; one step with ce high drives gnt_a and gnt_b both high (the lock path) and, because both credit and used are zero, also latches f_full and f_empty high, so both assertions fail in the next state.", "cti_state": [{"signal": "lfsr", "value": "4'b0000"}, {"signal": "credit", "value": "3'd0"}, {"signal": "used", "value": "3'd0"}, {"signal": "gnt_a", "value": "1'b0"}, {"signal": "gnt_b", "value": "1'b0"}, {"signal": "f_full", "value": "1'b0"}, {"signal": "f_empty", "value": "1'b0"}, {"signal": "armed", "value": "1'b1"}], "invariants": ["lfsr != 4'd0", "credit <= 3'd4", "used <= 3'd4", "credit + used == 3'd4"], "verilog": "module lfsr_token_arbiter (
    input  wire clk,
    input  wire ce,
    output wire o_gnt_a,
    output wire o_gnt_b,
    output wire o_full,
    output wire o_empty
);
    // maximal-length 4-bit LFSR (x^4 + x^3 + 1): cycles through all 15
    // nonzero states, so the all-zeros lockup state is never entered.
    reg [3:0] lfsr;
    reg       gnt_a, gnt_b;
    reg [2:0] credit, used;
    reg       f_full, f_empty;
    reg       armed;

    initial begin
        lfsr    = 4'h1;
        gnt_a   = 1'b0;
        gnt_b   = 1'b0;
        credit  = 3'd4;
        used    = 3'd0;
        f_full  = 1'b0;
        f_empty = 1'b1;
        armed   = 1'b0;
    end

    wire       fb   = lfsr[3] ^ lfsr[2];
    wire [3:0] nxt  = {lfsr[2:0], fb};
