    assign o_gnt_b = gnt_b;
    assign o_full  = f_full;
    assign o_empty = f_empty;

    // P1: two grants are never asserted together, once the arbiter has been armed
    always @(posedge clk)
        if (armed)
            assert (!(gnt_a && gnt_b));

    // P2: the full and empty flags are never asserted together, once armed
    always @(posedge clk)
        if (armed)
            assert (!(f_full && f_empty));
endmodule", "top_module": "lfsr_token_arbiter", "clock": "clk", "antecedents": ["armed"], "sanity_covers": ["armed", "armed && credit == 3'd2"]}

{"cti_reasoning": "In state S the occupancy register nact already holds 4 so the guarded property (heating implies nact <= 4) is satisfied, and the stored parity matches the stored zone mask so no fault is flagged; S violates R because nact does not equal the population count of zone (1) and because budget+nact is 7 instead of 4. With i_ce low the design sits in S forever, and one cycle with i_ce high, i_temp below T_LOW and i_zone=1 turns on an idle zone (budget is non-zero so the grant fires), pushing nact to 5 while zone stays non-zero, so the property fails.", "cti_state": [{"signal": "zone", "value": "8'h01"}, {"signal": "zpar", "value": "1'b1"}, {"signal": "nact", "value": "4'd4"}, {"signal": "budget", "value": "4'd3"}], "invariants": ["zpar == (^zone)", "nact == ({3'b000,zone[0]} + {3'b000,zone[1]} + {3'b000,zone[2]} + {3'b000,zone[3]} + {3'b000,zone[4]} + {3'b000,zone[5]} + {3'b000,zone[6]} + {3'b000,zone[7]})", "({1'b0,budget} + {1'b0,nact}) == 5'd4"], "verilog": "// Multi-zone thermostat front end with hysteresis and a power budget.
// The active-zone mask is a parity protected register slice; a maintained
// occupancy counter and a remaining-budget counter track it.
module zone_heat_budget (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,      // idle when low: all state frozen
    input  wire [2:0] i_zone,    // zone under consideration this cycle
    input  wire [7:0] i_temp,    // measured temperature of that zone
    output wire       o_fault,   // parity mismatch on the zone slice
    output wire [3:0] o_nact,
    output wire [3:0] o_budget
