    wire do_off = req_off &&  zone[i_zone];

    always @(posedge i_clk) begin
        if (i_rst) begin
            zone   <= 8'h00;
            zpar   <= 1'b0;
            nact   <= 4'd0;
            budget <= BUDGET;
        end else if (do_on) begin
            zone[i_zone] <= 1'b1;
            zpar         <= ~zpar;      // one data bit flips, parity flips
            nact         <= nact + 4'd1;
            budget       <= budget - 4'd1;
        end else if (do_off) begin
            zone[i_zone] <= 1'b0;
            zpar         <= ~zpar;
            nact         <= nact - 4'd1;
            budget       <= budget + 4'd1;
