endmodule", "top_module": "zone_heat_budget", "clock": "i_clk", "antecedents": ["heating"], "sanity_covers": ["heating && nact == 4'd4", "heating && nact == 4'd2", "budget == 4'd0"]}

{"cti_reasoning": "The state phase=1 (req asserted, ack not yet seen) with idle_r still 1 satisfies P because busy_r is 0, but it violates R, whose clause idle_r == (phase == 2'd0) forces idle_r low outside the idle phase; the design can sit here forever with i_ce low, and one step with slave_ack asserted moves phase 1->2 which sets busy_r to 1 while idle_r remains 1, so P (never both idle and busy) fails in the next state.", "cti_state": [{"signal": "phase", "value": "2'd1"}, {"signal": "req_r", "value": "1'b1"}, {"signal": "ack_r", "value": "1'b0"}, {"signal": "idle_r", "value": "1'b1"}, {"signal": "busy_r", "value": "1'b0"}], "invariants": ["req_r == (phase == 2'd1 || phase == 2'd2)", "ack_r == (phase == 2'd2 || phase == 2'd3)", "idle_r == (phase == 2'd0)", "busy_r == (phase == 2'd2 || phase == 2'd3)"], "verilog": "// Four-phase request/acknowledge handshake between a driver and a
// peripheral service unit, with separate idle and busy status flags.
module fourphase_handshake (
    input  wire clk,
    input  wire rst,
    input  wire i_ce,        // global enable / idle condition
    input  wire start,       // driver wants to open a transaction
    input  wire slave_ack,   // peripheral raises acknowledge
    input  wire slave_drop,  // peripheral releases acknowledge
    output wire o_req,
    output wire o_ack,
    output wire o_idle,
    output wire o_busy
);
    // phase encoding:
    //   0 : IDLE      req=0 ack=0
    //   1 : REQ       req=1 ack=0
    //   2 : ACK       req=1 ack=1
    //   3 : DROP      req=0 ack=1   (req may only fall after ack has risen)
    reg [1:0] phase;
    reg       req_r;
    reg       ack_r;
    reg       idle_r;
    reg       busy_r;

    initial begin
        phase  = 2'd0;
        req_r  = 1'b0;
        ack_r  = 1'b0;
        idle_r = 1'b1;
        busy_r = 1'b0;
    end

    always @(posedge clk) begin
        if (rst) begin
            phase  <= 2'd0;
            req_r  <= 1'b0;
            ack_r  <= 1'b0;
            idle_r <= 1'b1;
            busy_r <= 1'b0;
        end else if (i_ce) begin
            case (phase)
                2'd0: begin
                    // leave idle only by raising req; idle flag drops here
                    if (start) begin
                        phase  <= 2'd1;
                        req_r  <= 1'b1;
                        idle_r <= 1'b0;
                    end
                end
                2'd1: begin
                    // peripheral acknowledges; service becomes busy
                    if (slave_ack) begin
                        phase  <= 2'd2;
                        ack_r  <= 1'b1;
                        busy_r <= 1'b1;
                    end
                end
                2'd2: begin
                    // req is allowed to fall now that ack is high
                    phase <= 2'd3;
                    req_r <= 1'b0;
                end
                default: begin
                    // peripheral releases ack, transaction closes
                    if (slave_drop) begin
                        phase  <= 2'd0;
                        ack_r  <= 1'b0;
                        busy_r <= 1'b0;
                        idle_r <= 1'b1;
                    end
                end
            endcase
        end
    end

    assign o_req  = req_r;
    assign o_ack  = ack_r;
    assign o_idle = idle_r;
    assign o_busy = busy_r;

    // P: the service unit is never reported idle and busy at the same time.
    always @(*)
        assert (!(idle_r && busy_r));
