    // Bounded response (safety form), scoped after the first accepted burst:
    // the deadline never expires while credits are still outstanding.
    always @(*)
        assert (!armed || !((timer == 4'd0) && (outst != 4'd0)));
endmodule", "top_module": "credit_window", "clock": "clk", "antecedents": ["armed"], "sanity_covers": ["armed && outst == 4'd4", "armed && outst == 4'd3", "armed && timer == 4'd9"]}

{"cti_reasoning": "The state cnt=4, duty=5, high_cnt=3 satisfies both assertions (3<=5, and pwm_out=(4<5)=1 matches (3<5)=1) but violates R because high_cnt must equal min(cnt,duty)=4; with i_ce low the design sits in this state forever, and one enabled step advances cnt to 5 and high_cnt to 4, where pwm_out=(5<5)=0 while (4<5)=1, so the second assertion fails. (The first assertion is likewise non-inductive alone: cnt=1, duty=3, high_cnt=3 satisfies high_cnt<=duty, idles, and one step makes high_cnt=4>duty.)", "cti_state": [{"signal": "cnt", "value": "4'd4"}, {"signal": "duty", "value": "4'd5"}, {"signal": "high_cnt", "value": "4'd3"}, {"signal": "armed", "value": "1'b1"}, {"signal": "i_ce", "value": "1'b0 while idling, 1'b1 on the violating step"}, {"signal": "rst", "value": "1'b0"}], "invariants": ["cnt <= 4'd11", "duty <= 4'd12", "high_cnt == ((cnt < duty) ? cnt : duty)"], "verilog": "// PWM channel for a wire-logic accelerator block.
// Period counter walks 0..PER-1, duty is double buffered at the period edge,
// and high_cnt accumulates the number of high cycles elapsed in the period.
module pwm_channel (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // idle when low: no state changes at all
    input  wire       i_load,
    input  wire [3:0] i_duty,
    output wire       pwm_out,
    output reg        armed
