    reg [7:0] latch;

    initial state  = S_IDLE;
    initial latch  = 8'h00;
    initial o_data = 8'h00;
    initial o_rd   = 1'b0;
    initial o_wr   = 1'b0;
    initial busy   = 1'b0;   // window register: set by start, cleared at FLUSH

    always @(posedge clk) begin
        if (ce) begin
            case (state)
                S_IDLE: begin
                    o_rd <= start;
                    o_wr <= 1'b0;
