    reg  [3:0] wcnt  = 4'd0;   // words written into the writer half
    reg  [3:0] ttl   = 4'd0;   // countdown to the completion deadline
    reg  [3:0] rcnt  = 4'd0;   // reader index into its half
    reg        rvld  = 1'b0;   // reader half holds a complete frame
    reg        err_r = 1'b0;   // deadline expired while still outstanding

    reg  [7:0] mem0 [0:7];
    reg  [7:0] mem1 [0:7];

    integer i;
    initial begin
        for (i = 0; i < 8; i = i + 1) begin
            mem0[i] = 8'd0;
            mem1[i] = 8'd0;
        end
    end

    wire accept  = ce && start && !busy;
    wire wstep   = ce && busy;
    wire wlast   = wstep && (wcnt == 4'd7);
    wire expired = wstep && (ttl == 4'd0);

    assign rdata = rsel ? mem1[rcnt[2:0]] : mem0[rcnt[2:0]];
    assign err   = err_r;

    // data path: writer only ever touches half `sel`
    always @(posedge clk) begin
        if (wstep) begin
            if (sel) mem1[wcnt[2:0]] <= wdata;
            else     mem0[wcnt[2:0]] <= wdata;
        end
    end

    // control path
    always @(posedge clk) begin
