            busy <= 1'b1;
            wcnt <= 4'd0;
            ttl  <= DEPTH;
        end else if (wlast) begin
            busy <= 1'b0;
            wcnt <= 4'd0;
            ttl  <= 4'd0;
            sel  <= ~sel;      // writer swaps to the other half
            rsel <= sel;       // reader takes over the half just filled
            rcnt <= 4'd0;
            rvld <= 1'b1;
