    initial begin
        bin     = 4'b0000;
        gptr    = 4'b0000;
        s1      = 4'b0000;
        s2      = 4'b0000;
        prev_s2 = 4'b0000;
        bs1     = 4'b0000;
        bs2     = 4'b0000;
        bs3     = 4'b0000;
