{"cti_reasoning":"The state S = {state=DEVELOP(one-hot bit3), saw_expose=0, saw_develop=0, armed=1} satisfies both assertions vacuously (the FSM is in neither ETCH nor DONE), but it violates the invariant that any state at or past DEVELOP must already have recorded the EXPOSE visit; with step low the FSM sits in DEVELOP forever, and one step with step high moves it to ETCH while saw_expose stays 0, breaking the first assertion (the symmetric state ETCH with saw_develop=0 breaks the second one step later).","cti_state":[{"signal":"state","value":"6'b001000"},{"signal":"saw_expose","value":"1'b0"},{"signal":"saw_develop","value":"1'b0"},{"signal":"armed","value":"1'b1"}],"invariants":["state == 6'b000001 || state == 6'b000010 || state == 6'b000100 || state == 6'b001000 || state == 6'b010000 || state == 6'b100000","!(state[3] || state[4] || state[5]) || saw_expose","!(state[4] || state[5]) || saw_develop"],"verilog":"// One-hot process-step sequencer for a lithography/etch cell.
// Exactly one state bit is ever set; transitions are legal only from
// specific states.  Shadow registers record that earlier process steps
// really happened, and a sticky arm register remembers the first LOAD.
module litho_step_fsm (
    input  wire clk,
    input  wire rst,
    input  wire step,        // global enable / idle condition
    input  wire i_start,
    input  wire i_dose_ok,
    input  wire i_ack,
    output wire o_busy,
    output wire o_done
);
    localparam S_IDLE    = 0;
    localparam S_LOAD    = 1;
    localparam S_EXPOSE  = 2;
    localparam S_DEVELOP = 3;
    localparam S_ETCH    = 4;
    localparam S_DONE    = 5;

    reg [5:0] state;
    initial   state = 6'b000001;

    // shadow registers: earlier-event recorders
    reg saw_expose;
    reg saw_develop;
    initial saw_expose  = 1'b0;
    initial saw_develop = 1'b0;

    // sticky scope arm: set the first time a wafer is LOADed, never cleared
    reg armed;
    initial armed = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            state       <= 6'b000001;
            saw_expose  <= 1'b0;
            saw_develop <= 1'b0;
        end else if (step) begin
            case (1'b1)
                state[S_IDLE]: begin
                    if (i_start) begin
                        state       <= 6'b000010; // LOAD
                        saw_expose  <= 1'b0;      // fresh wafer
                        saw_develop <= 1'b0;
                    end
                end
                state[S_LOAD]: begin
                    state <= 6'b000100;           // EXPOSE
                end
                state[S_EXPOSE]: begin
                    if (i_dose_ok) begin
                        state      <= 6'b001000;  // DEVELOP
                        saw_expose <= 1'b1;       // exposure really completed
                    end
                end
                state[S_DEVELOP]: begin
                    state       <= 6'b010000;     // ETCH
                    saw_develop <= 1'b1;          // develop really completed
                end
                state[S_ETCH]: begin
                    state <= 6'b100000;           // DONE
                end
                state[S_DONE]: begin
                    if (i_ack)
                        state <= 6'b000001;       // IDLE
                end
                default: begin
                    state <= 6'b000001;
                end
            endcase
        end
    end

    always @(posedge clk) begin
        if (rst)
            armed <= 1'b0;
        else if (state[S_LOAD])
            armed <= 1'b1;
    end

    assign o_busy = ~state[S_IDLE];
    assign o_done = state[S_DONE];

    // Precedence, in the "after first LOAD" scope:
    // reaching ETCH requires a completed EXPOSE, reaching DONE a completed DEVELOP.
    always @(*) begin
        if (armed && state[S_ETCH])
            assert (saw_expose);
        if (armed && state[S_DONE])
            assert (saw_develop);
    end
endmodule","top_module":"litho_step_fsm","clock":"clk","antecedents":["armed","state[4]","state[5]"],"sanity_covers":["armed && state[4]","armed && state[5]"]}

